COLLDATA("asabahur","ur",[[7541,"§۸۹۱۹ ۔ ہانی بن جزء\nبن نعمان مرادی تطبیعی، ان کے بھائی نعمان کے سوانح میں گزر چکا ہے کہ انہیں شرف صحابیت حاصل ہے، وہ فتح مصر میں شریک تھے۔"],[7542,"§۸۹۲۰ ۔ ہانئ بن حارث\n(1) بن جبلہ ابن حجر بن شرحبیل بن حارث بن عدی بن ربیعہ بن معاویہ کندی، ہشام بن کلبی کا قول ہے: وفد کے ساتھ نبی کریم صلی اللہ علیہ وسلم کے پاس آئے۔","",{"fn":"(1) تجرید (۱۱۶/۲)"}],[7543,"§۸۹۲۱ ۔ ہانئ بن حبیب داری\n(1) واقدی نے تمیم داری کے ساتھ نبی کریم صلی اللہ علیہ وسلم کے پاس آنے والے داربین میں ان کا ذکر کیا ہے، نعیم بن اوس کے سوانح میں ان کا ذکر گزر چکا ہے۔ رشاطی کا قول ہے: تمیم داری کے ساتھ داربین کے وفد میں آئے، نبی کریم صلی اللہ علیہ وسلم کے لیے سونوں کے پتروں سے مزین ایک قبا کا ہدیہ لایا، آپ صلی اللہ علیہ وسلم نے اسے سیدنا عباس رضی اللہ عنہ کو عطا فرمایا، انہوں نے ایک یہودی کو آٹھ ہزار میں فروخت کر دیا۔","",{"fn":"(1) تجرید (۱۱۶/۲)"}],[7544,"§۸۹۲۲ ۔ ہانئ بن حجر\n(1) بن معاویہ بن جبلہ بن عدی بن ربیعہ بن معاویہ اکرمین کندی، ابن کلبی اور ابن سعد کا قول ہے: نبی کریم صلی اللہ علیہ وسلم کے پاس وفد کے ساتھ آئے۔ ہانی کی اولاد میں سے ولید بن عدی بن ہانی ہیں، ابن کلبی کا قول ہے: اسلامی شاعر ہیں۔","",{"fn":"(1) تجرید (۱۱۶/۲)"}],[7545,"§۸۹۲۳ ۔ ہانئ بن عدی\n(1) بن معاویہ بن جبلہ کندی، حجر بن عدی کے بھائی ہیں، ابن کلبی نے ذکر کیا ہے کہ وفد میں نبی کریم صلی اللہ علیہ وسلم کے پاس آئے۔","",{"fn":"(1) تجرید (۱۱۶/۲)"}],[7546,"§۸۹۲۲ ۔ ہانئ بن عمرو\nابو شریح خزاعی، طبری نے ان کا نام لیا ہے، مشہور یہ ہے کہ ان کا نام خویلد ہے۔"],[7547,"§۸۹۲۵ ۔ ہانی بن فراس اسلمی\n(1) ابو عمر(2) کا قول ہے، درخت کے نیچے بیعت کرنے والوں میں سے ہیں، ان سے مجزأۃ بن زاہر نے روایت کیا، ابن مندہ کا قول ہے، ھانی بن فراس اشجعی، اہل کوفہ میں سے ہیں۔ بیمار ہوئے اور اپنے گھٹنے کے نیچے تکیہ رکھنے لگے، اسے اسرائیل نے بحوالہ مجزرۃ بن زاہر روایت کیا ہے۔ میں کہتا ہوں: بخاری نے یہ بطریق مجزأۃ بحوالہ آبان بن اوس نقل کیا ہے۔ واللہ اعلم۔","",{"fn":"(1) استیعاب (۲۶۹۷)\n(2) استیعاب (۹۶/۴)"}],[7548,"§۸۹۲۶ ۔ ہانئ بن مالک ہمدانی\n(1) شام میں فروکش ہوئے، ابو مالک، خالد بن یزید بن ابو مالک کے دادا ہیں۔ ابو حاتم(2) کا قول ہے: انہیں شرف صحابیت حاصل ہے۔ ابن مندہ نے نقل کیا ہے کہ بخاری نے کہا: ان کے صحابی ہونے میں اختلاف ہے، ابن حبان کا قول ہے: یمن میں سے نبی کریم صلی اللہ علیہ وسلم کے پاس وفد میں آئے، پھر اسلام لے آئے، دمشق میں ۶۸ھ میں وفات پائی۔ بخاری(3) نے تاریخ میں اور طبرانی اور خطیب(4) نے بطریق سلیمان بن عبدالرحمن، بحوالہ خالد بن یزید(5) بن ابی مالک، عن ابیہ عن جدہ نقل کیا ہے کہ وہ نبی کریم صلی اللہ علیہ وسلم کے پاس یمن سے وفد میں آئے۔ آپ نے انہیں اسلام کی دعوت دی، وہ اسلام لائے، آپ صلی اللہ علیہ وسلم نے ان کے سر پر ہاتھ پھیرا اور ان کے لیے برکت کی دُعا کی، انہیں یزید بن ابوسفیان کے پاس ٹھہرایا، جب سیدنا ابوبکر رضی اللہ عنہ نے شام کی طرف لشکر بھیجا تو وہ ان کے ساتھ نکلے، پھر واپس نہیں لوٹے، خطیب کا قول ہے: ابوسلیمان اسے روایت کرنے میں تنہا ہیں۔","",{"fn":"(1) تجرید (۱۱۶/۲)\n(2) الجرح والتعدیل (۱۰۰/۹)\n(3) تاریخ کبیر (۲۲۸/۴، ۲۲۹)\n(4) معجم الکبیر (۵۲۳/۲۲)\n(5) اسد الغابہ (۵۳۳۱)"}],[7549,"§۸۹۲۷ ۔ ہانئ بن ہانئ\nذہبی نے تجرید میں ان کا ذکر کیا ہے، فرماتے ہیں: مسند بقی بن مخلد میں ان کی چار(۴) احادیث ہیں۔ مجھے خدشہ ہے کہ وہ ھانی بن ھانی ہیں۔ جنہوں نے سیدنا علی، عمار سے روایت کی، قسم ثالث میں ان شاء اللہ میں ان کا ذکر کروں گا۔"],[7550,"§۸۹۲۸ ۔ ہانئ بن ہبیرہ\n(1) بن ابو وہب قرشی مخزومی، ان کے والد فتح مکہ کے بعد حالت کفر میں فوت ہوئے، وہ ام ھانی بنت ابوطالب کے شوہر ہیں، جو سیدنا علی رضی اللہ عنہ کی بہن ہے، ان سے بھی ان کی کنیت ہے، ان کے نام میں اختلاف ہے جیسا کہ خواتین کے حالات میں آئے گا۔ زبیر نے بیان کیا ہے کہ ام ہانی کے ہاں بہیرہ سے ھانی، یوسف اور جعدہ کی ولادت ہوئی، ابن سعد(2) نے نقل کیا ہے کہ اسلام نے ان کے اور بہیرہ کے درمیان جدائی کر دی، جب فتح مکہ ہوا تو ہبیرہ بھاگ گیا، اس کے بعد حالت کفر میں فوت ہو گیا، اس سے ان کے ہاں ھانی، جعدہ، عمر اور یوسف پیدا ہوئے۔ انہوں نے بطریق اسماعیل سدی بحوالہ ابو صالح مولی ام ھانی نقل کیا ہے۔ فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم نے ام ھانی کو نکاح کا پیغام دیا، انہوں نے کہا: میں بیوہ ہوں اور میرے بچے چھوٹے ہیں، جب ان کے بیٹے بڑے ہو گئے تو انہوں نے نبی کریم صلی اللہ علیہ وسلم پر اپنا نفس پیش کیا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اب نہیں\"۔ کیونکہ اللہ تعالیٰ نے یہ آیت نازل کی ہے(3) جنہوں نے آپ کے ساتھ ہجرت کی ہے(4)۔ انہوں نے ہجرت نہیں کی۔","",{"fn":"(1) اسد الغابہ (۵۳۳۲) تجرید (۱۱۷/۲)\n(2) طبقات الکبریٰ (۱۰۹/۸)\n(3) سورہ الاحزاب الآیۃ (۵۰)\n(4) کنز العمال (۳۵۵۰۱)"}],[7551,"§۸۹۲۹ ۔ ہانی بن نیارہ\n(1) بن عمرو بن عبید بن کلاب بن دہمان بن غنم بن دینار بن تمیم بن کابل بن ذبل بن بلی بلوی، ابو بردہ بن نیار ہیں جو انصار کے حلیف ہیں، براء بن عازب کے ماموں ہیں، اپنی کنیت سے مشہور ہیں، کنیتوں میں ان کا ذکر آئے گا، بعض کا قول ہے: ان کا نام حارث ہے، ایک قول ہے: مالک ہے، پہلا قول مشہور ہے۔","",{"fn":"(1) استیعاب (۲۷۰۰) تجرید (۱۳/۲)"}],[7552,"§۸۹۳۰ ۔ ہانئ بن یزید\nبن نہیک ندجی، بعض کا قول ہے، نخعی، شریح کے والد ہیں، امام احمد نے اور امام بخاری نے ادب المفرد(1) میں ان کی حدیث نقل کی ہے، ابوداؤد، نسائی(2) نے بطریق یزید بن مقدام بن شریح بن ھانی عن ابیہ عن جدہ، عن ابی ھانی، اسے نقل کیا ہے، اس میں سے وہ روایت ہے جسے ابو داؤد(3) نے ان کے حوالے سے نقل کیا ہے کہ جب وہ وفد میں اپنی قوم کے ساتھ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے تو دیکھا کہ لوگ انہیں ابوالحکم کی کنیت سے پکار رہے ہیں، آپ صلی اللہ علیہ وسلم نے انہیں بلایا اور فرمایا: \"اللہ تعالی کا حکم ہے تم ابو حکم کنیت نہ رکھو۔\" انہوں نے عرض کیا: \"میری کنیت ابوالحکم اس وجہ سے ہے کہ میری قوم جب کسی چیز میں اختلاف کرتی ہے تو میرے پاس آتی ہے، میں ان کے درمیان فیصلہ کرتا ہوں تو دونوں فریق راضی ہو جاتے ہیں۔\" آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ بہت اچھا ہے، تمہارے کتنے بیٹے ہیں؟\" انہوں نے کہا: \"شریح، مسلم اور عبد اللہ۔\" آپ صلی اللہ علیہ وسلم نے پوچھا: \"ان میں سے بڑا کون ہے؟\" انہوں نے کہا: \"شریح۔\" آپ صلی اللہ علیہ وسلم نے فرمایا: \"تم ابو شریح ہو۔\" ابن ابی شیبہ(4) کے ہاں بحوالہ یزید بن مقدام اس سند سے مروی ہے، میں نے کہا: یا رسول اللہ! مجھے ایسی چیز بتائیے جو میرے لیے جنت واجب کر دے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اچھی گفتگو اور کھانا کھلانا۔\"","",{"fn":"(1) ادب المفرد (۸۱۱)\n(2) نسائی (۵۳۸۷)\n(3) ابوداؤد (۴۹۵۵)\n(4) مصنف ابن ابی شیبہ (۵۱۹/۸)"}],[7553,"§۸۹۳۱ ۔ ہانی مخزومی\nابومخزوم، ابن سکن کا قول ہے، بعض نے کہا: انہوں نے جاہلیت کا زمانہ پایا اور بطریق یعلی بن عمران بجلی نقل کیا ہے کہ مجھے مخزوم بن ھانی مخزومی نے بحوالہ اپنے والد بتایا، ان کی عمر ایک سو پچاس(۱۵۰) برس تھی، فرماتے ہیں: جب نبی کریم صلی اللہ علیہ وسلم کی ولادت کی رات آئی تو کسری کا ایوان تھر تھرانے لگا، اس میں سے چودہ(۱۴) کنگرے گر گئے، بحیرہ ساوہ کا پانی کم ہو گیا۔.... (الحدیث) ابن اثیر کا قول ہے: ابو ولید بن دباغ نے ابن عبدالبر کی کتاب پر اپنے استدراک میں صحابہ میں ان کا ذکر کیا ہے، اس حدیث میں ایسی کوئی شے نہیں جو ان کے صحابی ہونے پر دلالت کرے۔ میں کہتا ہوں: اگر وہ مخزومی ہیں تو فتح کے بعد قریش میں سے جو نبی کریم صلی اللہ علیہ وسلم کے بعد زندہ رہا وہ حجۃ الوداع میں شریک ہوا ہے۔"],[7554,"§۸۹۳۲ ۔ ہبار بن اسود\n(1) بن مطلب بن اسد بن عبد العزیٰ بن قصی قرشی اسدی، ان کی والدہ فاختہ بنت عامر بن قرطہ قشیریہ ہیں، حزن اور ہبیرہ ان کے ماں شریک بھائی ہیں جو ابو وہب کے بیٹے اور مخزومی ہیں۔ ابن اسحاق(2) نے مغازی میں بحوالہ ابو ہریرہ نقل کیا ہے، فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم نے لشکر بھیجا، میں ان میں تھا، پھر ہم سے فرمایا: \"اگر تم ہبار بن اسود، نافع بن قیس پر قابو پالو، تو ان دونوں کو آگ میں جلا دینا\"۔ یہاں تک کہ اگلا دن ہوا تو ہماری طرف پیغام بھیجا۔ \"میں نے تمہیں ان آدمیوں کو پکڑ کر جلانے کا حکم دیا تھا، پھر میں نے دیکھا کہ سوائے اللہ کے کسی کے لیے مناسب نہیں کہ وہ آگ میں جلانے کی سزا دے۔\" اسے ابن سکن نے بطریق ابن اسحاق نقل کیا ہے، فرماتے ہیں: اسی طرح ابن اسحاق نے روایت کیا ہے۔ اسے لیث نے بحوالہ یزید روایت کیا ہے۔ انہوں نے اس میں ابو اسحاق دوسی کا ذکر نہیں کیا، وہ مجہول ہیں۔ میں کہتا ہوں: لیث کے طریق کو بخاری، ابوداؤد(3)، ترمذی(4)، نسائی  نے نقل کیا ہے۔ اس میں ہبار اور اس کے ساتھی کا نام نہیں لیا۔ عمرو بن حارث نے بحوالہ بکیر ان کی پیروی کی ہے۔ بخاری نے تعلیق میں ان کا ذکر کیا ہے۔ نسائی نے اسے موصولاً نقل کیا ہے۔ اسے محمد بن عثمان بن ابی شیبہ نے اپنی تاریخ میں بطریق عبداللہ بن مبارک بحوالہ بکیر نقل کیا ہے۔ دونوں کا نام لیا ہے۔ لیکن نافع بن عبد عمرو نے فرمایا: ان کو جلانے کے حکم کا سبب یہ تھا جو ابن اسحاق(5) نے سیرۃ میں نقل کیا ہے کہ ہبار بن اسود نے رسول اللہ صلی اللہ علیہ وسلم کی صاحبزادی سیدہ زینب رضی اللہ عنہا کو اس وقت نیزہ مارا جب ان کے شوہر ابو العاص بن ربیع نے انہیں مدینہ بھیجا، وہ گر پڑیں، اس کا قصہ سیرۃ میں مشہور ہے، علی بن حرب نے اپنے فوائد میں ثابت بن قیس نے دلائل میں اور ابودحداح دمشقی نے بھی اپنے فوائد میں، ان سب نے بطریق ابن ابی بیج نقل کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم نے ایک سریہ بھیجا اور فرمایا: \"اگر تم ہبار بن اسود کو پاؤ تو اسے لکڑیوں کے دو گٹھوں کے درمیان رکھ کر جلا دو۔\" سریہ ان تک نہ پہنچا تھا کہ وہ اسلام لے آئے اور مدینہ ہجرت کی، وہ زیادہ گالیاں دینے والے تھے، نبی کریم صلی اللہ علیہ وسلم سے کہا گیا: ہبار کو گالی دی جاتی ہے اور وہ گالی نہیں دیتے، وہ آپ صلی اللہ علیہ وسلم کے پاس آئے آپ صلی اللہ علیہ وسلم نے اس کے پاس کھڑے ہوئے اور کہنے لگے: \"جو تمہیں برا بھلا کہے اسے برا بھلا کہو۔\" تو لوگ انہیں برا بھلا کہنے سے رُک گئے۔\nیہ روایت مرسل ہے، اس میں اس قول کے بارے میں وہم ہے کہ انہوں نے مدینہ کی طرف ہجرت کی، کیونکہ وہ جعرانہ میں اسلام لائے تھے، یہ فتح مکہ کے بعد کا قصہ ہے اور فتح مکہ کے بعد ہجرت نہیں۔ صحیح یہ ہے جو زبیر بن بکار نے کہا: ہبار جب اسلام لائے تو مدینہ آئے لوگ انہیں برا بھلا کہنے لگے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو تمہیں برا بھلا کہے اسے برا بھلا کہو\" تو لوگ انہیں ایسا کہنے سے رُک گئے۔(6)\nابن شاہین(7) نے بطریق عقیل بحوالہ ابن شہاب اسی مفہوم میں مرسل روایت نقل کی ہے، رہا ان کا اسلام لانا تو اسے واقدی نے بطریق سعید بن محمد بن جبیر بن مطعم، عن ابیہ، عن جدہ نقل کیا ہے، فرماتے ہیں: جعرانہ سے واپسی پر میں رسول اللہ صلی اللہ علیہ وسلم کے پاس بیٹھا ہوا تھا کہ رسول اللہ صلی اللہ علیہ وسلم کے دروازے سے ہبار بن اسود آئے، لوگوں نے کہا: یا رسول اللہ! ہبار بن اسود! آپ صلی اللہ علیہ وسلم نے فرمایا: \"میں نے اسے دیکھ لیا ہے۔\" ایک شخص نے اس کی طرف جانے کا ارادہ کیا، نبی کریم صلی اللہ علیہ وسلم نے اسے اشارہ کیا کہ بیٹھ جاؤ، تو ہبار رک گئے اور کہا: السلام علیک یا نبی اللہ، اشہد ان لا الہ الا اللہ و اشہد ان محمدا رسول اللہ۔ میں آپ سے بھاگ کر شہروں میں چلا گیا اور عجمیوں سے مل گیا، پھر مجھے آپ کا لوٹنا، آپ کی صلہ رحمی اور جو آپ سے جہالت کرے اسے دل سے معاف کرنا یاد آیا، اے اللہ کے نبی! ہم شرک کرتے تھے، اللہ تعالیٰ نے ہمیں آپ کے ذریعے ہدایت دی، اور ہمیں ہلاکت سے بچایا، میری جہالت کو اور جو کچھ میری طرف سے آپ کو پہنچا ہے، معاف فرما دیں۔ میں اپنی برائی کا اقرار کرتا ہوں اور اپنے گناہوں کا معترف ہوں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میں نے تمہیں معاف کر دیا، اللہ تمہارے ساتھ اچھا معاملہ کرے، اب جب اس نے تمہیں اسلام کی ہدایت دی ہے، اور اسلام پہلے گناہوں کو معاف کر دیتا ہے۔\" طبرانی(8) نے بطریق ابو معشر بحوالہ بیٹی بن عبد الملک بن ہبار بن اسود عن ابیہ، عن جدہ نقل کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم ہبار بن اسود کے گھر کے پاس سے گزرے اور گانے کی آواز سنی تو فرمایا: \"یہ کیا ہے؟\" لوگوں نے کہا: شادی ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ نکاح ہے زنا نہیں\" حسن بن سفیان نے اپنی مسند میں بطریق عبداللہ بن ابی عبد اللہ بن ہبار بن اسود بحوالہ ان کے والد، عن جدہ اسی مفہوم میں نقل کیا ہے، دونوں اسناد میں ضعف ہے، ابونعیم کا قول ہے: ابو عبد اللہ بن ہبار کا نام عبدالرحمن تھا۔\nمیں کہتا ہوں: اسے بغوی نے بطریق عبد اللہ بن عبد الرحمن بن ہبار اس سند کے ساتھ نقل کیا ہے، لیکن ان کی سند میں علی بن قرین ہیں، محدثین نے ان کی طرف حدیث گھڑنے کی نسبت کی ہے، لیکن خطیب نے موتلف میں بطریق ابراہیم بن محمد بن ابو ثابت نقل کیا ہے، ہمیں یہ عالی سند سے فوائد ابن ابی ثابت میں یہ ان کی روایت سے، ان کی سند سے جو احمد بن سلمہ حرانی تک پہنچتی ہے۔ بحوالہ عبد اللہ بن ہبار عن ابیہ لی ہے، فرماتے ہیں: ہبار(9) نے اپنی بیٹی کا نکاح کیا، اس کے نکاح میں دف بجایا گیا۔.... (الحدیث) اسماعیلی نے معجم الصحابہ میں اور خطیب نے مؤتلف میں اپنے طریق سے نقل کیا ہے، میں نے ان کی تحریر سے نقل کیا ہے، فرماتے ہیں: مجھ سے محمد بن طاہر بن ابی دمیک نے بحوالہ یحیی بن عبد الملک بن ہبار، عن ابیہ نقل کیا ہے۔ فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم علی بن ہبار کے پاس سے گزرے، پھر حدیث کا ذکر کیا، جیسا کہ علی بن ہبار کے سوانح میں گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۳۳۴) استیعاب (۲۷۰۱) تجرید (۱۱۷/۲)\n(2) السیرۃ النبویۃ (۲۲۴/۲)\n(3) بخاری (۳۰۱۷، ۳۰۱۶) ابوداؤد (۲۶۷۳)\n(4) ترمذی (۱۵۷۱)\n(5) السیرۃ النبویۃ (۲۲۴/۲، ۲۲۶/۲)\n(6) مغازی (۸۵۹/۲)\n(7) مغازی (۸۵۸/۲)\n(8) المعجم الکبیر (۲۰۱/۲۲، ۲۰۰) معجم الکبیر (۲۰۱/۲۲)\n(9) مجمع الزوائد (۲۹۰/۴)"}],[7555,"§۸۹۳۳ ۔ ہبار بن سفیان\n(1) بن عبد اسد بن ہلال بن عبداللہ بن عمر بن مخزوم مخزومی، ابو سلمہ بن عبد الاسد کے بھتیجے ہیں، موسیٰ بن عقبہ نے بحوالہ ابن شہاب اور ابو اسود، انہوں نے عروہ اور محمد بن اسحاق سے(2) حبشہ کی طرف ہجرت کرنے والوں میں ان کا ذکر کیا ہے، اجنادین میں شہید ہوئے، اسی طرح ابو حذیفہ نے مبتدا میں عبداللہ بن محمد قدامی نے فتوح میں اور محمد بن سعد نے فرمایا: اجنادین میں شہید ہوئے، سیف بن عمر کا قول ہے: یرموک میں شہید ہوئے، زبیر بن بکار اور ابن سعد نے بھی اسی طرح فرمایا: موتہ میں شہید ہوئے۔","",{"fn":"(1) اسد الغابة (۵۳۳۵) الاستيعاب (۲۷۰۲) تجريد اسماء الصحابة (۱۱۷/۲)\n(2) السيرة النبوية (۲۵۸/۱) (۶/۴)"}],[7556,"§۸۹۳۴ ۔ ہبار بن صیفی\n(1) صحابہ رضی اللہ عنہم میں ان کا ذکر ہے، اس میں تردد ہے، یہ ابو عمر(2) کا قول ہے۔\nمیں کہتا ہوں: کسی اور کی کتاب میں مجھے اس کا ذکر نہیں ملا۔","",{"fn":"(1) اسد الغابہ (۵۳۳۶) استيعاب (۲۷۰۳) تجريد (۱۱۷/۲)\n(2) استيعاب (۹۷/۳)"}],[7557,"§۸۹۳۵ ۔ ہبار بن ابی العاص\nبن نوفل بن عبد شمس بن عبد مناف قرشی عبشمی، ان کے والد بدر کے دن حالت کفر میں قتل ہوئے، مسلمانانِ فتح مکہ میں سے ہیں، ان کا عمر نامی بیٹا تھا، جو شام میں تھا، ان کی اولاد میں خالد بن یزید بن عمر ہیں، بنو عباس کے دور حکومت میں شام میں بنی امیہ کے ساتھ قتل ہوئے۔"],[7558,"§۸۹۳۶ ۔ ہبار بن وہب\nبن حذافہ، ابن اسحاق رحمہ اللہ نے مہاجرین حبشہ میں ان کا ذکر کیا ہے، یہ بلاذری نے بیان کیا ہے۔"],[7559,"§۸۹۳۷ ۔ ہُبیب\n(1) بعض کا قول ہے: مُغفل ان کے والد کے دادا ہیں، ان کی طرف نسبت ہو گئی۔ یہ ابو نعیم کا قول ہے، فرماتے ہیں: وہ ابن عمر بن مُغفل بن واقعہ بن حرام بن غفار غفاری ہیں، ابن یونس نے ان کا نسب بیان کیا ہے، فرماتے ہیں، فتح مصر میں شریک ہوئے۔ میں کہتا ہوں: بازار کے بارے میں ان کی صحیح حدیث محمد بن علیہ کے سوانح میں گزر چکی ہے، وہ احمد(2) وغیرہ کے ہاں ہے۔ ابن یونس نے ان کا ذکر کیا ہے کہ وہ سیدنا عثمان رضی اللہ عنہ کے شہید ہونے کے بعد فتنہ کے دور میں مریوط اور فیوم کے درمیان ایک وادی میں الگ ہو گئے، اس وجہ سے اسے وادی ہبیب کہا جاتا ہے۔","",{"fn":"(1) تجريد (۱۱۷/۲) اسد الغابة (۵۳۳۷)\n(2) مسند احمد (۳/۲۲۷) (۴/۲۲۷)"}],[7560,"§۸۹۳۸ ۔ ہبیرہ بن سبل\n(1) خطیب نے ابن فرات کی تحریر سے اسے لکھا ہے، رہے دار قطنی رحمہ اللہ تو انہوں نے جادہ میں ان کا ذکر کیا ہے، اسی طرح فاکہی رحمہ اللہ کی کتاب مکہ کے قابل اعتماد نسخے میں میں نے دیکھا ہے: ابن عجلان بن عقاب بن مالک بن کعب بن عمرو بن سعد بن عوف بن ثقیف ثقفی۔\nابن کلبی رحمہ اللہ نے ان کا نسب بیان کیا ہے، ابن سعد اور بغوی نے بطریق ابن جریج نقل کیا ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم فتح مکہ کے سال طائف گئے تو ہبیرہ بن سبل ثقفی کو نائب مقرر کیا، جب طائف سے واپس آئے تو عتاب بن اسید کو مکہ اور حج کا امیر مقرر کیا۔ اسی طرح خطیب نے بطریق اسحاق بن ابراہیم بن حاتم، بحوالہ کلبی ان کا ذکر کیا ہے، عبد الرزاق نے بحوالہ ابن جریج نقل کیا ہے: مجھ سے بیان کیا گیا کہ فتح مکہ کے بعد مکہ میں سب سے پہلے ہبیرہ بن سبل بن عجلان نے جماعت کرائی، نبی کریم صلی اللہ علیہ وسلم نے انہیں حکم دیا کہ لوگوں کو نماز پڑھائیں، وہ ثقیف کے ایک شخص ہیں، نبی کریم صلی اللہ علیہ وسلم کے پاس آئے، آپ صلی اللہ علیہ وسلم اس وقت حدیبیہ میں تھے۔(2) اسی طرح فاکہی اور ابو عمر نے بطریق ابن جریج میں نقل کیا ہے۔","",{"fn":"(1) اسد الغابة (۵۳۳۸) تجريد (۱۱۷/۲)\n(2) اسد الغابة (۴/۲۷۴)"}],[7561,"§۸۹۳۹ ۔ ہبیرہ بن مفاضہ العامری\n(1) وثیمہ نے بحوالہ ابن اسحاق ردہ میں ان کا ذکر کیا ہے، فرماتے ہیں: جب عرب کے قبائل مرتد ہو گئے تو انہوں نے بنو سلیم کی طرف پیغام بھیجا اور انہیں اسلام پر ثابت قدم رہنے کا حکم دیا۔","",{"fn":"(1) اسد الغابة (۵۳۳۹) تجريد (۱۱۷/۲)"}],[7562,"§۸۹۴۰ ۔ ہُبیل\nابن کعب، بنو مازن میں سے ہیں۔ مازن بن غشمہ کے سوانح میں ان کا ذکر گزر چکا ہے۔ واللہ اعلم"],[7563,"§۸۹۴۱ ۔ ہُبیل بن وبرہ انصاری\nان کے بھائی عصمہ کے سوانح میں ان کا ذکر گزر چکا ہے۔"],[7564,"§۸۹۴۲ ۔ ہدّاج حنفی\n(1) مدنین میں ان کا شمار ہے۔ بغوی، ابن سکن اور ابن مندہ نے بطریق ابو عمار ہاشم بن غطفان، بحوالہ عبداللہ بن ہدّاج، انہوں نے اپنے والد ہدّاج سے نقل کیا ہے، ہدّاج نے جاہلیت کا دور پایا، فرماتے ہیں: ایک شخص نبی کریم صلی اللہ علیہ وسلم کے پاس آیا، اس کی داڑھی زرد تھی، آپ صلی اللہ علیہ وسلم نے فرمایا: ”خضاب اسلام میں سے ہے۔“۔ (الحدیث)(2)","",{"fn":"(1) اسد الغابة (۵۳۴۳) تجريد (۱۱۸/۲)\n(2) تاريخ كبير (۲۴۹/۸) اسد الغابة (۲۷۵/۴) كنز العمال (۱۷۲۴۲)"}],[7565,"§۸۹۴۳ ۔ ہدّار کنانی\nابو عمر کا قول ہے: انہیں شرفِ صحابیت حاصل ہے، ابن مندہ کا قول ہے: اہل حمص میں ان کا شمار ہے، عبد الغنی بن سعید نے تاریخ حمص میں فرمایا: ہم سے محمد بن عوف نے بیان کیا، اسے امام احمد بن حنبل کے ہاں لکھا، مجھ سے میرے والد نے بحوالہ ہدّار کنانی بیان کیا کہ انہوں نے سیدنا عباس رضی اللہ عنہ اور ان کے میدے کی روٹی میں اسراف دیکھا، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم وفات پا گئے اور گندم کی روٹی سے پیٹ نہیں بھرا، یہاں تک کہ دنیا سے چلے گئے۔(1) اسے ابن مندہ نے بحوالہ محمد بن عوف نقل کیا ہے، فرماتے ہیں: غریب ہے۔\nاسے ابن سکن نے بروایت محمد بن عوف اور عبدہ بحوالہ ہدّار جو رسول اللہ صلی اللہ علیہ وسلم کے صحابی ہیں، فرماتے ہیں: اس طریق کے علاوہ ہدّار سے کوئی حدیث مروی نہیں۔ اسی طرح اسے ابن قانع نے بروایت محمد بن عوف روایت کیا ہے، اسے ابو الفضل بن طاہر نے اپنے فوائد میں دوسرے طریق سے بحوالہ محمد بن عوف نقل کیا ہے، اس کے الفاظ یہ ہیں: میں نے ہدّار سے سنا، وہ صحابہ میں سے ہیں، اسے ابو نعیم نے دوسرے طریق سے بحوالہ محمد بن عوف نقل کیا ہے، اس میں ہے: میں نے سیدنا ہدّار کنانی کو سنا، وہ سیدنا عباس رضی اللہ عنہ کو میدے کی روٹی کھانے پر عتاب کر رہے تھے۔","",{"fn":"(1) كنز العمال (۱۷۲۴۳)"}],[7566,"§۸۹۴۴ ۔ ہدم بن مسعود\n(1) بن مجاہد بن عبد بن مالک بن غالب بن قُطیعہ بن عبس عبسی، بنو(۹) لوگوں کے وفد میں سے تھے، بشر بن حارث کے سوانح میں ان کا ذکر گزر چکا ہے۔ طبری اور ابن کلبی نے ان کا ذکر کیا ہے، رشاطی کا قول ہے: ابن عبد البر نے ان کا ذکر نہیں کیا، نہ ہی ابن فتحون نے ان کا ذکر کیا ہے۔ ابن ماکولا نے یہ لکھا ہے۔ واللہ اعلم","",{"fn":"(1) تجريد (۱۱۸/۲)"}],[7567,"§۸۹۴۵ ۔ ہدم مخنث\nہیت کے ساتھ ان کا ذکر آئے گا۔"],[7568,"§۸۹۴۶ ۔ ہُدیم بن عبداللہ\n(1) بن علقمہ بن مطلب کلبی، ابن عبد البر اور ابن ماکولا کا قول ہے، یمامہ میں شہید ہوئے، لیکن ابن عبد البر نے راء کے ساتھ ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۵۳۴۸) تجريد (۱۱۸/۲)"}],[7569,"§۸۹۴۷ ۔ ہرماس بن زیاد باہلی\n(1) ابو داؤد وغیرہ نے صحیح اسناد سے ان کی حدیث روایت کی ہے۔(2) وہ بنو تمیم بن عمر میں سے ہیں، ابو امامہ باہلی کے قبیلے سے ہیں، ان کا ایک چچا زاد تھا جسے حبیب بن وائل کہا جاتا تھا، مال میں اسے وسعت دی گئی تھی، ابو ثمہ باہلی اس کے بارے میں کہتے ہیں:\n”میں اگرچہ حبیب کو وسعت دی گئی ہے کفایت کرنے والوں پر زیادہ قناعت نہیں کرتا، میں اتنا کھاتا ہوں جس سے سیر ہو جاؤں اور ٹھنڈے پانی کا نبیذ بنا کے پیتا ہوں۔“\nتو ہرماس نے حبیب کی طرف سے اپنے جواب دیا:\n”حبیب کی طرح ہو جاؤ پھر اسے زیادہ چھوڑنے والا کر چھوڑ، اپنے آپ پر رحم کر کہ کہیں تو بزدل ہو جائے۔“","",{"fn":"(1) اسد الغابة (۵۳۵۵)\n(2) بخاري (۱۶۸۴) ابوداود (۱۹۳۸) ترمذي (۸۹۶) نسائي (۳۰۴۷) ابن ماجه (۳۰۲۲) مسند احمد (۳/۴۸۵) (۵/۷)"}],[7570,"§۸۹۴۸ ۔ ہرماس بن زیاد عنبری\nثعلبہ میں ان کا ذکر گزر چکا ہے۔"],[7571,"§۸۹۴۹ ۔ ہرم بن حیان عبدی\n(1) ابن عبد البر کا قول ہے: وہ صغار صحابہ رضی اللہ عنہم میں سے ہیں، خلیفہ نے بحوالہ ولید بن ہشام فرمایا، انہوں نے اپنے والد سے، انہوں نے اپنے والد سے نقل کیا ہے کہ عثمان بن ابی العاص نے ہرم بن حیان عبدی کو قلعہ بحرہ کی طرف بھیجا، انہوں نے اسے دب بہ سے فتح کر لیا، یہ ۲۰ھ کا واقعہ ہے۔ بعض کا قول ہے: ۱۸ھ کا، سیدنا عمر رضی اللہ عنہ کے زمانے میں جیسا کہ پہلے گزر چکا ہے کہ فتوح کے زمانے میں وہ صرف صحابہ رضی اللہ عنہم کو امیر بناتے تھے۔\nامام احمد رحمہ اللہ کی کتاب الزہد میں ہے کہ وہ حمہ دوسی کے ساتھی تھے، حمہ خلافت عثمان رضی اللہ عنہ میں فوت ہوئے، مسند دارمی میں بطریق ابی عمران جونی مروی ہے: فاسق عالم سے بچو، سیدنا عمر رضی اللہ عنہ کو یہ بات معلوم ہوئی تو ان کی طرف لکھا، تمہاری کیا مراد ہے؟ انہوں نے کہا: میں نے بھلائی کا ارادہ کیا ہے۔ عالم امام اپنے علم سے گفتگو کرے گا اور گناہ کے کام کرے گا، جس سے لوگ شبہ میں پڑ جائیں گے، اس میں ہے: بحوالہ حسن کہ وہ جب وفات پاگئے تو نہایت گرم دن تھا، بادل کا ایک ٹکڑا آیا اور ان کی قبر اور اس کے ارد گرد جگہ پر بوچھاڑ کر گیا۔\nابن حبان کا قول ہے: انہوں نے سیدنا عمر رضی اللہ عنہ کا زمانہ پایا اور ان کی خلافت میں بہت سے عہدوں پر مامور رہے، ابو نعیم کی کتاب الحلیہ میں ان کا قصہ حضرت اویس قرنی کے ساتھ ہے، اس میں بطریق ..... بخاری(2) نے اپنی تاریخ میں بطریق اعمش نقل کیا ہے کہ ہم سے عامر نے وہ فرماتے ہیں کہ مجھ سے ابو زید بن خلیفہ نے نقل کیا ہے کہ وہ نبی کریم صلی اللہ علیہ وسلم کے اصحاب میں سے ہرم بن حیان بن عبد القیس سے ملے، فرمایا: کیا تم اہل کوفہ میں سے ہو؟ انہوں نے کہا: جی ہاں! فرمایا: تم مجھ سے پوچھ رہے ہو جبکہ تم میں سیدنا عبداللہ بن مسعود ہیں۔ ابن ابی حاتم نے اکابر تابعین میں سے آٹھ(۸) زہاد میں ان کا شمار کیا ہے۔ عسکری کا قول ہے: خیار تابعین میں سے ہیں، ابن سعد(3) کا قول ہے: ثقہ ہیں، انہیں فضیلت حاصل ہے، فتوح میں قبیلہ عبد القیس کے امیر تھے، ابن ابی شیبہ کا قول ہے: ہم سے خلف نے بحوالہ ابو النضر نقل کیا ہے کہ سیدنا عمر رضی اللہ عنہ نے ہرم بن حیان کو شہروں پر امیر بنا کر بھیجا۔ انہوں نے سیدنا عمر رضی اللہ عنہ کو لکھا، مجھے نگرانی کی طاقت نہیں۔","",{"fn":"(1) اسد الغابة (۵۳۵۶) استيعاب (۲۷۰۴) تجريد (۱۱۸/۲)\n(2) تاريخ كبير (۲۴۳/۴)\n(3) طبقات الكبرى (۱۰۲/۷)"}],[7572,"§۸۹۵۰ ۔ ہرم بن خنبش\nحرف واؤ میں وہب بن خنبش کے سوانح میں ان کا ذکر آئے گا۔"],[7573,"§۸۹۵۱ ۔ ہرمز\nنبی کریم صلی اللہ علیہ وسلم کے مولیٰ ہیں، کیسان میں ان کا ذکر گزر چکا ہے۔"],[7574,"§۸۹۵۲ ۔ ہُرمُز بن ماہان فارسی\n(1) ابو موسیٰ نے ذیل میں بطریق احمد بن محمد بن سعد بحوالہ ہرمز بن ماہان جو فارسی ہیں سے نقل کیا ہے، فرماتے ہیں: میں نبی کریم صلی اللہ علیہ وسلم کے پاس آیا، میں آپ صلی اللہ علیہ وسلم کے ہاتھ پر اسلام لایا، آپ صلی اللہ علیہ وسلم نے مجھے سیدنا خالد بن ولید رضی اللہ عنہ کے لشکر میں رکھا، میں نے کہا: یا رسول اللہ! میرے لیے صدقہ کا حکم دیجیے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”صدقہ نہ میرے لیے حلال ہے نہ میرے گھر والوں میں سے کسی کے لیے حلال ہے۔“۔ پھر میرے لیے ایک دینار دینے کا حکم فرمایا۔(2) ابن اثیر کا قول ہے: ہو سکتا ہے یہ پہلے والے ہی ہوں، لگتا ہے ان کی دلیل وہ روایت ہے جو بغوی نے بطریق ابو یزید بن ابو زیاد بحوالہ معاویہ بن قرہ نقل کی ہے، فرماتے ہیں: بدر میں بیس(۲۰) غلام شریک ہوئے، ان میں نبی کریم صلی اللہ علیہ وسلم کا غلام ہرمز بھی تھا، نبی کریم صلی اللہ علیہ وسلم نے اسے آزاد کر دیا اور فرمایا: ”اللہ تعالیٰ نے تمہیں آزاد کیا ہے، کسی قوم کا آزاد کردہ غلام انہی میں شمار ہوتا ہے۔ ہم اہل بیت صدقہ نہیں کھاتے، تم بھی اسے نہ کھاؤ“۔(3) لیکن فارسی کی روایت میں ہے کہ ان کا اسلام لانا خیر سے ہے، کیونکہ سیدنا خالد بن ولید رضی اللہ عنہ مدینہ میں اسلام لائے اور غزوہ بدر اس سے طویل مدت پہلے ہوا، دونوں قولوں کو جمع کرنا اس قول سے ممکن ہے کہ مجھے سیدنا خالد رضی اللہ عنہ کے لشکر میں شامل کر دیا، اس سے ان کے تاخیر سے اسلام لانے کا پتہ چلتا ہے، اگرچہ حرف فا کے ذریعے اس پر عطف کیا گیا۔","",{"fn":"(1) اسد الغابة (۵۳۵۷) تجريد (۱۱۹/۲)\n(2) مصنف عبد الرزاق (۶۹۴۵) معجم الكبير (۲۷۴/۴) (۲۱۶/۵) كنز العمال (۱۲۹۱۷) (۱۶۵۲۵) الكامل في الضعفاء (۲۳۴۹/۶) جامع المسانيد والسنن (۲۲۲/۲)\n(3) البداية والنهاية (۳۲۱/۵)"}],[7575,"§۸۹۵۳ ۔ ہرم یا ہرمی بن عبداللہ انصاری\n(1) بنو عمرو بن عوف سے ہیں، وہ ان رونے والوں میں سے ایک ہیں جن کے بارے میں یہ آیت نازل ہوئی: ﴿وہ واپس چلے جاتے ہیں اور ان کی آنکھوں سے آنسو بہہ رہے ہوتے ہیں۔﴾(2) یہ ابن عبد البر(3) نے دو والی کی پیروی کرتے ہوئے کہا ہے: رشاطی وغیرہ نے ان کا تعاقب کیا ہے، فرماتے ہیں: وہ بنو عمرو بن عوف سے نہیں ہیں، وہ بنو مالک بن اوس سے ہیں۔ ان کا نام ہرمی ہے، وہ ہرمی بن عبداللہ بن رفاعہ بن نجدہ بن مجدعہ بن عامر بن کعب بن واقف بن امری القیس بن مالک بن اوس ہیں۔ اسی طرح ابن کلبی اور ابن سعد وغیرہ(4) نے ان کا نسب بیان کیا ہے۔ ابن سعد کا قول ہے: اسلام کے ابتدائی دور میں اسلام لائے، وہ رونے والوں میں سے ایک ہیں۔ ابن ماکولا(5) نے یہ اضافہ کیا ہے کہ خندق میں اور بعد کے غزوات میں شریک تھے۔ اور ہرمی بن عبداللہ کے علاوہ ہیں جو جریر بن ثابت سے روایت کرتے ہیں۔ ابن اثیر کا قول ہے: ایسا لگتا ہے ابن ماکولا نے انہیں ایک قرار دیا ہے۔ یہ ان سے چوک ہو گئی ہے۔ ابن اثیر نے ابن عبد البر کے قول کا یہ عذر پیش کیا ہے کہ وہ بنو عمرو بن اوس سے ہیں، کیونکہ جاہلیت میں بنو واقف، بنو عمر کے حلیف تھے، یہ اچھا عذر ہے۔","",{"fn":"(1) اسد الغابة (۵۳۳۸) استيعاب (۲۷۰۵)\n(2) سورہ مائدہ الآیۃ (۸۳)\n(3) استيعاب (۹۸/۳)\n(4) طبقات الكبرى (۱۶۵/۲)\n(5) الإكمال (۳۱۵/۷)"}],[7576,"§۸۹۵۴ ۔ ہرم\nدوسرے ہیں، صہیب میں ان کا ذکر ہے۔"],[7577,"§۸۹۵۵ ۔ ہُریم\nہُذیم مطلبی میں ان کا ذکر آئے گا۔"],[7578,"§۸۹۵۶ ۔ ہزّال بن یزید\n(1) بن ذباب بن کلیب بن عامر بن جذیمہ بن مازن اسلمی، ابن حبان کا قول ہے: انہیں شرفِ صحابیت حاصل ہے، ان کی حدیث نسائی کے ہاں ان کے بیٹے نعیم بن ہزّال کی روایت سے ہے کہ ہزّال کی ایک لونڈی تھی، ماعز اس سے زنا کر بیٹھے تو ہزّال نے ان سے کہا: رسول اللہ صلی اللہ علیہ وسلم کے پاس جاؤ اور انہیں بتاؤ، امید ہے کہ تمہارے بارے میں قرآن نازل ہوگا۔ وہ گئے اور آپ صلی اللہ علیہ وسلم کو اس کی خبر دی، آپ صلی اللہ علیہ وسلم نے انہیں سنگسار کرنے کا حکم دیا۔ نبی کریم صلی اللہ علیہ وسلم نے ہزّال سے فرمایا: ”اے ہزّال! اگر تم اپنے اس عیب کو چھپا لیتے تو تمہارے لیے بہتر تھا“۔\nحاکم(2) نے مستدرک میں بطریق شعبہ بحوالہ ابن ہزّال نقل کیا ہے، انہوں نے اپنے والد سے اسی مفہوم میں روایت نقل کی ہے۔","",{"fn":"(1) تجريد (۱۱۹/۲)\n(2) مستدرك حاكم (۳۶۳/۴)"}],[7579,"§۸۹۵۷ ۔ ہزّال\n(1) درخت والے ہیں، ان سے معاویہ بن قرہ رحمہ اللہ نے روایت کیا، فرماتے ہیں: تم لوگ ایسے گناہ کرتے ہو جو تمہاری نگاہوں میں بال برابر ہیں۔ ہم انہیں رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ہلاک کرنے والی چیزوں میں شمار کرتے تھے۔(2)","",{"fn":"(1) اسد الغابة (۵۳۶۰) استيعاب (۲۷۰۶) تجريد (۱۱۹/۲)\n(2) مسند احمد (۷۹/۵)"}],[7580,"§۸۹۵۸ ۔ ہزان بن عمرو\n(1) بن قربوس بن غنم بن سالم بن عوف بن عمرو بن عوف بن خزرج انصاری، ابن فتحون نے بدر میں شریک ہونے والوں میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۵۳۶۳)"}],[7581,"§۸۹۵۹ ۔ ہزان زُھاوی\nابن شاہین نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، عمرو بن سفیح کے سوانح میں ان کے بارے میں گزر چکا ہے۔"],[7582,"§۸۹۶۰ ۔ ہزھار بن عمرو عجلی\nطبری نے ذکر کیا ہے کہ سیدنا ابو عبیدہ نے انہیں سیدنا عمر رضی اللہ عنہ کے حکم پر لشکر کے ایک حصے کا سردار بنا دیا تھا۔ جب شہسواروں کو عراق کی طرف بھیجا۔ ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے، پہلے گزر چکا ہے کہ فتوح کے زمانے میں صحابہ رضی اللہ عنہم کے علاوہ کسی کو امیر نہیں بناتے تھے۔"],[7583,"§۸۹۶۱ ۔ ہشام بن بختری مخزومی\nان کے مولا ہیں، مرزبانی نے معجم الشعراء میں ان کا ذکر کیا ہے۔\nمیں کہتا ہوں: سیدنا خالد بن ولید رضی اللہ عنہ کے بارے میں ان کا مرثیہ ہے، جب وہ خلافت عمر میں وفات پاگئے، اسے معافی نہروانی نے کتاب الجلیس میں بطریق ابی علی جرازی روایت کیا ہے۔ فرماتے ہیں: ہشام بن بختری بنو مخزوم کے لوگوں کے ساتھ سیدنا عمر رضی اللہ عنہ کے پاس آئے، انہوں نے کہا: اے ہشام! سیدنا خالد بن ولید کے بارے میں اپنے شعر سناؤ، انہوں نے شعر سنائے تو ان سے فرمایا: تم نے ابو سلیمان پر رونے میں کمی کی، وہ پسند کرتے تھے کہ شرک اور شرک کرنے والے ذلیل ہوں، مصیبت پر خوش ہونے والا اللہ کی ناراضی کا سامنا کرنے والا ہے جو کچھ اللہ کے پاس ہے وہ ان کے لیے بہتر ہے، بہ نسبت اس کے جس حال میں وہ تھے۔"],[7584,"§۸۹۶۲ ۔ ہشام بن حبیب داری\nطبری نے نبی کریم صلی اللہ علیہ وسلم کے پاس دارین میں سے آنے والے لوگوں میں ان کا ذکر کیا ہے، ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔"],[7585,"§۸۹۶۳ ۔ ہشام بن خُبیش(2)\n(1) ابن خالد مخزومی، ابن حبان کا قول ہے: انہیں شرفِ صحابیت حاصل ہے۔ بخاری رحمہ اللہ(3) کا قول ہے: انہوں نے سیدنا عمر رضی اللہ عنہ سے سنا، یحییٰ بن یونس شیرازی نے بطریق حرام بن ہشام بن خُبیش نقل کیا ہے، فرماتے ہیں: میں نے اپنے والد سے سنا کہ وہ رسول اللہ صلی اللہ علیہ وسلم کا ذکر کر رہے تھے کہ انہوں نے بستی پر بادل دیکھے تو فرمایا: یہ ضر بنی کعب کی زمین کو نرم کرے گا، یہ بات صحیح ثابت ہے کہ ان کے والد فتح مکہ کے دن قتل ہوئے، اسید بن ابی ایاس کی سوانح میں اس حدیث کا طریق(4) گزر چکا ہے۔","",{"fn":"(1) اسد الغابة (۵۳۶۵)\n(2) الثقات (۴۳۲/۳)\n(3) تاريخ كبير (۱۹۲/۸)\n(4) جامع المسانيد والسنن (۲۷۸/۱۲)"}],[7586,"§۸۹۶۴ ۔ ہشام بن حُبیش سلمی\nمندر بن خلدہ میں ان کی ایک حدیث ہے، تجرید میں اس کا ذکر ہے۔"],[7587,"§۸۹۶۵ ۔ ہشام بن ابی حذیفہ\n(1) ابن مغیرہ بن عبداللہ بن عمر بن مخزوم مخزومی، ابن اسحاق(2) اور زبیر بن بکار نے حبشہ کی طرف ہجرت کرنے والوں میں ان کا ذکر کیا ہے۔ واقدی نے ان کا نام ہشام لیا ہے، ابو معشر اور موسیٰ بن عقبہ نے ان کا ذکر نہیں کیا۔","",{"fn":"(1) اسد الغابة (۵۳۶۶)\n(2) السيرة النبوية (۲۷۱/۲) (۶/۴)"}],[7588,"§۸۹۶۶ ۔ ہشام بن حکیم\n(1) ابن حزام بن خویلد بن اسد بن عبد العزیٰ بن قصی قرشی اسدی، ابن مندہ کو وہم ہوا ہے، انہوں نے انہیں مخزومی کہا ہے۔\nصحیح میں بروایت زہری، بحوالہ عمر ان کا ذکر ثابت ہے کہ میں نے ہشام بن حکیم نے سورہ فرقان اس طریقے سے ہٹ کے پڑھ رہے ہیں جس طریقے سے رسول اللہ صلی اللہ علیہ وسلم نے مجھے پڑھایا تھا، اسی میں ہے کہ وہ انہیں رسول اللہ صلی اللہ علیہ وسلم کے پاس لے آئے۔ آپ صلی اللہ علیہ وسلم نے دونوں کی قراءت سنی اور دونوں کو درست قرار دیا، فرمایا: ”قرآن پاک سات(۷) لہجوں میں نازل ہوا“۔(2) حدیث طویل ہے۔\nابن سعد کا قول ہے: بارعب تھے، زہری کا قول ہے: اپنے ساتھ لوگوں کو نیکی کا حکم دیتے تھے، مصعب زبیری کا قول ہے: انہیں فضیلت حاصل تھی، ابن وہب نے بحوالہ مالک نقل کیا ہے۔ کسی کو دوست نہیں بناتے تھے، نہ ان کی اولاد تھی، ان سے اسی طرح جبیر بن نفیر، قتادہ سلمی وغیرہ نے روایت کیا ہے، اپنے والد سے ایک مدت پہلے فوت ہوگئے، ابو نعیم کا قول ہے: اجنادین میں شہید ہوئے۔","",{"fn":"(1) اسد الغابة (۵۳۶۷) الاستيعاب (۲۷۱۰) تجريد (۱۲۰/۲)\n(2) مسند احمد (۴۰۳/۳) مجمع الزوائد (۱۰۵/۷) مصنف ابن ابي شيبة (۵۱۶/۱۰) در المنثور (۶/۲) تاريخ بغداد (۲۶/۱۱)"}],[7589,"§۸۹۶۷ ۔ ہشام بن صُبابہ\n(1) ابن حزن بن سیار بن عبداللہ بن کلیب بن عوف بن کعب بن عامر بن لیث بن بکر بن عبد مناۃ بن کنانہ، ابن کلبی نے ان کا نسب بیان کیا ہے، ابو سعید عسکری کا قول ہے: وہ ہشام بن حزن ہیں، ان کی والدہ صبابہ بنت متیقس بن قیس بن عدی بن سعید بن سہم ہیں، ابن اسحاق(2) نے مغازی میں فرمایا: مجھ سے عبداللہ بن ابی بکر بن عمرو بن حزم نے بیان کیا کہ ہشام مرتدین کے مسلمانوں کے ساتھ مل کر لڑے یہاں تک کہ نہایت جرات مندی کا مظاہرہ کیا، وہ اسلام لا چکے تھے، ان سے بنو خوف بن خزرج کا ایک شخص ملا، اس نے خیال کیا کہ وہ مشرک ہیں اور انہیں قتل کر دیا۔\nتفسیر سعید بن جبیر میں وہ روایت ہے جسے ابن لہیعہ نے بحوالہ عطاء بن دینار، انہوں نے ان کے حوالے سے نقل کیا ہے، اسی طرح تفسیر ابن کلبی رحمہ اللہ میں بحوالہ ابن عباس رضی اللہ عنہما اس آیت مبارکہ کے بارے میں مروی ہے جو کسی مومن کو جان بوجھ کر قتل کرے۔(3) فرماتے ہیں: یہ آیت مقیس بن صبابہ کے بارے میں نازل ہوئی، وہ اور ان کے بھائی ہشام اسلام لا چکے تھے، مقیس نے اپنے بھائی کو مقتول پایا تو رسول اللہ صلی اللہ علیہ وسلم سے اس کی شکایت کی، آپ صلی اللہ علیہ وسلم نے اسے دیت دینے کا حکم فرمایا، اس نے اسے لے لیا، پھر اپنے بھائی کے قاتل پر حملہ کیا اور اسے قتل کر دیا۔ پھر مرتد ہو کر مکہ مقیم ہو گیا اور اس کے بارے میں اشعار کہے۔ واقدی رحمہ اللہ نے اپنی سند سے ان کے قاتل کا نام اوس لیا ہے، اور ان کا نام ہشام لیا ہے، اسی طرح بحوالہ ابن شاہین، بطریق محمد بن یزید، اپنے راویوں سے نقل کیا ہے، پہلا قول زیادہ صحیح ہے۔","",{"fn":"(1) اسد الغابة (۵۳۶۹) الاستيعاب (۲۷۱۱) تجريد (۱۲۰/۲)\n(2) السيرة النبوية (۲۸/۳) (۲۲۰/۳)\n(3) سورة النساء الآية (۹۳)"}],[7590,"§۸۹۶۸ ۔ ہشام بن العاص\n(1) ابن وائل سہمی، ان کے بھائی عمرو کی سوانح میں ان کا نسب گزر چکا ہے، ابن حبان کا قول ہے: ان کی کنیت ابو العاص تھی، نبی کریم صلی اللہ علیہ وسلم نے ان کی کنیت ابو مطیع رکھ دی۔ ابن سعد کا قول ہے: ان کی والدہ ام حرملہ بنت ہشام بن مغیرہ ہیں، اسی طرح ابن سکن کا قول ہے: اسلام کے ابتدائی دور میں اسلام لائے، حبشہ کی طرف ہجرت کی، ابن سکن نے صحیح سند سے بحوالہ ابن اسحاق(2) بحوالہ عمر نقل کیا ہے۔ فرماتے ہیں: میں نے اور عیاش بن ابی ربیعہ، ہشام بن العاص نے وعدہ کیا جب ہم نے ہجرت کا ارادہ کیا کہ ہم میں سے صبح کے بعد جو پیچھے رہ جائے تو ہم یہ سمجھیں گے کہ اسے کوئی مسئلہ پیش آگیا، پھر باقی چل پڑیں گے۔ فرماتے ہیں: صبح سے پہلے میں اور عیاش نکل آئے اور ہشام روک لیے گئے اور آزمائش میں ڈالے گئے۔۔۔۔ (الحدیث)\nنسائی اور حاکم نے بطریق محمد بن عمر، انہوں نے بحوالہ ابو ہریرہ مرفوع حدیث نقل کی ہے: ”العاص کے دونوں بیٹے مومن ہیں: ہشام اور عمرو“۔(3) ہم نے اسے امالی المحاملی میں بطریق عمرو بن دینار، بحوالہ عمر اسی مفہوم میں نقل کیا ہے۔\nبغوی نے بطریق ابو حازم بحوالہ عمرو بن شعیب، عن ابیہ، عن جدہ نقل کیا ہے، فرماتے ہیں: ہم آئے اور لوگ قرآن کے بارے میں بحث مباحثہ کر رہے تھے۔ ہم ان سے الگ ہوگئے، رسول اللہ صلی اللہ علیہ وسلم حجرے کے پیچھے سے ان کی گفتگو سن رہے تھے، آپ صلی اللہ علیہ وسلم غصے سے باہر آئے یہاں تک کہ ان کے پاس کھڑے ہوئے اور فرمایا: ”اس کی وجہ سے تم سے پہلی امتیں گمراہ ہوئیں، قرآن اس لیے نازل نہیں ہوا کہ تم اس کے بعض حصے کو بعض سے ٹکراؤ، اس کا بعض حصہ دوسرے حصے کی تصدیق کرتا ہے“۔ پھر میری اور میرے بھائی کی طرف متوجہ ہوئے، ہمیں اپنے آپ پر بڑا غصہ آیا کہ آپ صلی اللہ علیہ وسلم نے ہمیں ان کے ساتھ نہ دیکھا ہو، اسے سوید بن سعید نے بحوالہ عبد العزیز بن ابی حازم، انہوں نے اپنے والد کے حوالے سے نقل کیا ہے۔\nواقدی کا قول ہے: نبی کریم صلی اللہ علیہ وسلم نے انہیں فتح مکہ(4) سے پہلے ایک سریہ میں بھیجا، ابن مبارک نے زہد میں، بحوالہ عبداللہ ابن عبید بن عمیر فرمایا: فرماتے ہیں: عمرو بن العاص قریش کی ایک جماعت کے پاس سے گزرے، انہوں نے ہشام کا ذکر کیا، کہنے لگے: ان دونوں میں سے کون افضل ہے؟ عمرو نے کہا: میں اور ہشام جنگ یرموک میں شریک تھے، ہم میں سے ہر ایک نے اللہ تعالیٰ سے شہادت کا سوال کیا، جب صحیح ہوئی تو میں اس سے محروم رہا اور انہیں شہادت نصیب ہوئی۔\nاسی طرح ابن سعد، ابن ابی حاتم اور ابو زرعہ مشقی کا قول ہے۔ موسیٰ بن عقبہ اور ابو اسود نے بحوالہ عروہ، ابن اسحاق، ابو عبیدہ، مصعب، زبیر اور دوسرے راویوں سے اجنادین میں(5) شہید ہونے والوں میں ان کا ذکر کیا ہے۔\nواقدی نے بحوالہ خرمہ بن بکیر، انہوں نے ام بکر بنت مسور سے نقل کیا ہے۔ فرماتے ہیں: ہشام نیک شخص تھے، اجنادین میں بعض مسلمانوں کو دیکھا کہ وہ پسپائی اختیار کر رہے ہیں، انہوں نے اپنے چہرے سے خود ہٹایا اور دشمن کو مارنے کے لیے پیش قدمی کرنے لگے اور بلند آواز سے کہنے لگے: میری طرف آؤ، میری طرف آؤ۔ میں ہشام بن العاص ہوں۔ کیا تم جنت سے بھاگتے ہو۔۔۔۔ یہاں تک کہ شہید ہوگئے۔\nخالد بن معدان کے طریق سے ہے کہ جب رومیوں کو اجنادین میں شکست ہوئی تو وہ ایسی جگہ کی طرف پیچھے ہٹے صرف ایک شخص عبور کر سکتا تھا، رومی اس پر ڈٹ گئے۔ ہشام بھی لڑے یہاں تک کہ شہید ہوگئے۔ اس مقام پر ان کی لاش گری اور اس کا راستہ بند ہو گیا۔ جب مسلمان وہاں پہنچے تو ان کی لاش کو روندنا پسند نہ کیا۔ عمرو نے کہا: اے لوگو! اللہ تعالیٰ نے انہیں شہادت عطا فرمائی ہے، ان کی روح کو نکال لیا ہے، وہ صرف جسم ہے۔ پھر اس کے اوپر سے گزر گئے۔ عمرو نے اس کے بعد انہیں جمع کیا اور چہرے کے غمدے میں ڈال کر دفن کر دیا۔(6)","",{"fn":"(1) الاستيعاب (۲۷۱۲) تجريد (۱۲۰/۲)\n(2) السيرة النبوية (۹۰/۲)\n(3) مستدرك حاكم (۴۵۲/۳) المعجم الكبير (۱۱۷/۲۲) طبقات الكبرى (۱۹۱/۴)\n(4) مختصر تاريخ دمشق (۹۳/۲۷)\n(5) مختصر تاريخ دمشق (۸۸/۲۷)\n(6) مختصر تاريخ دمشق (۹۴/۲۷) اسد الغابة (۲۸۳/۴)"}],[7591,"§۸۹۶۹ ۔ ہشام بن العاص اموی\nبیہقی نے دلائل میں بطریق شُرحبیل بن مسلم بحوالہ ہشام بن العاص اموی نقل کیا ہے، فرماتے ہیں: مجھے اور قریش کے ایک شخص کو ہرقل کی طرف بھیجا گیا، تاکہ ہم اسے اسلام کی دعوت دیں۔ ہم جبلہ کے پاس پہنچے ہم نے اسے اسلام کی طرف بلایا، تو اس پر سیاہ کپڑے تھے۔ انہوں نے اس کے بارے میں پوچھا، انہوں نے کہا: میں نے قسم کھائی ہے کہ انہیں اس وقت تک نہیں اتاروں گا جب تک تمہیں شام سے نکال نہ لوں۔ فرماتے ہیں: ہم نے اس سے کہا: اللہ کی قسم! تم اپنی اسی جگہ پر بیٹھے رہو گے اور ہم تمہارا اتنا بڑا ملک لے لیں گے جس کی ہمیں ہمارے نبی صلی اللہ علیہ وسلم نے اطلاع دی ہے۔ وہ کہنے لگا: تم ایسا کام کر سکتے ہو، پھر ان کا وہ واقعہ ذکر کیا جس میں وہ ہرقل کے پاس جاتے اور علیحدگی میں اس سے ملتے ہیں، پھر اس نے ایک صندوقچی نکالا، جس میں انبیاء کی نشانیاں اور صفات تھیں، یہاں تک کہ اس نے ان کے سامنے حضور صلی اللہ علیہ وسلم کی تصویر نکالی جو سفید تھی، کہنے لگا: اسے پہچانتے ہو؟ فرماتے ہیں: ہم رو پڑے اور کہنے لگے: ہاں! تو وہ اٹھ کر بیٹھ گیا، اس نے کہا: اللہ کی قسم! یہ وہی ہے؟ ہم نے کہا: ہاں! تو وہ تھوڑی دیر خاموش رہ کے کہنے لگا: یہ آخری خانہ تھا، میں نے اس لیے جلدی کی کہ دیکھوں کہ تمہارے پاس کیا ہے؟ اس کے بعد اس نے کہا: اگر اپنی بادشاہت سے نکلنے کی وجہ سے میرا دل خوش ہوتا تو میں یہ چاہتا کہ میں تمہارے شیر کا اس کی بادشاہت میں مرتے دم تک غلام رہتا۔ فرماتے ہیں: جب ہم واپس آئے، سیدنا ابو بکر رضی اللہ عنہ سے بیان کیا کہ آپ صلی اللہ علیہ وسلم نے فرمایا: اگر اللہ اس کے ساتھ بھلائی کا ارادہ کرے تو کرے، پھر کہنے لگے: ہمیں رسول اللہ صلی اللہ علیہ وسلم نے بتایا ہے کہ ان نصاریٰ اور یہود کو نبی صلی اللہ علیہ وسلم کی علامات کا پتا تھا۔\nعدی بن کعب کے حالات میں اس واقعے سے ملتا جلتا واقعہ بیان ہو چکا ہے، لیکن اس میں ہے کہ وہ ہشام بن العاص السہمی تھے۔ واللہ اعلم!"],[7592,"§۸۹۷۰ ۔ ہشام بن العاص بن ہشام\n(1) ابن مغیرہ بن عبداللہ بن عمر بن مخزوم، ابو جہل کے بھتیجے ہیں، ان کے والد غزوہ بدر میں قتل ہوئے۔ بعض کا قول ہے: انہیں سیدنا عمر رضی اللہ عنہ نے قتل کیا۔ ابو عمر(2) کا قول ہے: یہ وہی ہیں جو فتح مکہ کے دن رسول اللہ صلی اللہ علیہ وسلم کے ہاں آئے، آپ صلی اللہ علیہ وسلم کی سر مبارک سے کپڑا ہٹ گیا تو اس نے مہر نبوت پر ہاتھ رکھا۔ آپ صلی اللہ علیہ وسلم نے ان کا ہاتھ ہٹایا پھر ان کے سینے پر تین دفعہ ہاتھ مارا اور فرمایا: ”اے اللہ! اس سے کھوٹ اور حسد کو دور فرما“۔  تین بار ایسا فرمایا۔ یہ زبیر بن بکار کی کتاب میں ہے، انہوں نے اپنی کتاب میں بحوالہ اوقص، انہوں نے حماد بن سلمہ کے حوالے سے نقل کیا ہے۔ فرماتے ہیں: جب فتح مکہ کا دن تھا، ہشام بن العاص آئے پھر ان کا ذکر کیا، اس کے آخر میں فرماتے ہیں: اوقص فرماتے تھے، سب سے کم حسد ہمارے ساتھیوں میں تھا پھر بطریق ابن شہاب نقل کیا ہے، سیدنا عمر رضی اللہ عنہ نے سعید بن العاص اموی سے کہا: میں نے تمہارے باپ کو قتل کیا ہے، تم نے میرے ماموں عاص بن ہشام کو قتل کیا ہے۔","",{"fn":"(1) اسد الغابة (۵۳۷۶) الاستيعاب (۲۷۱۳) تجريد (۱۲۰/۲)\n(2) اسد الغابة (۱۰۱/۴)"}],[7593,"§۸۹۷۱ ۔ ہشام بن عامر\nابن امیہ انصاری، ان کا ذکر اور نسب، ان کے والد کے سوانح میں گزر چکا ہے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کیا، ان کی حدیث مسلم کے پاس ہے، ان سے سعید بن جبیر، حمید بن ہلال اور دوسرے لوگوں نے روایت کی۔\nابن مبارک نے زہد میں بطریق جعفر بن زید نقل کیا ہے۔ فرماتے ہیں: ہم ایک غزوے میں کابل کی طرف نکلے، لشکر میں صلہ بن اشیم تھے۔ پھر ان کا قصہ ذکر کیا کہ وہ اور ہشام بن عامر نے نیزوں، تلواروں سے دشمن پر حملہ کر دیا اور قتل کرنے لگے۔ فرماتے ہیں: دشمن نے کہا: عرب کے دو آدمیوں نے ہمارے ساتھ یہ کیا ہے، اگر وہ جنگ کریں تو کیا حال ہوگا؟ یعنی وہ شکست کھا گئے۔ فرماتے ہیں: ابو ہریرہ رضی اللہ عنہ سے کہا گیا: ہشام بن عامر نے اپنے آپ کو ہلاکت میں ڈالا تو سیدنا ابو ہریرہ رضی اللہ عنہ نے فرمایا: نہیں! بلکہ انہوں نے اس آیت پر عمل کیا(1) لوگوں میں سے بعض وہ ہیں جو اللہ کی رضا چاہنے کے لیے اپنے نفس کو بیچ ڈالتے ہیں۔(2)\nبعض کا قول ہے: ان کا نام شہاب تھا، رسول اللہ صلی اللہ علیہ وسلم نے ان کا نام ہشام رکھا، بصرہ میں فروکش ہوئے، زیادہ زمانے تک زندہ رہے۔","",{"fn":"(1) لسان الميزان (۸۷/۵)\n(2) سورة البقرة الآية (۲۰۷)"}],[7594,"§۸۹۷۲ ۔ ہشام بن عقبہ\nابن ربیعہ، بعض کا قول ہے: وہ ابو حذیفہ کا نام ہے، کنیتوں میں ان کا ذکر آئے گا۔"],[7595,"§۸۹۷۳ ۔ ہشام بن عقبہ\nابن ابی معیط اموی۔ ان کے والد بدر کے دن حالت کفر میں قتل ہوئے، مسلمان فتح مکہ میں سے ہیں، ان کے پوتے ہشام بن معاویہ بن ہشام قُنّسرین پر حضرت عمر بن عبد العزیز کی طرف سے گورنر تھے۔"],[7596,"§۸۹۷۴ ۔ ہشام بن عُمَارہ\nابن ولید بن مغیرہ بن عبداللہ بن عمر بن مخزوم مخزومی ہیں، ابو حذیفہ بخاری نے مبتدا میں ذکر کیا ہے کہ وہ یرموک کی جنگ غسل میں ۱۳ھ میں شہید ہوئے۔\nمیں کہتا ہوں: ان کے والد عمرو بن العاص کے ساتھ حبشہ میں تھے، نجاشی کو ان کے بارے میں بھڑکایا گیا، یہاں تک کہ اس نے حکم دیا کہ ان کے ذکر کے سرے میں ہوا بھری جائے، جس سے ان کا عقلی توازن جاتا رہا۔ وہ جنگلی جانوروں کے ساتھ پھرتے یہاں تک کہ خلافت عمر رضی اللہ عنہ میں ان کی وفات ہوگئی۔ وہ اور ان کے بیٹے حبشہ کی طرف گئے، مسلمان فتح مکہ میں سے ہیں، انہوں نے ان کا ذکر نہیں کیا۔ وہ ہماری شرط کے مطابق ہے، ولید بن عمارہ کے سوانح میں قصہ آئے گا۔"],[7597,"§۸۹۷۵ ۔ ہشام بن عمرو\n(1) ابن ربیعہ بن حارث بن حبیب، ابن جذیمہ بن مالک بن حسل بن عامر بن لوی بن غالب قرشی عامری۔ ابن اسحاق نے ان لوگوں میں ان کا ذکر کیا ہے، جنہیں تالیف قلب کے لیے نبی کریم صلی اللہ علیہ وسلم نے حنین کی غنیمتوں میں سے سو(۱۰۰) سے کم اونٹ دیے، یہ وہی ہیں جو اس عہد کو توڑنے کے لیے گئے جسے قریش نے بنو ہاشم کے بارے میں لکھا تھا، جب وہ شعب ابو طالب میں محصور تھے، ان دنوں میں وہ بہت آتے جاتے تھے۔ ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔ فرماتے ہیں: خلیفہ بن خیاط نے ان کا ذکر کیا ہے۔ فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم نے انہیں پچاس(۵۰) اونٹ دیے۔ ابن اسحاق(2) نے عہد توڑنے کے قصے میں ان کا ذکر کیا ہے، انہوں نے اس کے لیے اپنے آپ کو خطرے میں ڈالا، اللہ ان پر رحم کرے۔","",{"fn":"(1) الاستيعاب (۲۷۱۵) تجريد (۱۲۰/۲)\n(2) السيرة النبوية (۱۷/۲)"}],[7598,"§۸۹۷۶ ۔ ہشام بن قُدیک\nمندر بن خلدہ میں ان کی ایک حدیث ہے، تجرید میں ان کا ذکر ہے۔"],[7599,"§۸۹۷۷ ۔ ہشام بن ولید\nبن مغیرہ مخزومی، خالد کے بھائی ہیں، ابو عمر کا قول ہے: ان لوگوں میں ان کا ذکر ہے، جنہیں تالیف قلب کے لیے دیا گیا۔\nعبد الرزاق(1) نے بطریق سعید بن مسیب ذکر کیا ہے، فرماتے ہیں: جب سیدنا ابو بکر رضی اللہ عنہ کی وفات ہوئی تو لوگ ان پر رونے لگے تو سیدنا عمر رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میت کو زندہ لوگوں کے رونے کی وجہ سے عذاب دیا جاتا ہے“۔ پھر بھی وہ روتے رہے، تو انہوں نے ہشام بن ولید سے کہا: جاؤ اور عورتوں کو باہر نکالو۔ سیدہ عائشہ رضی اللہ عنہا نے فرمایا: تم خود ہی چلے جاؤ۔\nسیدنا عمر رضی اللہ عنہ نے فرمایا: جاؤ! میں نے تمہیں اجازت دی ہے، تو سیدہ عائشہ رضی اللہ عنہا فرمانے لگیں: اے بیٹے! کیا تم مجھے نکالو گے؟ انہوں نے کہا: میں نے آپ کو اجازت دی، تو عورتیں ایک ایک کر کے باہر آنے لگیں یہاں تک کہ ام فروہ بنت ابی قحافہ بھی باہر آگئیں۔\nاسے ابن سعد نے دوسرے طریق سے نقل کیا ہے۔ اس میں ہے: سیدنا عمر رضی اللہ عنہ نے انہیں نوحہ کرنے سے روکا، وہ نہ رکے تو ہشام بن ولید سے کہا: میرے پاس ابو قحافہ کی بیٹی یعنی سیدہ عائشہ رضی اللہ عنہا کی پھوپھی کو بھیجو، پھر قصہ ذکر کیا۔(2) وہ بخاری رحمہ اللہ کے ہاں تعلیقاً اختصار کے ساتھ ہے، مرزبانی نے معجم الشعراء میں ان کے اشعار نقل کیے ہیں، جس میں وہ سیدنا عثمان بن عفان رضی اللہ عنہ کو مخاطب کر رہے ہیں: عطا\n”میری زبان طویل ہے، اس کی اذیت سے بچ، میری تلوار، میری زبان سے بھی زیادہ طویل ہے“۔","",{"fn":"(1) مصنف عبد الرزاق (۶۶۹۲) (۶۶۷۵)\n(2) مسلم (۲۱۳۹) ابو داود"}],[7600,"§۸۹۷۸ ۔ ہشام\nبے نسبت۔ بخاری رحمہ اللہ نے ادب المفرد میں بطریق سعید بن ہشام، بحوالہ سیدہ عائشہ رضی اللہ عنہا نقل کیا ہے، فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم کے پاس شہاب نامی شخص کا ذکر کیا گیا، آپ صلی اللہ علیہ وسلم نے فرمایا: ”تم ہشام ہو“۔ ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے، فرماتے ہیں: ممکن ہے کہ وہ ہشام بن عامر یعنی سعد کے والد ہوں پھر بطریق یحییٰ بن موسیٰ عنجار بحوالہ زینب بنت سعد، انہوں نے اپنے والد کے حوالے سے نقل کیا ہے کہ ان کے دادا جن کا نام ہشام بن عامر ہے، رسول اللہ صلی اللہ علیہ وسلم کے پاس کھجوروں کی ایک ٹھیلی لائے، آپ صلی اللہ علیہ وسلم نے فرمایا: ”تمہارا کیا نام ہے؟“ انہوں نے کہا: میرا نام شہاب ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”جہنم کے ناموں میں سے ایک نام شہاب ہے، تم ہشام ہو“۔(1)\nمیں کہتا ہوں: ابو اسید وہ عبد الکریم بن ابی المخارق ہیں، احتمال ہے کہ سیدہ عائشہ رضی اللہ عنہا کی روایت میں جو راوی ہیں وہ کوئی اور ہیں۔ مسلم بن عبداللہ کے سوانح میں گزر چکا ہے کہ ان کا نام شہاب تھا، نبی کریم صلی اللہ علیہ وسلم نے ان کا نام بدل دیا۔","",{"fn":"(1) مستدرك حاكم (۲۷۵/۴) (۲۷۷/۴)"}],[7601,"§۸۹۷۹ ۔ ہشام (مولیٰ رسول اللہ صلی اللہ علیہ وسلم)\n(1) طبرانی، مطین، ابن قانع اور ابن مندہ وغیرہ نے بطریق ثوری بحوالہ ہشام مولیٰ رسول اللہ صلی اللہ علیہ وسلم کی حدیث روایت کی ہے۔ فرماتے ہیں: ایک شخص نبی کریم صلی اللہ علیہ وسلم کے پاس آیا اور عرض کیا، یا رسول اللہ! میری بیوی نا محرم کے ہاتھ کو نہیں لوٹاتی، آپ صلی اللہ علیہ وسلم نے فرمایا: ”اسے طلاق دے دو“۔ اس نے کہا: وہ مجھے پسند ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: ”پھر اسی حال میں اس سے نفع اٹھاؤ“۔(2)\nاسے عبداللہ بن عمر رضی اللہ عنہما نے بحوالہ جابر نقل کیا ہے، گویا وہ اسی راستے پر چلے۔ ابو عمر(3) نے ذکر کیا ہے کہ بعض کا قول ہے کہ ہشام جن کا ذکر کیا گیا۔ وہی سوال کرنے والے ہیں۔","",{"fn":"(1) الاستيعاب (۲۷/۷) تجريد (۱۲۰/۲)\n(2) ابو داود (۲۰۴۹) نسائي (۳۴۶۴) نصب الراية (۳۵۳/۳) تذكرة الموضوعات (۱۲۹)\n(3) الاستيعاب (۱۰۲/۴)"}],[7602,"§۸۹۸۰ ۔ ہُشیم\nبعض کا قول ہے: وہ ابو العاص بن ربیع کا نام ہے، ابو موسیٰ نے ان کا ذکر کیا ہے۔"],[7603,"§۸۹۸۱ ۔ ہلال بن امیہ\n(1) ابن عامر بن قیس بن عبد اعلم بن عامر بن کعب بن واقف انصاری واقفی۔ بدر میں اور بعد کے غزوات میں شریک ہوئے، مرارہ بن ربیع کی سوانح میں ان کی حدیث گزر چکی ہے۔ یہ ان تین لوگوں میں سے ہیں جن کی توبہ قبول ہوئی، شریک بن سحماء کے سوانح میں بھی ان کا ذکر گزر چکا ہے، صحیحین میں بروایت سعید بن جبیر بحوالہ ابن عمر ان کا ذکر ہے۔\nابن شاہین نے بطریق عطاء بن عجلان بحوالہ عکرمہ بن ہلال بن امیہ نقل کیا کہ وہ سیدنا عمر رضی اللہ عنہ کے پاس آئے، پھر لعان کا طویل قصہ نقل کیا، یہ اگر ثابت ہے کہ اس پر دلالت کرتا ہے کہ ہلال بن امیہ سیدنا معاویہ رضی اللہ عنہ کی خلافت تک زندہ رہے، یہاں تک کہ عکرمہ نے ان سے روایت کی۔ لیکن عطاء بن عجلان متروک راوی ہے، اسی طرح احتمال ہے کہ عکرمہ نے ان سے مرسل حدیث نقل کی ہے۔","",{"fn":"(1) اسد الغابة (۵۳۸۱) الاستيعاب (۲۷/۸) تجريد (۱۲۱/۲)"}],[7604,"§۸۹۸۲ ۔ ہلال بن امیہ خزاعی کعبی\nحدیث عمران بن حصین میں ان کا ذکر ہے، اسے بیہقی نے خلافات میں بطریق ابن وہب، بحوالہ خزینت بنت حصین، انہوں نے اپنے بھائی عمران سے نقل کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”کیا تم نے نہیں دیکھا کہ تمہارے ساتھی ہلال بن امیہ نے کیا کیا ہے، اگر میں کسی مومن کو کسی کافر کی وجہ سے قتل کرتا تو انہیں قتل کرتا، اسے فدیہ دے دو“۔ فرماتے ہیں: ہم نے ان کا فدیہ دے دیا اور بنو مدلح، جاہلیت میں بنو کعب کے حلیف تھے۔ ہم نے عموالی ابو علی بن خزیمہ کے جزو الثالث میں اسے عالی سند سے روایت کیا ہے، اس میں ہے: جب فتح مکہ کا دن ہوا تو ہلال بن امیہ نے ہذیل کے ایک شخص کو قتل کر دیا۔۔۔۔ (الحدیث)۔۔۔۔ بیہقی کا قول ہے: اسے واقدی رحمہ اللہ نے دوسرے طریق سے بحوالہ عبد الملک نقل کیا ہے، لیکن فرماتے ہیں: خراش بن امیہ۔\nمیں کہتا ہوں: یہ وہی شخص ہیں، ابن اسحاق نے جن کا ذکر کیا ہے۔ واللہ اعلم"],[7605,"§۸۹۸۳ ۔ ہلال بن ابی خولی\n(1) ابن عمرو بن زہیر بن خثیمہ بن ابی خُمر بن معاویہ بن حارث بن مالک بن عوف جعفی، ابن کلبی کا قول ہے: وہ اور ان کے دونوں بھائی خولی اور عبداللہ بدر میں شریک ہوئے، اسی طرح موسیٰ بن عقبہ نے بدری صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، ابن اسحاق نے ان کا ذکر نہیں کیا۔","",{"fn":"(1) اسد الغابة (۵۳۸۵) الاستيعاب (۲۷۲۱) تجريد (۱۲۱/۲)"}],[7606,"§۸۹۸۴ ۔ ہلال بن حارث\nابو حمراء، نبی کریم صلی اللہ علیہ وسلم کے مولیٰ ہیں۔ اپنی کنیت سے مشہور ہیں، کنیتوں میں ان کا ذکر آئے گا۔"],[7607,"§۸۹۸۵ ۔ ہلال بن سعد\n(1) جعفر مستغفری وغیرہ نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ ایک حدیث میں ان کا ذکر ہے۔ جسے عبد الرزاق(2) نے اپنے مصنف میں، بحوالہ ابن جریج نقل کیا ہے کہ مجھے صالح بن دینار نے بتایا کہ حضرت عمر بن عبد العزیز نے اپنے عامل کو شہد کے بارے میں لکھا، تمام شہد والے لوگ جمع ہوئے انہوں نے گواہی دی کہ سیدنا ہلال بن سعد رسول اللہ صلی اللہ علیہ وسلم کے پاس شہد لے کر آئے، آپ صلی اللہ علیہ وسلم نے فرمایا: ”یہ کیا ہے؟“ انہوں نے کہا: ہدیہ ہے، آپ صلی اللہ علیہ وسلم نے نوش فرمایا، پھر دوسری مرتبہ آئے تو کہا: صدقہ ہے، نبی کریم صلی اللہ علیہ وسلم نے اسے لینے کا حکم فرمایا اور اٹھا لینے کو کہا، اس وقت نہ عشروں کا ذکر کیا، نہ ہی نصف عشر کا۔ البتہ آپ نے وہ لے لیا۔\nانہوں نے حضرت عمر بن عبد العزیز رحمہ اللہ کو لکھا اور فرمایا: اگر ہمیں کچھ دے دیتے تو ہم لے لیتے تھے، ہم عشر وغیرہ طلب نہیں کرتے تھے، جو انہوں نے ہمیں دیا ہے، ہم نے لے لیا۔  اسے ابن مبارک نے بحوالہ ابن جریج مختصر ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۵۳۸۷) الاستيعاب (۲۷۲۲) تجريد (۱۲۱/۲)\n(2) مصنف عبد الرزاق (۶۱/۴)"}],[7608,"§۸۹۸۶ ۔ ہلال بن سلیم\nہلال بن ابی ہلال میں ان کا ذکر آئے گا۔"],[7609,"§۸۹۸۷ ۔ ہلال بن عمرو\nابن عمیر ثقفی، ہلال نامی اشخاص کے آخر میں ان کا ذکر آئے گا۔"],[7610,"§۸۹۸۸ ۔ ہلال بن مُرّہ اشجعی(1)\nصحیح حدیث میں ان کا ذکر ہے، اسے حارث بن ابی اسامہ، طبرانی، طحاوی، ابن مندہ نے بروایت سعید بحوالہ عبداللہ بن عتبہ نقل کیا ہے کہ سیدنا ابن مسعود رضی اللہ عنہ کے پاس ایک خاتون کے بارے میں سوال آیا، پھر بروع بنت واشق کا قصہ ذکر کیا، اس میں ہے اشجع قبیلے کے کچھ لوگ کھڑے ہوئے ان میں جراح بن سنان اور ابو سنان بھی تھے۔ انہوں نے کہا: ہم گواہی دیتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمارے درمیان بروع بنت واشق کے بارے میں اسی طرح فیصلہ کیا، ان کے شوہر ہلال بن مُرّہ تھے، جیسا کہ آپ نے فیصلہ کیا، طحاوی کے ہاں ہے: ہلال بن مروان، حارث نے ان کے والد کا نام نہیں لیا، ابن فتحون کا قول ہے: ایک جماعت نے یہ حدیث ذکر کی ہے، ان میں مسلم بن حجاج ہیں، ہلال کا نام نہیں ہے۔\nمیں کہتا ہوں: مسلم سے ان کی نسبت کے بارے میں نادانستہ غلطی ہوئی ہے، حدیث سنن میں ہے۔ جیسا کہ جراح کے سوانح میں گزر چکا ہے۔","",{"fn":"(1) المعجم الكبير (۱۹۹/۲۲) جامع المسانيد والسنن (۲۶۱/۱۲)"}],[7611,"§۸۹۸۹ ۔ ہلال بن مروان اشجعی\nپہلے والے سوانح میں ان کا ذکر ہے۔"],[7612,"§۸۹۹۰ ۔ ہلال بن معلیٰ\n(1) ابن لوذان بن حارثہ بن زید بن ثعلبہ بن عدی بن مالک بن زید مناۃ انصاری، بنو نجم بن خزرج میں سے ہیں، ابن اسحاق(2) نے بدر میں شریک ہونے والوں میں ان کا ذکر کیا ہے، وہیں شہید ہوئے، اسی طرح ابن حبان وغیرہ نے ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۵۳۹۲) الاستيعاب (۲۷۲۴) تجريد (۲۶۴/۲)\n(2) السيرة النبوية (۲۶۴/۲)"}],[7613,"§۸۹۹۱ ۔ ہلال اسلمی\n(1) اضاحی میں ان کی حدیث ہے۔ اسے امام احمد، ابن ماجہ نے حسن سند سے نقل کیا ہے، ابن حبان کا قول ہے: انہیں شرف صحابیت حاصل ہے۔ ابن مندہ نے ان کے لیے یہ عنوان قائم کیا ہے: ہلال بن ابی ہلال اور ابن قانع نے یہ لکھا ہے: ہلال بن مسلم۔","",{"fn":"(1) الاستيعاب (۲۷۲۶)"}],[7614,"§۸۹۹۲ ۔ ہلال\n(1) بنو ثعلبان میں سے ایک ہیں، شہد کے بارے میں ان کی حدیث ہے، ابو موسیٰ نے ان کے اور ہلال بن سعد کے درمیان فرق کیا ہے، صاحب تجرید کا قول ہے: بعض نے کہا کہ وہ ایک ہیں۔ ابو داود(2) نے بطریق عمرو بن حارث، عن ابیہ، عن جدہ فرماتے ہیں: بنو ثعلبان کے ایک شخص نبی کریم صلی اللہ علیہ وسلم کے پاس شہد کی مکھیوں کا عشر لے کر آئے اور آپ صلی اللہ علیہ وسلم سے سوال کیا کہ انہیں سلمہ نامی وادی دے دی جائے، آپ صلی اللہ علیہ وسلم نے انہیں یہ وادی دے دی، جب سیدنا عمر رضی اللہ عنہ خلیفہ بنے تو ان کی طرف سفیان بن وہب نے لکھا اور اس کے بارے میں سوال کیا، آپ نے انہیں لکھا: رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں جو ادا کرتے تھے، ادا کرتے رہیں۔ انہیں وہ وادی دے دو اور ان کا اکرام کرو ورنہ وہ بارانی زمین ہے جو چاہے اس سے نفع اٹھائے۔\nمیں کہتا ہوں: یہ قصہ ہلال بن سعد سے کئی وجوہات کی وجہ سے مختلف ہے، مغایرت ظاہر ہے۔","",{"fn":"(1) اسد الغابة (۵۳۸۸)\n(2) ابو داود (۱۶۰۰)"}],[7615,"§۸۹۹۳ ۔ ہلال ، مولیٰ مغیرہ\n(1) ابن شعبہ، ابو عبد الرحمن سلمی نے اہل صفہ میں ان کا ذکر کیا ہے، ابن بشکوال کا قول ہے: زہیر بن عباد کی کتاب المتقین میں ان کا ذکر ہے، ابو نعیم نے حلیہ میں بطریق عطاء خراسانی، بحوالہ ابو ہریرہ رضی اللہ عنہ نقل کیا ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اس دروازے سے وہ شخص داخل ہوگا، اللہ تعالیٰ جس کی طرف دیکھتا ہے“۔ فرماتے ہیں: سیدنا ہلال داخل ہوئے، آپ نے ان سے کہا: ”اے ہلال! مجھ پر درود بھیجو“۔ اور ان سے کہا: ”جو تمہیں اللہ عز و جل کا پسندیدہ بنائے اور تمہارا اس کی وجہ سے اکرام کیا جائے“۔ اس کی سند ضعیف اور منقطع ہے۔\nابو نعیم نے معرفۃ الصحابہ میں اس سے صرف نظر کیا ہے، ابو موسیٰ نے ابن مندہ کی کتاب پر اپنے استدراک میں ان کا ذکر کیا ہے، احمد بن منصور بن یوسف مذکور نے بروایت ابو ہریرہ بہت طویل نقل کیا ہے، یہ ابو موسیٰ کا قول ہے۔\nابو نعیم نے حلیہ میں اویس قرنی کے سوانح میں بطریق شجاع، بحوالہ ابو ہریرہ اسی مفہوم میں نقل کیا ہے۔ لیکن ہلال کا نام نہیں لیا، ابو داود کی حدیث میں ان کا ذکر ہے، لیکن مغیرہ کی طرف ان کی نسبت نہیں۔ حکیم ترمذی نے نوادر الاصول میں ایک سو پچیس(۱۲۵) اصول میں بطریق یحییٰ بن ابی طلحہ، بحوالہ ابو درداء ان کا ذکر کیا ہے، فرماتے ہیں: میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ مسجد میں تھا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اس دروازے سے ایسا شخص داخل ہوگا جو اہل جنت میں سے ہے“۔(2) رسول اللہ صلی اللہ علیہ وسلم نماز کے لیے کھڑے ہوئے، میں اس دروازے سے داخل ہوا، میں نے کسی کو نہیں دیکھا، پھر میں واپس آیا، دروازے سے داخل ہوا اور رسول اللہ صلی اللہ علیہ وسلم کے پاس بیٹھ گیا، آپ صلی اللہ علیہ وسلم نے فرمایا: ”اے ابو درداء! تم نہیں ہو“۔ پھر ایک حبشی آیا اور اس دروازے سے داخل ہوا، اس پر اون کا جبہ تھا۔ اس میں چہرے کا پوند تھا، وہ اپنی نگاہ آسمان کی طرف کیے ہوئے تھا۔ یہاں تک کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور آپ صلی اللہ علیہ وسلم کو سلام کیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اے ہلال! تمہارا کیا حال ہے؟“ انہوں نے کہا: یا رسول اللہ! خیریت سے ہوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اے ہلال! ہمارے لیے دعا اور استغفار کرو“۔ انہوں نے کہا: یا رسول اللہ! اللہ آپ سے راضی ہو اور آپ کی مغفرت فرمائے، پھر طویل حدیث ذکر کی۔","",{"fn":"(1) تجريد (۱۲۲/۲)\n(2) الادب المفرد (۲۵۰)"}],[7616,"§۸۹۹۴ ۔ ہلال ثقفی\nابن جریج نے بطریق عکرمہ اس آیت کے بارے میں روایت کیا ہے: ﴿اللہ سے ڈرو اور جو سود باقی رہ گیا ہے اسے چھوڑ دو﴾۔(1) بنو عمرو بن عمیر کے بارے میں نازل ہوئی، فرماتے ہیں: مسعود، عبد یالیل، حبیب بن ربیعہ، اور ہلال اسلام لائے۔ یہ وہ لوگ تھے جن کا بنو مغیرہ پر سود تھا۔\nمیں کہتا ہوں: اسے طبری نے تفسیر سنید سے، ان کی روایت سے، بحوالہ عکرمہ نقل کیا ہے، اس سے پہلے، بحوالہ ابن جریج حدیث نقل کی ہے، فرماتے ہیں: ثقیف نے نبی کریم صلی اللہ علیہ وسلم سے اس بات پر صلح کی تھی کہ ان کا جو سود لوگوں پر ہے، وہ ان کا ہے اور جو لوگوں کا ان پر ہے، وہ ختم ہے۔ جب فتح مکہ کا واقعہ ہوا تو رسول اللہ صلی اللہ علیہ وسلم نے مکہ پر عتاب بن اسید کو زکوٰۃ کی وصولی پر مقرر کیا۔ ثقیف کا معاملہ بنو مغیرہ کے ساتھ تھا، بنو عمرو بن عمیر، بنو مغیرہ سے اپنا سود لینے آئے، انہوں نے دینے سے انکار کیا، وہ معاملہ سیدنا عتاب کے پاس لے گئے، سیدنا عتاب رضی اللہ عنہ نے نبی کریم صلی اللہ علیہ وسلم کو خط لکھا، اس موقع پر یہ آیت نازل ہوئی: ﴿اے ایمان والو! اللہ سے ڈرو اور جو سود باقی رہ گیا ہے اسے چھوڑ دو﴾ (الآیۃ)  ابن جریج کا قول ہے: عکرمہ نے کہا: وہ کہتے ہیں کہ وہ مسعود، عبد یالیل، حبیب اور ربیعہ تھے، جو بنو عمرو بن عمیر ہیں، یہ وہی لوگ ہیں جن کا دوسرے لوگوں پر سود تھا، وہ اسلام لائے۔ پھر پانچ(۵) بیٹوں کا ذکر کیا۔\nمیں کہتا ہوں: جس کا آخر میں اضافہ کیا وہ ہلال ہیں، احتمال ہے کہ وہ چاروں کا بھائی ہو، یہ احتمال بھی ہے کہ وہ ان کا بھائی نہ ہو بلکہ ثقیف سے ہو، فتح مکہ سے پہلے ثقیف سے صلح ہوئی اس میں تردد ہے، میں نے اسباب النزول میں اس کی وجہ کا ذکر کر دیا ہے۔","",{"fn":"(1) سورة البقرة الآية (۲۷۸)"}],[7617,"§۸۹۹۵ ۔ مہلب طائی\n(1) ابن درید کا قول ہے، نبی کریم صلی اللہ علیہ وسلم کے پاس ایک گنجا شخص آیا، آپ صلی اللہ علیہ وسلم نے اس کے سر پر ہاتھ پھیرا تو اس کے بال اگ آئے۔ اس کا نام مہلب پڑ گیا، ابن درید کا قول ہے: وہ اقرع تھے، پھر افرع ہوگئے، مہلب کا مطلب بہت زیادہ بالوں والا ہے۔\nمیں کہتا ہوں: وہ یزید بن قُتافہ ہیں، بعض کا قول ہے: ابن یزید بن عدی بن قُتافہ، اسی طرح ابن کلبی کا قول ہے، لیکن ان کا نام اسلام ملیا ہے۔ ابن کلبی رحمہ اللہ کا قول ہے: ان کے بارے میں شاعر کہتے ہیں: عطا\n”پہلے تو اس کے سر پر ایک بال بھی نہ تھا، پھر وہ گھنے زلفوں والا ہو گیا“۔\nبلب نے نبی کریم صلی اللہ علیہ وسلم سے روایت کیا، ان سے ان کے بیٹے قیصر نے روایت کیا، ابو داود، ترمذی وغیرہ(2) میں ان کی حدیث ہے، ابن سعد(3) نے مسلمان فتح مکہ میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۵۳۹۶)\n(2) ابو داود (۱۰۳۹) نسائی (۱۲۲۵) ترمذی (۲۹۰) (۳۹۵)\n(3) طبقات الکبریٰ (۲۰/۶)"}],[7618,"§۸۹۹۶ ۔ ہلواب\nاسمر بن ساعدہ میں ان کا ذکر گزر چکا ہے۔"],[7619,"§۸۹۹۷ ۔ ہمام بن حارث\n(1) ابن ہمزہ، ابو عمر کا قول ہے: بدر میں شریک ہوئے، مجھے ان کی کوئی روایت معلوم نہیں۔","",{"fn":"(1) اسد الغابة (۵۳۹۸) تجريد (۱۲۲/۲)"}],[7620,"§۸۹۹۸ ۔ ہمام بن ربیعہ عصری\nرشاطی نے ان لوگوں میں ان کا ذکر کیا ہے جو عبد قیس سے وفد میں نبی کریم صلی اللہ علیہ وسلم کے پاس آئے، وہ ان کے سردار اور شہسوار تھے۔ ابو عبیدہ معمر بن مثنیٰ نے ان کا ذکر کیا ہے۔\nمیں کہتا ہوں: صحار بن عباس میں ان کا ذکر گزر چکا ہے۔"],[7621,"§۸۹۹۹ ۔ ہمام بن زید\n(1) ابن وابصہ وابصی، حاکم نے ان لوگوں میں ان کا ذکر کیا ہے جو صحابہ رضی اللہ عنہم میں سے نیشاپور داخل ہوئے، فرماتے ہیں: وہ صحابہ رضی اللہ عنہم میں سے ہیں، سیدنا عبد اللہ بن عامر کے ساتھ آئے اور نیشاپور کو اپنا وطن بنایا، وہیں وفات پائی، ان کی وہاں اولاد ہے، پھر بطریق سہیل بن عمار نقل کیا ہے، فرماتے ہیں: میں اپنے دادا عبد اللہ بن محمد کے پاس آیا، ان کے پاس یحییٰ بن یحییٰ، بشر بن قاسم، حسین بن ولید عیادت کرنے کے لیے آئے۔ انہوں نے ان کی عمر کے بارے میں پوچھا اور یہ کہ انہوں نے لوگوں میں سے کس کا زمانہ پایا ہے؟ انہوں نے بتایا کہ انہوں نے ہمام بن زید وابصی نامی شیخ کا زمانہ پایا۔ فرماتے ہیں کہ میں نے انہیں کہتے ہوئے سنا: مجھے نبی کریم صلی اللہ علیہ وسلم نے چادر دی، پھر واقعہ ذکر کیا۔ یحییٰ بن یحییٰ فرماتے ہیں: ہم امید رکھتے ہیں کہ ہم ان لوگوں میں سے ہیں جن کے بارے میں نبی صلی اللہ علیہ وسلم نے فرمایا: ”اس شخص کے لیے خوشخبری ہے جس نے مجھے دیکھا، اور جس نے مجھے دیکھنے والوں کو دیکھا“۔(2) حاکم کا قول ہے: ابو طیب کرامیشی فرماتے ہیں: ابراہیم بن ابی طالب، ہمام بن زید کا حال بیان کرتے ہیں اور عبد اللہ بن محمد کو ثقہ قرار دیتے ہیں۔ دوسرے طریق سے، بحوالہ سہیل بن عمار مروی ہے کہ ہم سے میرے دادا نے بیان کیا کہ میں نے ہمام بن زید بن وابصہ کو دیکھا ہے، تو وہ نبی کریم صلی اللہ علیہ وسلم کے صحابہ رضی اللہ عنہم میں سے تھے، برجان میں فروکش تھے، جب وہ شہر میں داخل ہوتے تو ہر چھوٹا بڑا ان کے پاس جاتا اور انہیں سلام کرتا۔ پھر قصہ ذکر کیا۔ اسے خطیب نے محمد بن محمد بن یحییٰ کے سوانح میں، دوسرے طریق سے، بحوالہ سہیل بن عمار نقل کیا ہے کہ مجھ سے میرے دادا عبد اللہ بن محمد نے بیان کیا کہ ہمام بن وابصہ جب کوفہ میں داخل ہوتے تو اپنے پاس سے گزرنے والے ہر مرد و عورت اور بچے کو سلام کرتے اور فرماتے: رسول اللہ صلی اللہ علیہ وسلم نے ہمیں حکم دیا ہے کہ ہم سلام کو پھیلائیں۔\nسہیل کا قول ہے: میں نے یہ روایت یحییٰ بن یحییٰ سے بیان کی ہے، وہ حسین بن ولید اور بشر بن قاسم آئے، ان لوگوں نے میرے دادا سے حدیث کا مذاکرہ کیا، یہاں تک کہ انہوں نے ان سے یہ روایت سنی۔ یحییٰ بن یحییٰ یا بشر کا قول ہے: ہم اس حدیث کے بارے میں بات کر رہے تھے: ”اس شخص کے لیے خوشخبری ہے جس نے مجھے دیکھنے والے کو دیکھا“۔ اسی طرح ہمام بن وابصہ نے کہا: گویا انہوں نے انہیں ان کے دادا کی طرف منسوب کیا ہے۔ اس کے علاوہ دوسرا عنوان قائم کیا ہے۔","",{"fn":"(1) تجريد (۱۲۳/۲)\n(2) مسند احمد (۲۶۸/۵) مجمع الزوائد (۵۴/۱۰) المعجم الکبیر (۸۰۹) مشکوٰۃ المصابیح (۶۲۸۱) الدر المنثور (۳۷/۱) المطالب العالیہ (۴۲۲۱) (۴۲۴۲) کنز العمال (۲۴۹) (۳۲۴۲۷) کشف الخفاء (۶۲/۲) الکامل فی الضعفاء (۱۴۲۷/۴)"}],[7622,"§۹۰۰۰ ۔ ہمام بن عروہ\nابن مسعود ثقفی، ان کے والد کے سوانح میں ان کا نسب گزر چکا ہے، ابن سکن کا قول ہے، بعض نے کہا: انہیں شرف صحابیت حاصل ہے، محمد بن اسحاق ثقفی نے ان کی حدیث، بحوالہ یعقوب بن زید بن ہمام بن عروہ، عن ابیہ، عن جدہ فرماتے ہیں: میں نے نبی کریم صلی اللہ علیہ وسلم کو طائف کے ایک طرف اترے، ہم نے آپ کی تیر برسائے اور آپ صلی اللہ علیہ وسلم کا بائیں ہاتھ سے اشارہ کر رہے تھے۔\nمیں کہتا ہوں: عروہ بن مسعود واقعہ طائف کے بعد اسلام لائے، مدینہ میں نبی کریم صلی اللہ علیہ وسلم کے پاس وفد میں آئے، اسلام لائے اور ان کا اسلام سنور گیا۔ پھر طائف کی طرف لوٹ گئے، ان لوگوں کو اسلام کی طرف بلایا، انہوں نے ان کو قتل کر دیا۔ ان کی اولاد کا صحابی ہونا ممکن ہے۔\nکئی مرتبہ گزر چکا ہے کہ مکہ اور طائف میں قریش اور ثقیف میں سے ہر شخص حجۃ الوداع کے موقع پر اسلام لا چکا تھا اور حاضر تھا۔\nبلاذری نے بیان کیا ہے کہ فارعہ ان ہمام کی بیٹی، یوسف بن حکم بن ابی عقیل بن عروہ بن مسعود ثقفی کی زوجہ تھیں، ان سے مشہور امیر حجاج بن یوسف پیدا ہوئے۔"],[7623,"§۹۰۰۱ ۔ ہمام بن مالک\nابن ہمام بن معاویہ عبدی، ابن کلبی کا قول ہے: وہ اور ان کے بھائی عبیدہ نبی کریم صلی اللہ علیہ وسلم کے پاس وفد میں آئے۔"],[7624,"§۹۰۰۲ ۔ ہمام بن معاویہ\n(1) ابن شہاب، وفد عبد القیس سے ہیں، ابن سعد(2) نے ان کا ذکر کیا ہے۔","",{"fn":"(1) تجريد (۱۲۲/۲)\n(2) طبقات الکبریٰ (۴۲۱/۵)"}],[7625,"§۹۰۰۳ ۔ ہمام بن نفیل سعدی\n(1) ابو علی بن سکن نے ان کا ذکر کیا ہے اور بطریق عاصمہ بنت عاصم بن ہمام سعدی نقل کیا ہے کہ مجھ سے میرے والد نے حوالہ اپنے والد ہمام بن نفیل بیان کیا، فرماتے ہیں: میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، میں نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم! ہم نے کنواں کھودا ہے، اس کا پانی نمکین ہے۔ فرماتے ہیں: آپ صلی اللہ علیہ وسلم نے مجھے ایک برتن دیا، اس میں پانی تھا، آپ صلی اللہ علیہ وسلم نے فرمایا: ”اسے اس میں ڈال دو“۔ میں نے ایسا ہی کیا، جس سے اس کا پانی میٹھا ہو گیا۔","",{"fn":"(1) تجريد (۱۲۳/۲)"}],[7626,"§۹۰۰۴ ۔ ہمام بن وابصہ\nہمام بن زید میں ان کا ذکر گزر چکا ہے۔"],[7627,"§۹۰۰۵ ۔ ہمیل بن دمون\n(1) ابن عبید بن مالک ثقفی، انہوں نے اور ان کے بھائی قیصر نے نبی کریم صلی اللہ علیہ وسلم سے بیعت کی، ابن اکولا نے ان کا ذکر کیا ہے، ابو حسن مدائنی نے کتاب اخبار ثقیف میں ان کا ذکر کیا ہے، فرماتے ہیں: وہ حضری ہیں، وہ اور ان کے بھائی ثقیف کے حلیف ہیں۔ طائف میں رہائش تھی، پھر ان کے بھائی قیصر کا جبوا مالک کے ساتھ واقعہ پیش آیا، انہوں نے ان کو قتل کرنے کا ارادہ کیا وہ اور ان کے بھائی اور شریر ید بن سوید وہاں سے بھاگ گئے، وہ اسلام لے آئے۔ یہ ثقیف کے اسلام لانے اور ان کے وفد کے آنے سے پہلے کا واقعہ ہے۔","",{"fn":"(1) تجريد (۱۲۲/۲)"}],[7628,"§۹۰۰۶ ۔ ہَنَّاد\n(1)","",{"fn":"(1) بیاض فی الاصل"}],[7629,"§۹۰۰۷ ۔ ہند بن اسماء\n(1) ابن حارثہ اسلمی، ان کے والد اسماء کے سوانح میں ان کا نسب گزر چکا ہے۔ بخاری رحمہ اللہ کا قول ہے: انہیں شرف صحابیت حاصل ہے۔ ابن سکن نے کہا: انہیں شرف صحابیت حاصل ہے اور خلافت معاویہ میں وفات پائی۔ احمد بن حنبل(2) نے بطریق ابن اسحاق نقل کیا ہے کہ مجھ سے عبد اللہ بن ابی بکر نے بحوالہ حبیب بن ہند بن اسماء اسلمی، بحوالہ اپنے والد نقل کیا ہے کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے میری قوم قبیلہ اسلم کی طرف بھیجا اور فرمایا: ”اپنی قوم کو مدد کرو کہ اس دن یعنی عاشوراء کے دن روزہ رکھیں، جسے تم اس حالت میں پاؤ کہ اس نے پہلے وقت تو کھا لیا ہے وہ دن کی آخری گھڑی میں روزہ رکھے“۔ ابن کلبی کا خیال ہے کہ جنہیں حکم دیا گیا، وہ ہند بن حارث، ان کے چچا ہیں۔ ابو عمر نے ان کی پیروی کی ہے۔","",{"fn":"(1) تجريد (۱۲۲/۲)\n(2) مسند احمد (۴۸۴/۳)"}],[7630,"§۹۰۰۸ ۔ ہند بن حارثہ اسلمی\n(1) پہلے والے صحابی کے چچا ہیں، ابن حبان کا قول ہے: انہیں شرف صحابیت حاصل ہے۔ ابن قانع نے بطریق عبد الرحمن بن حرملہ، بحوالہ یحییٰ بن ہند بن حارثہ، عن ابیہ نقل کیا ہے۔ وہ اور ان کے بھائی اسماء بن حارثہ اصحاب حدیبیہ میں سے ہیں کہ نبی کریم صلی اللہ علیہ وسلم قبیلہ اسلم کے لوگوں کے پاس سے گزرے، جو تیر اندازی کر رہے تھے۔ تو فرمایا: اے بنو اسماعیل! تیر اندازی کرو، تمہارا باپ تیر انداز تھا۔\nابن ابی حاتم کا گمان ہے کہ ہند بن اسماء بن حارثہ اپنے دادا کی طرف منسوب ہیں، بغوی نے بیان کیا ہے کہ وہ بیعت الرضوان میں اپنے سات(۷) بھائیوں کے ساتھ شریک تھے۔ وہ یہ ہیں: ہند، اسماء، خراش، ذویب، سلمہ، فضالہ، مالک اور حمران۔\nفرماتے ہیں: اس میں ان کی تعداد کے برابر بھائی شریک نہ تھے، اس میں مقرن کی اولاد کو شامل کیا ہے۔\nابو ہریرہ رضی اللہ عنہ سے مروی ہے کہ میں نے ہند اور اسماء کو بہت عرصہ تک آپ صلی اللہ علیہ وسلم کی خدمت کرتے ہوئے دیکھا۔ ابو عمر کا قول ہے:(2) ہند سے اس حدیث کو صرف ان کے بیٹے نے روایت کیا ہے، فرماتے ہیں: وہ یحییٰ کے والد ہیں، جن سے عبد الرحمن بن حرملہ نے روایت کیا۔\nمیں کہتا ہوں: انہیں اس میں وہم ہوا ہے، حبیب یحییٰ کے بھائی نہیں بلکہ ہند جو یحییٰ کے والد ہیں وہ حبیب کے چچا زاد ہیں۔","",{"fn":"(1) الاستيعاب (۲۷۲۷)\n(2) الاستيعاب (۱۰۵/۴)"}],[7631,"§۹۰۰۹ ۔ ہند بن صامت\nابن عبد اللہ بن صامت بن سدوسی بجی، نبی کریم صلی اللہ علیہ وسلم کے پاس وفد میں آئے، آپ صلی اللہ علیہ وسلم نے انہیں حکم دیا کہ ٹھوڑی کے نیچے پگڑی کے عمامہ باندھیں۔ فرمایا: یہ حضرت جبرائیل علیہ السلام کے عمامہ باندھنے کا انداز ہے۔ ابو علی بحری نے اپنی کتاب نوادر میں ان کا ذکر کیا ہے، فرماتے ہیں: یہ جبر ولیہ کا عمامہ باندھنے کا انداز ہے۔ ہند کی کنیت ابو جرول تھی، رشاطی کا قول ہے: ابو عمر اور ابن فختون نے ان کا ذکر نہیں کیا، ابن بشکوال نے اپنے استدراک میں ان کا ذکر کیا ہے۔"],[7632,"§۹۰۱۰ ۔ ہند بن ابی ہالہ التمیمی\n(1) نبی کریم صلی اللہ علیہ وسلم کے پروردہ ہیں، ان کی والدہ سیدہ خدیجہ رضی اللہ عنہا، نبی کریم صلی اللہ علیہ وسلم کی زوجہ ہیں۔ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کیا، ان سے سیدنا حسن بن علی رضی اللہ عنہ نے نبی کریم صلی اللہ علیہ وسلم کی صفات کے بارے میں روایت کی، اسے ترمذی، بغوی، طبرانی(2) وغیرہ نے کئی طرق سے، بحوالہ حسن بن علی نقل کیا ہے۔ ہمیں یہ روایت عالی سند سے، ابو علی بن شاذان کے مشیخہ میں بطریق اہل بیت ملی ہے، اسے بغوی نے اسی طرح نقل کیا ہے۔ ابن مندہ نے اسے بطریق یعقوب بن تیمی، بحوالہ ابن عباس رضی اللہ عنہما نقل کیا ہے کہ انہوں نے ہند بن ابو ہالہ سے فرمایا: مجھ سے نبی کریم صلی اللہ علیہ وسلم کی صفت بیان کرو۔(3) بغوی نے، بحوالہ اپنے چچا، انہوں نے ابو عبید سے نقل کیا ہے: نبی کریم صلی اللہ علیہ وسلم سے پہلے سیدہ خدیجہ رضی اللہ عنہا کے شوہر ابو ہالہ کا نام نباش بن زرارہ تھا، ان کے بیٹے کا نام ہند بن نباش بن زرارہ بن وقدان بن حبیب بن سلامہ بن غدی بن جردہ بن اسید بن عمرو بن تمیم تھا، جو بنو عبد الدار کے حلیف تھے، بعض کا قول ہے: وہ زرارہ بن نباش ہیں۔\nزبیر کا قول ہے: ان کا نام مالک بن نباش بن زرارہ ہے، ابو محمد بن حزم کا قول ہے: ابو ہالہ کا نام ہند بن زرارہ بن نباش ہے۔ مجھے ان سے پہلے شخصیت مل گئی ہے جس نے ان کا ذکر کیا ہے۔\nابن ابی خیثمہ کا قول ہے، ہم سے احمد بن مقدام نے، بحوالہ سعید نقل کیا ہے، قتادہ کا قول ہے: ابو ہالہ، ہند بن زرارہ بن نباش ہیں، میں نے مرز بانی کی مجمع الشعراء میں دیکھا ہے کہ زرارہ بن نباش نے بدر میں کفار کا مرثیہ کہا، ان کا اسلام لانا مذکور نہیں۔\nابن سکن، ابن قانع نے بطریق سیف بن عمر، بحوالہ ہند بن ہند بن ابو ہالہ، عن ابیہ نقل کیا ہے، فرماتے ہیں: میں نے کہا: یا رسول اللہ! آپ نے کس وجہ سے اپنی بیٹی عتیبہ سے چھڑا لی، یہاں تک کہ آپ نے انہیں اپنا مخالف بنا لیا، آپ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ تعالیٰ نے مجھے جتنی خاتون سے نکاح کرنے اور جتنی شخص کو رشتہ دینے کا حکم دیا ہے“۔ \nزبیر بن بکار کا قول ہے: ہند، جمل کے دن سیدنا علی رضی اللہ عنہ کے ساتھ شہید ہوئے۔ دار قطنی نے کتاب الاخوۃ میں فرمایا: ابو عمر کا قول ہے:  فصیح و بلیغ تھے، انہوں نے نبی کریم صلی اللہ علیہ وسلم کے اوصاف بڑے اچھے اور مبسوط طریقے سے بیان کیے۔","",{"fn":"(1) اسد الغابة (۵۴۰۴) الاستيعاب (۲۷۲۸)\n(2) شمائل ترمذی (حدیث: ۳۳) مستدرک حاکم (۶۴۰/۳) السنن الکبریٰ (۱۶۱/۱) (۲۳۸/۱) المعجم الکبیر (۱۰۰/۲۲)\n(3) کنز العمال (۳۱۹۳۹) جامع الجوامع (۴۶۱۴)"}],[7633,"§۹۰۱۱ ۔ ہند بن ہند\n(1) ابن ابو ہالہ، پہلے والے کے بیٹے ہیں، قتادہ اور ان کے تابعین کے قول کے مطابق ہند ابو ہند بن ہند تینوں ترتیب وار ہیں۔\nابن مندہ نے ان کا ذکر کیا ہے اور بطریق حسان بن عبد اللہ واسطی، بحوالہ مالک بن دینار نقل کیا ہے کہ مجھ سے ہند جو سیدہ خدیجہ زوجہ النبی صلی اللہ علیہ وسلم کے بیٹے ہیں، فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم ہم ابو مردان کے پاس سے گزرے وہ اپنی انگلی سے رسول اللہ صلی اللہ علیہ وسلم کی طرف اشارہ کرنے لگا، یہاں تک کہ آپ صلی اللہ علیہ وسلم اس کی طرف متوجہ ہوئے تو فرمایا: ”اے اللہ! اس پر کبھی طاری کر“۔ فرماتے ہیں: وہ اپنی جگہ پر پکڑا گیا، اسی طرح ابن ابی حاتم(2) رازی اور عبد اللہ بن احمد نے زیادت الزہد میں اس طریق سے اور مالک بن دینار نے نقل کیا ہے، انہوں نے ہند بن ابی ہالہ کا زمانہ نہیں پایا، البتہ ان کے بیٹے کا زمانہ پایا ہے، گویا انہوں نے ان کے دادا کی طرف ان کی نسبت کی ہے۔\nابن ابی حاتم نے بحوالہ ان کے والد ذکر کیا ہے کہ ہند بن ہند نے نبی کریم صلی اللہ علیہ وسلم سے مرسل روایت کی ہے۔ ابو عمر(3) نے اس کے ظاہر کو دیکھتے ہوئے اس حدیث کو ہند بن ابو ہالہ سے ذکر کیا ہے۔\nزبیر بن بکار اور دو لابی نے بطریق محمد بن حجاج، بنو تمیم کے ایک شخص کے حوالے سے نقل کیا ہے، فرماتے ہیں: میں نے ہند ابن ہند بن ابو ہالہ کو دیکھا، ان پر سبز جوڑا تھا، وہ طاعون میں فوت ہوئے۔ چار آدمی ان کا جنازہ لے کر نکلے، کیونکہ لوگ اپنے مردوں کی وجہ سے مشغول تھے۔ ایک خاتون چیخ کر کہنے لگی: ہائے ہند بن ہند اور رسول اللہ صلی اللہ علیہ وسلم کے پروردہ کے بیٹے! فرماتے ہیں: لوگوں نے اپنے مردوں کو چھوڑ دیا اور ان کے جنازے میں شامل ہو گئے، جس سے بہت ازدحام ہو گیا۔","",{"fn":"(1) اسد الغابة (۵۴۰۵) الاستيعاب (۲۷۲۸) تجريد (۱۲۳/۲)\n(2) الجرح\n(3) الاستيعاب (۱۰۵/۴)"}],[7634,"§۹۰۱۲ ۔ ہنیدہ بن خالد خراعی\n(1) ابن حبان اور ابو عمر(2) کا قول ہے: انہیں شرف صحابیت حاصل ہے۔ ابن مندہ کا قول ہے: کوفہ کے صحابہ رضی اللہ عنہم میں ان کا شمار ہے، فرماتے ہیں: ابو اسحاق کا قول ہے: ان کی والدہ سیدنا عمر بن خطاب رضی اللہ عنہ کی زوجہ تھیں، ابو نعیم کا قول ہے: ان کے صحابی ہونے میں اختلاف ہے، انہوں نے بطریق شعبہ، بحوالہ ابو اسحاق نقل کیا ہے کہ میں نے ہنیدہ سے فرماتے ہوئے سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اس تلوار کو اس کے حق کے ساتھ کون لے گا؟“ ایک شخص نے اسے لے لیا اور کہا:(3) عطا\n”میں وہ ہوں کہ میرے دوست نے مجھ سے عہد لیا ہے“۔\nفرماتے ہیں: وہ اس سے لڑے حتیٰ کہ شہید ہو گئے۔\nبیہقی نے اسے سنن کبریٰ میں اس طریق سے اس قول کے علاوہ نقل کیا ہے جس کے آخر میں وہ لڑے حتیٰ کہ شہید ہو گئے۔\nاسے ابن مندہ نے بطریق یونس بن ابی اسحاق، عن ابیہ، عن ہنیدہ بن خالد خراعی اسی مفہوم میں نقل کیا ہے، اس کے آخر میں ہے: وہ ابھی چند قدم ہی چلے تھے کہ دشمن نے ان پر یلغار کر دی اور انہیں شہید کر دیا۔\nان کا قصہ مشہور صحابی ابو دجانہ سے ملتا ہے، لیکن ابو دجانہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں شہید نہیں ہوئے، ابن حبان نے ثقات تابعین میں لکھا ہے: ہنیدہ بن خالد خراعی، انہوں نے سیدنا علی، سیدہ حفصہ بنت عمر سے روایت کی، ان کی والدہ سیدنا عمر رضی اللہ عنہ کی زوجہ تھیں، ان سے عدی بن ثابت وغیرہ نے روایت کیا، اس میں اور تہذیب میں ان کے کلام کے بارے میں اختلاف ہے۔","",{"fn":"(1) اسد الغابة (۵۴۰۶) الاستيعاب (۲۷۴۱) تجريد (۱۲۳/۲)\n(2) الاستيعاب (۱۱/۴)\n(3) اسد الغابة (۵۴۰۸)"}],[7635,"§۹۰۱۳ ۔ ہود\n(1) بعض کا قول ہے: ھودہ بن احمر حارثی، ابو موسیٰ نے ذیل میں ان کا ذکر کیا ہے، فرماتے ہیں: ھود بن احمر، بنی سدوسی میں(2) نبی کریم صلی اللہ علیہ وسلم کے پاس وفد میں آئے، ابو زکریا بن مندہ نے ان کے دادا پر اپنے استدراک میں ان کا ذکر کیا ہے۔\nمیں کہتا ہوں: شیرازی نے القاب میں ان کا ذکر کیا ہے، اور بطریق نمیر بن حاجب بن ثوب بن شہاب بن زہیر ذہلی، بحوالہ شہاب بن زہیر نقل کیا ہے۔ فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم کی طرف بکر بن وائل میں سے پانچ افراد نے، بنو سدوس میں سے چار اور عجل میں ایک شخص نے ہجرت کی، انہوں نے سدوسیوں کا ذکر کیا، یہاں تک کہ فرمایا: ھودہ بن احمر حارثی، فرماتے ہیں: فرات، ابن حیان عجلی ہیں۔","",{"fn":"(1) اسد الغابة (۲۹۶/۴)\n(2) اسد الغابة (۲۹۷/۴)"}],[7636,"§۹۰۱۴ ۔ ھودہ بن حارث\n(1) ابن عمرہ بن عبد اللہ بن یظفر بن عصیر بن خفاف بن امری القیس بن محمد بن سلیم سلمی، طبری اور ابن شاہین نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ فرماتے ہیں: ھودہ بن حارث اسلام لائے اور فتح مکہ کے موقع پر حاضر تھے، انہوں نے سیدنا عمر رضی اللہ عنہ سے، ان کے ساتھ جنگ کرنے کے بارے میں کہا: عطا\n”یہ معاملہ نا اہل کے سپرد کر دیا گیا ہے۔ اس کام کا ذمہ دار اب تم کہاں سے تلاش کرو گے؟“\nمرزبانی(2) کا قول ہے: ھودہ، ابن حمامہ کے نام سے معروف تھے، وہ سیدنا عمر رضی اللہ عنہ کی خلافت میں علاء لینے کے لیے آئے، انہوں نے ان سے پہلے ان کی قوم کے کچھ آدمیوں کو بلا لیا تھا، انہوں نے مذکورہ شعر کہا، لیکن اس کے آخر میں ہے: عطا\n”اے اللہ کے امین! کیسے باز رہتا ہے؟ کیا تم اور شریکو تم سے پہلے بلایا جاتا ہے، دریا بچ اور طرود کو تم سے پہلے بلایا جاتا ہے، اگر اس کتاب کے مطابق فیصلہ ہوا ہے تو ٹھیک ہے، کیونکہ وہ آزاد بادشاہوں کی اولاد ہیں اور ہم غلام ہیں“۔\nفرماتے ہیں: سیدنا عمر بن خطاب رضی اللہ عنہ نے انہیں بلایا اور عطا کیا، اسی طرح بلاذری کے قصہ میں مذکور ہے۔","",{"fn":"(1) اسد الغابة (۵۴۰۹)\n(2) معجم الشعراء (۴۶۰)"}],[7637,"§۹۰۱۵ ۔ ھودہ بن خالد\n(1) ابن ربیعہ عامری، ابن سعد نے وفد بنو عامر میں ان کا ذکر کیا ہے، فرماتے ہیں: وہ، ان کے والد خالد اور بھتیجے اسلام لائے۔","",{"fn":"(1) اسد الغابة (۵۴۱۰)"}],[7638,"§۹۰۱۶ ۔ ھودہ بن خالد کنانی\n(1) ابو موسیٰ نے ذیل میں ان کا ذکر کیا ہے، فرماتے ہیں: ابو زبیر نے، بحوالہ جابر، سیدنا معاویہ کے ساتھ فتوح میں ان کی حدیث روایت کی ہے۔","",{"fn":"(1) اسد الغابة (۵۴۱۰)"}],[7639,"§۹۰۱۷ ۔ ھودہ بن عرفطہ حمیری\n(1) نبی کریم صلی اللہ علیہ وسلم کے پاس وفد میں آئے، فتح مصر میں شریک تھے۔ مجھے ان کی کوئی روایت معلوم نہیں، یہ ابو سعید بن یونس کا(2) قول ہے۔","",{"fn":"(1) تجريد (۱۲۴/۲)\n(2) اسد الغابة (۵۴۱۱) تجريد (۱۲۴/۲)"}],[7640,"§۹۰۱۸ ۔ ھودہ بن عمرو\n(1) ابن یزید بن عمرو بن ریاح بن عوف بن عمرو بن عون جری، ابن کلبی کا قول ہے: نبی کریم صلی اللہ علیہ وسلم کے پاس وفد میں آئے،(2) اسی طرح طبری نے ذکر کیا ہے، ابن ماکولا(3) نے اسے ریاح کے سوانح میں نقل کیا ہے۔ فرماتے ہیں: یہ ابن حبیب نے ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۵۴/۲)\n(2) جمهرة انساب العرب (۴۵۱) اسد الغابة (۲۹۷/۴)\n(3) الاکمال (۱۶/۴)"}],[7641,"§۹۰۱۹ ۔ ھودہ انصاری\nطبرانی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، اور ان کی کوئی حدیث نقل نہیں کی۔\nمیں کہتا ہوں: شاید وہ معبد بن ھودہ کے والد ہیں، ان کے حالات میں کسی کا قول گزر چکا ہے۔ یہ حدیث معبد کے والد ھودہ کی ہے۔"],[7642,"§۹۰۲۰ ۔ ھودہ\n(1) بے نسبت۔ بغوی کا قول ہے: ابن سعد نے ان کا ذکر کیا ہے، فرماتے ہیں: انہوں نے نبی کریم صلی اللہ علیہ وسلم سے حدیث روایت کی، اور اسے ذکر نہیں کیا۔ طبرانی(2) نے ان کا عنوان قائم کیا ہے، لیکن حدیث ذکر نہیں کی۔\nمیں کہتا ہوں: احتمال ہے کہ یہ پہلے والے ہوں۔","",{"fn":"(1) المعجم الکبیر (۲۲/۲۰)\n(2) تجريد (۱۲۴/۲)"}],[7643,"§۹۰۲۱ ۔ ھیاج بن محارب عامری\n(1) ابن سکن اور ابن قانع نے ان کا ذکر کیا ہے، ابن قانع نے بطریق خلدہ بنت عیاض، بحوالہ ھیاج بن ھیاج بن محارب نقل کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”گھوڑوں کی پیشانی کے ساتھ قیامت تک خیر بندھی ہوئی ہے“۔(2) ابن سکن کا قول ہے: ان سے مجہول سند سے حدیث مروی ہے۔\nمیں کہتا ہوں: اس میں جعفر بن عبد الواحد ہاشمی ہیں، انہوں نے حدیث گھڑنے کی طرف ان کی نسبت کی ہے۔","",{"fn":"(1) بخاری (۲۸۵۰) مسلم (۹۸) ترمذی (۱۶۹۴) نسائی (۳۵۷۶) کنز (۲۵۷۵۴) (۳۲۵۴۳) سیوطی فی در المنثور (۱۹۳/۲)\n(2) نصب الرایہ (۹۱/۴، ۹۲)"}],[7644,"§۹۰۲۲ ۔ ھیبان\n(1) اسلمی، بعض کا قول ہے: ہیبان، ابن مندہ نے اسے بطریق یزید بن ابی منصور، بحوالہ عبد اللہ بن ہیبان، عن ابیہ نقل کیا ہے۔ فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”مسلمان کا وسعت کی حالت میں صدقہ کرنا مشک کی خوشبو کی طرح ہے، جو ایک دن کی مسافت سے سونگھی جا سکتی ہے اور فقر و فاقہ کی حالت میں صدقہ کرنا مشک کی ایسی خوشبو کی طرح ہے جو خشکی یا تری میں ایک سال کی مسافت سے سونگھی جا سکتی ہے“۔(2)","",{"fn":"(1) اسد الغابة (۵۴۱۵) تجريد (۱۲۴/۲)\n(2) کنز العمال (۱۶۲۷۸) جامع المسانید والسنن (۳۱۱/۱۲)"}],[7645,"§۹۰۲۳ ۔ ھیت المغنث\n(1) صحیح بخاری میں بطریق سفیان بن عتبہ، بحوالہ ام سلمہ ان کا ذکر ہے، فرماتی ہیں: میرے پاس رسول اللہ صلی اللہ علیہ وسلم تشریف لائے اور میرے پاس مخنث تھا، آپ صلی اللہ علیہ وسلم نے اسے عبد اللہ بن ابی امیہ کو کہتے ہوئے سنا: اگر اللہ تعالیٰ تمہیں طائف پر فتح دے تو غیلان کی بیٹی کو نہ جانے دینا، وہ چار کے ساتھ آتی ہے اور آٹھ کے ساتھ جاتی ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اسے نہ آنے دو“۔(2) سفیان کا قول ہے، ابن جریج نے کہا: مخنث کا نام ہیت تھا، یہ حدیث مسلم، ابو داود، نسائی کے ہاں اس کے نام کے بغیر ہے۔\nعبد الملک بن حبیب نے واضحہ میں، بحوالہ حبیب، کاتب مالک نقل کیا ہے، فرماتے ہیں: میں نے مالک سے کہا: سفیان نے بنت غیلان کی حدیث میں یہ اضافہ کیا ہے کہ مخنث کو ہیت کہا جاتا تھا، مالک کا قول ہے: ٹھیک کہا، ایسا ہی ہے۔ نبی کریم صلی اللہ علیہ وسلم نے اسے حجاز کی طرف جلا وطن کر دیا۔\nابو عمر نے تمہید میں کہا: یہ سفیان کے حوالے سے غیر معروف ہے، سفیان نے، بحوالہ ابن جریج ان کا ذکر کیا ہے۔ جوزجانی نے اپنی تاریخ میں بطریق اوزاعی، بحوالہ علی بن حسن نقل کیا ہے، ایک مخنث نبی کریم صلی اللہ علیہ وسلم کی ازواج کے پاس آتا تھا، اس کا نام ہیت تھا۔\nاسی طرح ابو یعلیٰ نے بطریق یونس، بحوالہ عائشہ رضی اللہ عنہا ذکر کیا، پھر اصل قصہ ذکر کیا، اس میں ہے: ہیت گھر میں جاتا تھا، صحیح میں یہ بطریق معمر، بحوالہ زہری نام کے بغیر مروی ہے۔\nمستغفری نے بطریق داود بن بکر، بحوالہ ابن منکدر نقل کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم نے دو باتیں جو اس نے کی تھیں وہ عورتوں کی باتوں کے مشابہ تھیں، جلا وطن کر دیا۔ اس نے عبد الرحمن بن ابی بکر سے کہا: جب تم کل طائف فتح کرو تو غیلان کی بیٹی کو نہ جانے دینا، وہ چار کے ساتھ آتی ہے اور آٹھ کے ساتھ جاتی ہے، نبی کریم صلی اللہ علیہ وسلم کو یہ بات معلوم ہوئی تو فرمایا: ”ان لوگوں کو اپنے گھروں میں نہ آنے دو۔۔۔“۔ (الحدیث)۔\nابن ابی شیبہ اور احمد بن ابراہیم دورقی نے اپنی سند میں بطریق محمد بن عبد الرحمن بن ابی لیلیٰ، بحوالہ عامر بن سعد بن مالک، عن ابیہ نقل کیا ہے کہ انہوں نے مکہ میں ایک خاتون کو نکاح کا پیغام دیا اور کہا: مجھے اس کے بارے میں کون بتائے گا؟ ہیت نامی ایک مخنث نے کہا: میں تمہیں اس کے بارے میں بتاتا ہوں، جب وہ چلتی ہوئی آتی ہے اور جب واپس جاتی ہے تو چار پر جاتی ہے۔ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”مجھے تو یہ بات بری لگی ہے، میرا خیال ہے کہ وہ عورتوں کو جانتا ہے“۔ وہ سیدہ سودہ رضی اللہ عنہا کے پاس آتا تھا، آپ صلی اللہ علیہ وسلم نے انہیں منع فرمایا کہ اسے گھر آنے دیں۔ جب مدینہ آئے تو اسے جلا وطن کر دیا۔ سیدنا عمر رضی اللہ عنہ کی خلافت تک ایسا ہی رہا۔ پھر اس نے کوشش کی تو اسے اتنی رخصت ملی کہ مدینہ آئے، جمعہ کے دن لوگ اسے صدقہ دیتے۔\nابن وہب نے اپنے جامع میں اس شخص کے حوالے سے نقل کیا ہے جس نے ابو معشر سے سنا، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے اس کے بارے میں حکم دیا، اسے مدینہ میں ذی الحلیفہ کے پاس جبل عمر کی طرف جلا وطن کر دیا گیا، بعض صحابہ رضی اللہ عنہم نے اس کے لیے سفارش کی کہ وہ بھوک سے مر جائے گا۔ آپ صلی اللہ علیہ وسلم نے اسے اجازت دی کہ ہر جمعہ کو کھانا لے لے پھر اپنی جگہ پر چلا جائے، وفات تک وہیں رہا۔\nمانع کے سوانح میں اس کے کچھ حالات گزر چکے ہیں۔\nابو عبید بکری نے شرح امالی القالی میں فرمایا: مدینہ میں تین مخنث تھے جو عورتوں کے پاس آیا کرتے تھے، ان سے پردہ نہیں کیا جاتا تھا۔ ہیت، بدم اور ماتع۔","",{"fn":"(1) اسد الغابة (۵۴۱۶) تجريد (۱۲۴/۲)\n(2) بخاری (۵۲۳۵) مسلم (۲۲) ابو داود (۴۹۲۸) ابن ماجہ (۲۶/۴)"}],[7646,"§۹۰۲۴ ۔ ھیشم اسدی\nبعض کا قول ہے: ابو معقل، اپنی کنیت سے مشہور ہیں، محمد بن عبد اللہ بن زکریا انصاری نے ان کا نام لیا ہے۔ ابو نعیم کا قول ہے: بعض نے کہا: ان کا نام ہثم ہے، کتبوں میں ان کا ذکر آئے گا۔"],[7647,"§۹۰۲۵ ۔ ھیشم بن دھر\n(1) ابن سعد نے، بحوالہ واقدی اپنی سند سے نقل کیا ہے، انہوں نے منذر بن جہم سے، انہوں نے ہثم بن دہر سے نقل کیا ہے، فرماتے ہیں: میں نے نبی علیہ السلام کی پیشانی اور زریب سفید بال دیکھے جنہیں میں نے شمار کیا تو تیس بال تھے، طبری کے نزدیک ایک ترجمہ بعد والا ہے صاحب ہیں، ان کا اپنے دادا کے نسب سے ذکر ہوا۔","",{"fn":"(1) اسد الغابة (۵۴۱۷)"}],[7648,"§۹۰۲۶ ۔ ھیشم بن ضرار\nابن ابی خیثمہ کا قول ہے، بعض نے کہا: وہ شام کا نام ہے، ان کے بارے میں مشہور ہے کہ ان کا نام معقل ہے۔ یہ ابو الفرج اصبہانی کا قول ہے۔"],[7649,"§۹۰۲۷ ۔ ھیشم بن نصر\nابن وہرہ سلمی، واقدی نے نبی کریم صلی اللہ علیہ وسلم کے خدام میں ان کا ذکر کیا ہے، ان کے حوالے سے ان کی سند سے نقل کیا ہے، فرماتے ہیں: میں نبی کریم صلی اللہ علیہ وسلم کی خدمت کرتا تھا، حاجت مند لوگوں کے ساتھ میں آپ صلی اللہ علیہ وسلم کے دروازے پر بیٹھا گیا، میں آپ صلی اللہ علیہ وسلم کے پاس، میرا ابی ہثم بن تہبان سے پانی لاتا تھا، اس کا پانی میٹھا تھا، گرمیوں میں ایک دن آپ صلی اللہ علیہ وسلم ابو ہثم کے پاس آئے، آپ صلی اللہ علیہ وسلم کے ساتھ سیدنا ابو بکر رضی اللہ عنہ تھے۔۔۔ پھر قصہ ذکر کیا۔"],[7650,"§۹۰۲۸ ۔ ھیشم\n(1) قیس کے والد ہیں، محمد بن سلام تجمی اور ابن قانع نے مختصر ذکر کیا ہے، بطریق عبد القاہر بن سری بن قیس بن ہثم فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم نے میرے دادا ہثم کو اپنی قوم کے صدقات وصول کرنے پر مقرر کیا۔ انہوں نے پوری زکوٰۃ سیدنا ابو بکر رضی اللہ عنہ کے سپرد کر دی۔ زبرقان نے بھی پوری زکوٰۃ دی، سیدنا ابو بکر صدیق رضی اللہ عنہ نے فرمایا: زبرقان نے اکرام کرنے کے لیے اسے پورا کیا اور ہثم نے گناہ سے بچنے کے لیے پوری دی یا ثواب حاصل کرنے کے لیے دی۔ عبد القاہر کا قول ہے: میں نے ان سے کہا: آپ سے کس نے بیان کیا؟ انہوں نے ایک لمحہ سوچا پھر فرمایا: حمید نے، بحوالہ حسن نقل کیا ہے۔ ابن اثیر(2) کا قول ہے: یہ ابن قیس بن ملت ابن حبیب سلمی ہیں، جو امیر خراسان عبد اللہ بن حازم کے چچا ہیں۔","",{"fn":"(1) اسد الغابة (۵۴۱۸) تجريد (۱۲۴/۲)\n(2) اسد الغابة (۵۲۶/۵)"}],[7651,"§۹۰۲۹ ۔ ھیدان بن سیج عبسی\nجاحظ نے بیان میں ان کا ذکر کیا ہے، انہوں نے ذکر کیا کہ نبی کریم صلی اللہ علیہ وسلم نے نابغہ سے فرمایا: ”تمہارے دانت سلامت رہیں“۔ اور ہیدان بن سیج سے فرمایا: ”تمھیں سے بہت سے خطیب ہوں گے“۔ حسان بن ثابت سے فرمایا۔۔۔ پھر کچھ کا ذکر کیا۔ میرے لیے ان کے والد کا نام واضح نہیں ہوا۔"],[7652,"§۹۰۳۰ ۔ ھیکل بن جابر\n(1) ابو موسیٰ نے ذیل میں ان کا ذکر کیا ہے اور بطریق حماد بن عمر نصیبی، بحوالہ ھیکل بن جابر نقل کیا ہے، فرماتے ہیں: اسی اثناء میں کہ نبی کریم صلی اللہ علیہ وسلم بیت اللہ کا طواف کر رہے تھے کہ ایک آدمی کعبے کے پردوں سے چمٹا ہوا تھا اور کہہ رہا تھا، اس گھر کی حرمت کی قسم! تو مجھے معاف کر دے۔ نبی کریم صلی اللہ علیہ وسلم نے اسے ڈانٹا پھر طویل قصہ ذکر کیا اس میں ہے: ”بخل کرنا کفر ہے اور کفر آگ میں لے جائے گا، اگر تم روزہ رکھو اور مقام ابراہیم اور رکن کے پیچھے ایک ہزار یا دو ہزار سال تک نماز پڑھو، پھر تم روتے رہو یہاں تک کہ تمہارے آنسوؤں سے نہریں جاری ہو جائیں اور اس سے درخت اگیں پھر تم مر جاؤ اور تم کینہ ہو تو اللہ تعالیٰ تمہیں منہ کے بل آگ میں پھینکیں گے“۔(2) حماد بن عمرو حدیث گھڑنے میں مشہور ہے۔","",{"fn":"(1) اسد الغابة (۵۴۲۰) تجريد (۱۲۵/۲)\n(2) اتحاف السادة المتقین (۱۹۵/۸) جامع المسانید والسنن (۳۱۲/۱۲)"}],[7653,"§۹۰۳۱ ۔ ھرمی بن عبد اللہ\n(1) بعض کا قول ہے: ابن عقبہ ہیں، بعض نے کہا: ابن عمرو انصاری خطمی۔ بعض نے کہا: واثقی ہیں، ابو موسیٰ نے ذیل میں ان کا ذکر کیا ہے اور بطریق ابن اسحاق نقل کیا ہے کہ محمد سے ثمامہ بن قیس بن رفاعہ نے، بحوالہ ہرمی بن عبد اللہ سے نقل کیا ہے جو ان کی قوم کے ایک شخص تھے، وہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں پیدا ہوئے اور آپ علیہ السلام کے صحابہ رضی اللہ عنہم کو دیکھا، وہ کثیر تعداد میں تھے، فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے جمعہ پایا، پھر اس میں نہیں آیا تو بعد والے میں بوجھل ہو گا“۔ (الحدیث)۔(2) ابن ہرمی نے بحوالہ خزیمہ بن ثابت اور نسائی روایت ہے، اس کی سند میں اختلاف ہے۔ ان کے بارے میں کہا گیا: عبد اللہ بن ہرمی، وہ نام بدل گیا ہے، بخاری رحمہ اللہ نے اپنی تاریخ میں اس کی طرف اشارہ کیا ہے۔","",{"fn":"(1) اسد الغابة (۵۳۵۲) استیعاب (۲۷۲۷)\n(2) مصنف عبد الرزاق (۵۴۸۴) جامع المسانید والسنن (۲۲۷/۱۲)"}],[7654,"§۹۰۳۲ ۔ ھلال بن عامر نمیری\n(1) وہ ابن تجم ہیں، ان کے والد صحابی ہیں، انہیں دیدار حاصل ہے۔ یہ ابن مندہ کا قول ہے، ان کے سوانح میں بطریق وہیب، بحوالہ قبیصہ بن سعوف شمس کے بارے میں نقل کیا ہے، یہ ابن مندہ کا قول ہے، دوسرے راویوں نے بحوالہ ھلال بن عامر فرمایا: یعنی ابو قلابہ نے اسے، بحوالہ ھلال بن عامر، انہوں نے قبیصہ سے روایت کیا ہے۔ نہ کہ ھلال بن عامر سے، جو اس حدیث کے صحابی ہیں اسے ابو داود(2) نے، بہ روایت عباد بن منصور، بحوالہ ھلال نقل کیا ہے کہ قبیصہ نے ان سے بیان کیا، طبرانی نے بطریق انیس بن سوار، بحوالہ ایوب اسی مفہوم میں نقل کیا ہے۔","",{"fn":"(1) اسد الغابة (۵۳۸۹) تجريد (۱۲۲/۲)\n(2) ابو داود (۱۱۸۵، ۱۱۸۶)"}],[7655,"§۹۰۳۳ ۔ ھاشم بن حرملہ مُرّی\nجاہلیت کے شہسواروں میں سے ہیں، انہوں نے اسلام کا زمانہ پایا، سیدنا عمر رضی اللہ عنہ کی خلافت تک زندہ رہے، میں نے تاریخ مظفری میں پڑھا ہے کہ سیدنا عمر رضی اللہ عنہ نے بنو مرہ کے ایک شخص سے فرمایا: اگر تم چاہو تو اپنے نسب یعنی قریش کی طرف لوٹو، ان میں میں حارث بن عوف، حصین بن حمام، ھجرم اور خارجہ بن سنان کے بیٹے، ہاشم بن حرملہ بھی تھے، ہاشم وہی شخص ہیں جنہوں نے عامر جعفنی کی ان الفاظ میں تعریف کی: ”اس کے باپ کو ہاشم بن حرملہ نے گرد و غبار اور مشقت کے دن بچایا“۔ انہیں یہ شعر پسند نہ آئے تو انہوں نے مزید کہا: ”تو اس کے ارد گرد بادشاہوں کو گھٹیا دیکھے گا وہ قصور وار اور بے قصور کو قتل کرتے ہیں“۔ یہ شعر انہیں پسند آیا تو انہیں انعام دیا۔"],[7656,"§۹۰۳۴ ۔ ھانی بن عروہ\nابن فضفاض، بن عمران بن عمرو بن قتاس بن عبد یغوث مرادی پھر غطیفی، مختار کی ہیں۔ کوفہ میں رہائش تھی۔ سیدنا علی رضی اللہ عنہ کے خاص لوگوں میں سے تھے، جب اہل کوفہ نے مسلم بن عقیل بن ابو طالب کی سیدنا حسین بن علی رضی اللہ عنہ کے لیے بیعت کی تو وہ مذکورہ ہانی کے پاس ٹھہرے، جب عبد اللہ بن زیاد آیا تو اس نے مسلم بن عقیل اور ہانی بن عروہ کو قتل کر دیا۔\nابن سعد نے شعبی وغیرہ تک اپنی اسانید سے نقل کیا ہے کہ مسلم کوفہ میں خفیہ طور پر آئے، نعمان بن بشیر کوفہ کے امیر تھے، جب یزید بن معاویہ کو سیدنا حسین بن علی کی کوفہ کے ارادے سے آنے کی اطلاع ملی تو اسے خوف ہوا کہ نعمان ان کا مقابلہ نہیں کر سکیں گے، اس نے عبید اللہ بن زیاد کو لکھا اس وقت وہ بصرہ کا امیر تھا کہ اسے کوفہ کی امارت بھی دے دی جائے گی، وہ کوفہ آیا۔ اس کے ساتھ شریک بن اعور حارثی بھی آیا۔ شریک ہانی بن عروہ کے پاس ٹھہر اور اپنے آپ کو بیمار ظاہر کیا، عبید اللہ بن زیاد نے اس کی عیادت کو آیا، انہوں نے اسے دھوکے سے قتل کرنا چاہا۔ اس نے بھانپ لیا اور جلدی سے واپس لوٹا۔ ہانی بن عروہ کو اپنے پاس بلایا، اسے محل میں داخل کیا، اس وقت ان کی عمر نوے(۹۰) برس سے زیادہ تھی۔ انہیں ڈانٹا، پھر نیزہ مارا اور ان کا سر علیحدہ کر لیا۔ اسے محل کے اوپر سے گرا دیا۔ سیدنا حسین رضی اللہ عنہ کی شہادت کے واقعات میں یہ مشہور واقعہ ہے۔ اس قول کہ انہوں نے ۹۰ سے زیادہ عمر پائی یہ غرض ہے کہ انہوں نے آپ صلی اللہ علیہ وسلم کی حیات مبارکہ سے چالیس(۴۰) سے زیادہ سال پائے۔ اس لیے وہ اس قسم والے لوگوں میں سے ہیں۔\nان کے والد عروہ کا ذکر اسی طرح ھثم حالت میں گزر چکا ہے۔"],[7657,"§۹۰۳۵ ۔ ھانی بن معاویہ صدفی\nانہوں نے نبوت کا زمانہ پایا اور فتح مصر میں شریک ہوئے۔ سیدنا عثمان رضی اللہ عنہ کے ساتھ حج کیا، انہوں نے عثمان بن حنیف کے حوالے سے روایت کیا، ابن یونس نے ان کا ذکر کیا ہے۔"],[7658,"§۹۰۳۶ ۔ ھبیرہ بن اسعد\nابن کلان سابی۔ انہوں نے نبوت کا زمانہ پایا، فتح مصر میں شریک ہوئے، ابن یونس نے ان کا ذکر کیا ہے، فرماتے ہیں: برتہ میں ان کی اولاد باقی ہے۔"],[7659,"§۹۰۳۷ ۔ ھبیرہ بن احنس\nابن کور بن مولہ بن ھمام بن ضب بن کعب بن مالک بن ثعلبہ بن دودان بن اسد بن خزیمہ اسدی، مرزبان نے نجم اشعراء میں ان کا ذکر کیا ہے، فرماتے ہیں: وہ مخضرم ہیں، کہتے ہیں: ”اے آل مالک! میں نے گھر اکر انہیں پکارا، جس نے قوم کے کیڑوں کو سوار بنا دیا“۔"],[7660,"§۹۰۳۸ ۔ ھبیرہ بن خالد\nابن مسلم بن حارث بن خضف بن حاج، وہ مالک بن حارث بن بکر بن ثعلبہ بن عقبہ بن سکون سکونی ہیں۔ انہوں نے نبوت کا زمانہ پایا، ان کے بیٹے مالک سیدنا معاویہ رضی اللہ عنہ کے ہاں شریف اور امیر تھے۔ ان کا ان کے ساتھ حجر بن عدی کے قتل میں قصہ تھا، ابن کلبی رحمہ اللہ نے ان کا ذکر کیا ہے، محمد بن ابی حذیفہ کے سوانح میں ان کا ذکر گزر چکا ہے۔"],[7661,"§۹۰۳۹ ۔ ھبیرہ بن مفاضہ عامری\n(1) وثیمہ نے کتاب الردہ میں ذکر کیا ہے، انہوں نے، بونعیم کا پیغام بھیجا جس میں انہوں نے انہیں اسلام پر ثابت قدم رہنے کا حکم دیا جبکہ عرب کے بعض قبائل مرتد ہو گئے تھے۔ مرزبان نے نجم اشعراء میں ذکر کیا ہے: ھبیرہ بن عامر بن ریبعہ بن عبادہ بن عقیل ابن کعب بن ریبعہ بن عامر بن صعصعہ، یہ وہی ہیں جنہیں ھبیرہ بن مفاضہ کہا جاتا ہے، مفاضہ ان کی والدہ ہیں اور بنو اسد سے ہیں۔ ان کے بارے میں ان کے کچھ اشعار نقل کیے ہیں۔","",{"fn":"(1) اسد الغابة (۵۳۳۹)"}],[7662,"§۹۰۴۰ ۔ ھبیرہ بن نعمان\nابن قیس بن مالک بن معاویہ بن سعد بن بداء، ابن سعد بن عمرو بن ذئل بن مزن بن جعفی بن سعد عشیرہ اکھٹی، انہوں نے نبوت کا زمانہ پایا، سیدنا علی رضی اللہ عنہ کے امراء میں سے تھے، ان کے ساتھ صفین میں شریک تھے، انہوں نے انہیں مدائن کا گورنر بنایا تھا، شریف تھے، یہ ابن کلبی کا قول ہے۔"],[7663,"§۹۰۴۱ ۔ ھجاس ایادی\nابو فرج اصبہانی، انہوں نے جاہلیت کا زمانہ پایا، ان کے حوالے سے دو ادیادی نے شعر نقل کیے ہیں۔"],[7664,"§۹۰۴۲ ۔ ھجالہ بن افلح\nابن قیس بن عمرہ خافقی، انہوں نے جاہلیت کا زمانہ پایا، فتح مصر میں وہ اور ان کے دونوں بیٹے عبد اللہ اور عبد الرحمن شریک ہوئے، ان کی وفات بہت پہلے فتح مصر کے تھوڑے عرصے بعد ہی وفات پاگئے، ابن یونس نے ان کا ذکر کیا ہے۔"],[7665,"§۹۰۴۳ ۔ ھدیل بن ھبیرہ ثعلبی\nمرزبان نے نجم اشعراء میں ان کا ذکر کیا ہے، فرماتے ہیں: مخضرم ہیں۔"],[7666,"§۹۰۴۴ ۔ ھذیل کاہلی\nسیف نے فتوح میں اور طبری(1) نے تاریخ میں نقل کیا ہے، سیدنا خالد بن ولید رضی اللہ عنہ نے حیرہ کی فتح کی خبر دے کر سیدنا ابو بکر صدیق رضی اللہ عنہ کے پاس بھیجا۔","",{"fn":"(1) تاریخ طبری (۳۶۲/۲)"}],[7667,"§۹۰۴۵ ۔ ھذیم ثعلبی\nادیم میں ان کا ذکر گزر چکا ہے۔"],[7668,"§۹۰۴۶ ۔ ھرم بن حبان عبدی\nمشہور ہے کہ کبار تابعین میں سے ہیں، پہلی قسم میں ان کا ذکر گزر چکا ہے۔"],[7669,"§۹۰۴۷ ۔ ھرم بن سنان مُرّی\nہاشم بن حرملہ کے سوانح میں ان کا ذکر ہے، یہ وہی ھرم ہیں جنہوں نے بنو عبس اور بنو فزارہ میں میں صلح کروائی، داحس اور ثمراء کی وجہ سے ان کے درمیان جو جنگیں ہوئیں وہ لڑتے لڑتے لوگ ختم ہونے کے قریب پہنچ گئے تھے۔ یہ وہی ہیں جنہوں نے مشہور شاعر زہیر بن ابی اسلمی جو والد کعب بن زہیر ہیں نے اپنے شعر میں مراد لیا ہے جو ان کے اور ان کے دوست کے بارے میں ہے: ”تم دونوں نے عبس اور ذبیان کا اس وقت تدارک کیا جب ان کے درمیان عداوت کی بوجھل چکی تھی اور وہ فنا ہونے کے قریب پہنچ چکے تھے“۔\nابن کلبی کا قول ہے۔ مجھ سے میرے والد نے بیان کیا، فرماتے ہیں: ھرم سیدنا عمر رضی اللہ عنہ کے زمانے تک زندہ رہے، انہوں نے ان سے کہا: عامر بن طفیل اور علقمہ بن غلاثہ میں سے کون شخص زیادہ فضیلت والا ہے؟ انہوں نے کہا: اگر میں یہ بات کہہ دوں تو جذعہ لوٹ آئے، آپ نے فرمایا: ھرم تو بہترین راز دار ہو۔"],[7670,"§۹۰۴۸ ۔ ھرم بن قطبہ\nابن شان فراری، انہوں نے جاہلیت کا زمانہ پایا، نبی کریم صلی اللہ علیہ وسلم کے زمانے میں اسلام لائے۔ ارتداد کے زمانے میں ثابت قدم رہے، وثیمہ نے ذکر کیا ہے کہ انہوں نے عیینہ بن حصن کو اسلام پر ثابت قدم رہنے کی طرف بلایا، اس سے کہا: بہاء وہ دین سرکشی کے انجام کو، قیس کے دن گھوڑوں کی سخت دشمنی کو احزاب کے دن اپنی شکست کو یاد کرو، طویل نصیحت کی، اس نے نہ مانا تو وہ اس سے جدا ہو گیا اور اس کے بارے میں شعر کہے، ھرم بن قطبہ جاہلیت میں عربوں میں فیصلہ کرتے تھے، عامر بن طفیل اور علقمہ بن غلاثہ نے انہیں فیصل بنایا، انہوں نے ان دونوں سے بات مخفی رکھی، ابو عبیدہ نے یہ کتاب الدیباج میں ذکر کیا ہے، فرماتے ہیں: ھرم بن قطبہ اسلام لائے، سیدنا عمر رضی اللہ عنہ نے اپنی خلافت میں فرمایا: اگر تمہیں فیصلہ بنایا جاتا تو تم کس کے بارے میں فیصلہ کرتے، انہوں نے کہا: آپ مجھے معاف رکھیے! اللہ کی قسم! اگر میں یہ بات ظاہر کر دیتا تو فیصلہ جذعہ کو لوٹا دیتا۔ آپ رضی اللہ عنہ نے فرمایا: تم نے سچ کہا، اسی عقل کے ذریعے تم نے فیصلہ کیا تھا۔ یہ قصہ ابو حسین رازی نے جو تمام کے والد ہیں، اپنے فوائد میں بطریق شافعی نقل کیا ہے۔ فرماتے ہیں: مجھ سے کئی لوگوں نے روایت کیا، پھر ان کا ذکر کیا۔\nجاحظ نے کتاب البیان میں سیدنا عمر رضی اللہ عنہ نے جب پہلے پہل انہیں دیکھا تو ان کا حال جاننا چاہا، ان سے ان کی معلومات سے مشورہ لیا، کیونکہ وہ پست قد اور گھر کے کونے میں سونے کپڑے میں لیٹے پڑے رہتے تھے، جب انہوں نے اس بات سے آپ کو جواب دیا تو وہ آپ رضی اللہ عنہ کو اچھے لگے، ان کے فخر کے مقابلے کا واقعہ ابن درید نے اپنی امالی میں بطریق ابن کلبی، عن ابیہ، عن ابی سکیں، عن اشیخ نقل کیا ہے۔"],[7671,"§۹۰۴۹ ۔ ھرمزان فارسی\n(1) فارس کے بادشاہوں میں سے تھے، فتوح عراق میں قیدی بنائے گئے اور سیدنا عمر رضی اللہ عنہ کے ہاتھ پر اسلام لائے، پھر ان کے پاس مدینہ میں قیام کیا، انہوں نے ان سے اہل فارس سے قتال کے بارے میں مشورہ لیا۔\nقاضی اسماعیل بن اسحاق فرماتے ہیں: ہم سے یحییٰ بن عبد الحمید نے، بحوالہ عبد اللہ بن شداد نقل کیا ہے، فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم نے ھرمزان کی طرف خط لکھا: ”محمد رسول اللہ (صلی اللہ علیہ وسلم) کی طرف سے، میں تمہیں اسلام کی دعوت دیتا ہوں، اسلام لاؤ، سلامتی حاصل ہو گی۔۔۔“۔ (الحدیث)۔\nشافعی رحمہ اللہ کا قول ہے: ہم سے ثقفتی اور ابن ابی شیبہ نے، بحوالہ مروان بن معاویہ، دونوں نے حمید سے، بحوالہ انس نقل کیا: ہم نے شتر کا محاصرہ کیا، ھرمزان سیدنا عمر رضی اللہ عنہ کے حکم پر قلعے سے نیچے اترا، اسے آپ رضی اللہ عنہ کے پاس لایا گیا، اس پر آپ کی ہیبت چھا گئی، آپ نے اس سے کہا: کوئی حرج نہیں بات کرو، یہ سیدنا عمر رضی اللہ عنہ کی طرف سے امان تھا، اسی طرح مختصر مروی ہے۔\nاسے علی بن حجر نے فتوح اسماعیل بن جعفر میں طویل نقل کیا ہے۔ حمید سے، بحوالہ انس فرماتے ہیں: مجھے ابو موسیٰ نے ھرمزان کے ساتھ سیدنا عمر رضی اللہ عنہ کے پاس بھیجا، وہ سیدنا عمر رضی اللہ عنہ کے حکم پر قلعے سے اترا تھا، سیدنا عمر رضی اللہ عنہ اس سے بات چیت کرنے لگے۔ اس نے کسی بات کا جواب نہیں دیا، سیدنا عمر رضی اللہ عنہ نے اس سے کہا: بات کرو، اس نے کہا: کیا زندہ شخص جیسی بات کروں یا مردہ شخص جیسی؟ آپ نے فرمایا: بات کرو، تمہیں کوئی حرج نہیں۔ اس نے کہا: اے عرب کی جماعت! ہم اور تم اگر اللہ تعالیٰ ہمارے درمیان حائل نہ ہو جاتا تو ہم تمہیں غلام بنا لیتے، جب اللہ تعالیٰ تمہارے ساتھ ہے تو ہمارا تم پر کوئی زور نہیں۔۔۔۔ پھر ان کو امان دینے کے بارے میں انہوں نے وہ واقعہ ذکر کیا جو میرے ساتھ پیش آیا تھا، فرماتے ہیں: ھرمزان اسلام لائے، سیدنا عمر رضی اللہ عنہ نے ان کے لیے حصہ مقرر کیا۔\nیحییٰ بن آدم نے کتاب الخراج میں، بحوالہ اسماعیل بن ابو خالد نقل کیا ہے۔ فرماتے ہیں: سیدنا عمر رضی اللہ عنہ نے ھرمزان کے لیے دو ہزار(۲۰۰۰) مقرر کیے۔ علی بن عاصم نے، بحوالہ انس رضی اللہ عنہ نقل کیا ہے: ھرمزان سیدنا عمر رضی اللہ عنہ کے پاس آئے، پھر ان کے امان دیے جانے کا قصہ ذکر کیا، سیدنا عمر رضی اللہ عنہ نے فرمایا: اسے میرے پاس سے لے جاؤ، اسے کشتی میں سوار کرانا، پھر کوئی بات کہی، میں نے اس بات کے بارے میں پوچھا: مجھے کہا گیا کہ انہوں نے کہا: اے اللہ! اسے توڑ دے، انہیں کشتی میں سوار کرا لیا گیا، ابھی تھوڑی دوری گئی تھی کہ اس کے تختے کھل گئے اور وہ سمندر میں گر پڑی۔(2) مجھے ان کی یہ بات یاد آگئی: اسے توڑ دے، آپ نے یہ نہیں کہا تھا: اسے غرق کر دے، مجھے نجات کی طلب ہوئی، میں تیرنے لگا اور فتح گیا، پھر اسلام لے آیا۔\nحمید نے نوادر میں، بحوالہ سیدنا عبد اللہ بن خلیفہ نقل کیا ہے کہ میں نے ھرمزان کو سیدنا عمر رضی اللہ عنہ کے ساتھ دیکھا کہ اپنے ہاتھ اٹھائے ہوئے دعا کر رہے تھے اور لا الہ الا اللہ کہہ رہے تھے۔\nکرامیشی نے ادب القضاء میں صحیح سند سے جو سعید بن مسیب تک پہنچی ہے کہ سیدنا عبد الرحمن بن ابی بکر فرماتے ہیں جب سیدنا عمر رضی اللہ عنہ کو شہید کیا گیا تو میں ھرمزان، جفینہ اور ابو لولوہ کے پاس سے گزرا، وہ سرگوشی کر رہے تھے جب انہوں نے مجھے دیکھا تو ادھر ادھر ہو گئے، ان کے درمیان سے اس کا وہ خنجر پڑا جس کے دو سر تھے، اس کا دستہ اس کے درمیان میں تھا، اس خنجر کی طرف دیکھو کہ یہ وہی تو نہیں جس سے سیدنا عمر رضی اللہ عنہ کو شہید کیا گیا، دیکھا گیا تو وہی تھا، وہ عبید اللہ بن عمر کے پاس گئے جب انہوں نے یہ سنا تو اپنی تلوار نکالی اور ھرمزان کے پاس آئے اور اسے قتل کر دیا، جفینہ کو قتل کر دیا اور ابو لولوہ کی چھوٹی بیٹی کو قتل کر دیا، اور مدینہ میں ہر قیدی کو قتل کرنے کا ارادہ کیا، لوگوں نے انہیں روکا۔۔۔۔ جب سیدنا عثمان رضی اللہ عنہ خلیفہ بنے تو ان سے سیدنا عمرو بن العاص نے فرمایا: جس وقت یہ معاملہ ہوا تھا آپ لوگوں کے امیر نہیں تھے، ھرمزان کا خون رائیگاں ہوا۔","",{"fn":"(1) تجريد (۱۱۹/۲)\n(2) جامع المسانید والسنن (۲۷۲/۱۲)"}],[7672,"§۹۰۵۰ ۔ ھریم بن حواس تمیمی\nبنو عامر میں سے ہیں جو بنو کعب بن سعد بن زید مناۃ بن تمیم سے ہیں، انہوں نے نبوت کا زمانہ پایا، وہ مخضرم ہیں، اغلب مجلی جور جز یہ شاعر ہیں، جن کا ذکر قسم اوّل میں حرف الف میں گزر چکا ہے ان کی جو کرتے تھے۔ مرزبان(1) نے معجم الشعراء میں ان کا ذکر کیا ہے۔ بیان کیا گیا کہ وہ عکاظ کے بازار میں آمنا سامنا ہوا اور ان سے کہا: ”تم گزرے ہوئے زمانے اور غلام کی گدی سے بڑے ہو جب قوم پست و بلند ہوتی ہے، تمہارے دشمن صاف نہیں ہوئے جیسے مشکینزے کے اطراف بری سبزی کی وجہ سے صاف نہیں ہوتے“۔ تو انہوں نے ان سے کہا: تمہارا ناس ہو! تم کون ہو؟ تو یہ بولے: ”میں بنو مقا عبس کا جوان ہوں، جو گھوڑ سواروں کی تلواروں کو منہ توڑ جواب دیتے ہیں“۔","",{"fn":"(1) معجم الشعراء (۴۷۲)"}],[7673,"§۹۰۵۱ ۔ ھزال التمیمی\nانہوں نے نبوت کا زمانہ پایا، ان کا قصہ ہے جسے مرزبان نے ذکر کیا ہے، فرماتے ہیں: ہزال تمیمی اور مخنبل السعدی شاعر نے زبرقان کی بیٹی کے لیے نکاح کا پیغام دیا، ہزال کو اس نے رشتہ دے دیا اور مخنبل کو انکار کر دیا، اس سے وہ ناراض ہوا، ہزال نے زبرقان کی باندی کو قتل کیا تھا، فرماتے ہیں: تجمل نے زبرقان کی ہجو کی اور اشعار میں اس پر عار دلایا۔"],[7674,"§۹۰۵۲ ۔ ھزال بن حارث\nبن صعب بن خرم خولانی، انہوں نے نبوت کا زمانہ پایا، فتح مصر میں شریک ہوئے، جب مصر میں داخل ہوئے تو اپنی قوم کے ظالم تھے، ابن یونس نے ان کا ذکر کیا ہے۔"],[7675,"§۹۰۵۳ ۔ ھزیل بن شرحبیل ازدی کوفی\nابو موسیٰ نے ذیل میں ان کا ذکر کیا ہے، فرماتے ہیں: بعض کا قول ہے: انہوں نے جاہلیت کا زمانہ پایا، ابن سعد(1) نے تابعین کے طبقہ اولیٰ میں ان کا ذکر کیا ہے اور انہیں ثقہ قرار دیا ہے۔\nمیں کہتا ہوں: انہوں نے ابو ذر، ابن مسعود، عثمان، علی، طلحہ، سعد بن ابی وقاص، قیس بن سعد بن عبادہ وغیرہ کبار تابعین سے روایت کی، ان سے شعبی، ابو اسحاق، طلحہ بن مصرف، عمرو بن مرہ اور دوسرے لوگوں نے روایت کی، دار قطنی نے انہیں ثقہ کہا ہے، عجلی کا قول ہے: سیدنا عبد اللہ بن مسعود کے ساتھیوں میں ان کا شمار ہے۔","",{"fn":"(1) طبقات الکبریٰ (۱۲۲/۶)"}],[7676,"§۹۰۵۴ ۔ ھلال بن علفہ\n(1) عین کے پیش، لام کی تشدید اور اس کے بعد فاء ہے۔","",{"fn":"(1) اسد الغابة (۵۳۹۱)"}],[7677,"§۹۰۵۵ ۔ ھلال بن وکیع\n(1) ابن بشر بن عمرو بن عدی بن دارم، ابو عمر(2) نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ کوئی مستند روایت نقل نہیں کی، فرماتے ہیں: جمل کے دن شہید ہوئے، زید بن جبلہ کے سوانح میں گزر چکا ہے کہ ھلال بن وکیع وفد میں سیدنا عمر رضی اللہ عنہ کے پاس آئے، اس سے پتہ چلتا ہے کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم کو نہیں دیکھا، لہذا وہ اس قسم میں سے ہیں۔","",{"fn":"(1) اسد الغابة (۵۳۹۵) استیعاب (۲۷۲۳) تجريد (۱۲۲/۲)\n(2) استیعاب (۱۰/۴، ۹)"}],[7678,"§۹۰۵۶ ۔ ھمدان صنعانی\nاہل یمن کے سیدنا عمر رضی اللہ عنہ کی طرف قاصد ہیں، انہوں نے نبی کریم صلی اللہ علیہ وسلم کا زمانہ پایا اور سیدنا عمر رضی اللہ عنہ سے روایت کی، یہ قول نقل کیا: نماز کی باتیں کرنے والوں کی نسبت ستونوں کے زیادہ حق دار ہیں، اسے حمیدی نے نوادر میں اور ابن ابی شیبہ دونوں نے بحوالہ ھمدان نقل کیا ہے۔"],[7679,"§۹۰۵۷ ۔ ھملع بن اعفر تمیمی\nبنو تمیم سے ہیں، مرزبان(1) نے معجم الشعراء میں لکھا ہے۔ مخضرم ہیں، بلعمرہ میں فروکش ہوئے، سیدنا زبیر بن عوام نے ان کی بیٹی کے لیے نکاح کا پیغام دیا، انہوں نے انکار کر دیا، انہوں نے اس کے بارے میں اشعار کہے جن میں سے یہ ہے۔ ”میں خوش اسلوبی سے خرید و فروخت کرتا ہوں اگر کہیں میرا سودا ہو جائے اور زینب جواری کو ہدیہ کرے“۔","",{"fn":"(1) معجم الشعراء (۴۷۳)"}],[7680,"§۹۰۵۸ ۔ ھند بن عمرو جملی\nمرادی، انہوں نے جاہلیت کا زمانہ پایا، سیدنا عمر رضی اللہ عنہ نے انہیں سے اس میں انصاری بنو ثعلب پر امیر بنایا تھا، انہوں نے ہند ابن عبد اللہ بن شریفی نفی کو قتل کیا، اس کے بارے میں کہتے ہیں: ”اگر تم مجھے قتل کر تو میں ابن شریفی ہوں، علی اور ہند جملی کا قاتل ہوں“۔ جنگ جمل میں سیدنا علی رضی اللہ عنہ کے ساتھ مارے گئے، ابن فحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔"],[7681,"§۹۰۵۹ ۔ ھُنّی\nتشدید کے ساتھ ہے، مولیٰ عمر ہیں، انہوں نے نبی کریم صلی اللہ علیہ وسلم کا زمانہ پایا۔ سیدنا عمر رضی اللہ عنہ نے انہیں چراگاہ کا نگران بنایا، صحیح بخاری رحمہ اللہ میں اس کے بارے میں روایت ہے۔\nابن سعد نے، بحوالہ واقدی، انہوں نے عمرو بن عیبر بن ھنی، عن ابیہ، عن جدہ نقل کیا ہے، فرماتے ہیں: سیدنا ابو بکر رضی اللہ عنہ نے بقبح کے علاوہ کوئی زمین، سرکاری زمین قرار نہیں دی، جب سیدنا عمر رضی اللہ عنہ کا زمانہ آیا اور لوگ بہت ہو گئے تو مجھے ربدہ کی چراگاہ پر نگران بنایا، ابن سعد نے بھی، بحوالہ جعفر بن محمد نقل کیا ہے کہ میں نے انصار کے ایک شخص سے سنا کہ میرے والد سے ھنی کے بارے میں بات چیت کر رہا ہے جو مولیٰ عمر ہیں کہ وہ صفین میں شریک تھے، پھر سیدنا عمار رضی اللہ عنہ کی طرح قصہ ذکر کیا۔ اس کے بارے میں سیدنا عمرو بن العاص رضی اللہ عنہ کے ساتھ قصہ نقل کیا۔"],[7682,"§۹۰۶۰ ۔ ھودہ بن الحارث\n(1) ابن عجر وابن عبد اللہ بن یظفر سلمی، ابن حامد کے نام سے معروف ہیں، یہ ان کی والدہ ہیں، انہوں نے نبوت کا زمانہ پایا۔ مرزبان(2) نے نجم اشعراء میں ان کا ذکر کیا ہے، فرماتے ہیں: سیدنا عمر بن خطاب رضی اللہ عنہ کے زمانے میں عطیات آئے، آپ رضی اللہ عنہ نے ان سے پہلے ان کی قوم کے لوگوں کو بلایا تو انہوں نے کہا: ”معاملہ نا اہل کے سپرد ہو گیا ہے، دیکھو! اللہ کا امین کیسے پھنستا ہے، کیا تم اور شریر کو ہم سے آگے بلایا اور براج اور طرح ودو کو ہم سے پہلے بلایا۔ اگر یہ اللہ کی کتاب کے مطابق ہے تو ٹھیک ہے، کیونکہ وہ آزاد، بادشاہ کے بیٹے ہیں اور ہم غلام ہیں“۔\nمیں کہتا ہوں: چاوں جن کا ذکر ہے، میرے خیال میں صحابہ رضی اللہ عنہم ہیں۔ شریر ابن سلمی مشہور صحابی ہیں۔ گویا انہیں صحابی ہونے کی وجہ سے ھودہ سے پہلے ذکر کیا گیا اور یہ خود اسلام لانے سے پہلے ان پر مقدم تھے، جیسا کہ اس طرح کی صورتحال حارث بن ہشام اور ان جیسے دوسرے لوگوں کے ساتھ پیش آئی جب انہوں نے صہیب جیسے لوگوں کو دیکھا کہ انہیں ان سے پہلے سیدنا عمر رضی اللہ عنہ کے پاس آنے کی اجازت ملتی ہے۔","",{"fn":"(1) اسد الغابة (۵۴۰۹)\n(2) معجم الشعراء (۴۵۹)"}],[7683,"§۹۰۶۱ ۔ ھودہ بن عبد اللہ\nابن طفیل، اجنادین میں شہید ہوئے، تاریخ مظفری میں ان کا ذکر ہے۔"],[7684,"§۹۰۶۲ ۔ ھودہ\nبے نسبت، ابن عساکر نے اپنی تاریخ میں ان کا ذکر کیا ہے۔ فرماتے ہیں: انہوں نے نبی کریم صلی اللہ علیہ وسلم کا زمانہ پایا، بدر میں مشرکین کے ساتھ شریک تھے۔ پھر بعد میں اسلام لے آئے اور سیدنا معاویہ رضی اللہ عنہ کی خلافت میں ان کے پاس وفد میں آئے، ابن مندہ نے بطریق رجعہ بن عصمہ، بحوالہ شعبی نقل کیا ہے، فرماتے ہیں: سیدنا معاویہ کے پاس ھودہ نامی ایک شخص آیا، سیدنا معاویہ نے ان سے کہا: کیا تم بدر میں شریک تھے، اس نے کہا: جی ہاں! اے امیر المومنین! وہ میرے لیے وبال تھا نہ کہ فائدہ مند، گلو گیا میں دیکھ رہا تھا کہ ان کی تلواروں کی چمک سورج کی شعاع ہے جو بادلوں کے درمیان ہو، انہوں نے کہا: تمہاری عمر کتنی تھی؟ انہوں نے کہا: میں انتہائی مضبوط اور لمبا انسان تھا جیسے سخت پتھر ہوتا ہے۔ پھر واقعہ ذکر کیا، ابو نعیم کا قول ہے: ان کا صحابی ہونا درست نہیں کیونکہ وہ نبی کریم صلی اللہ علیہ وسلم کی وفات کے بعد اسلام لائے۔"],[7685,"§۹۰۶۳ ۔ ھیشم بن اسود\nابن قیس بن معاویہ بن سفیان مخی، ان کی کنیت ابو عمر بان ہے، ابو عمر نے یہ جائز کہا ہے کہ یہ وہی ہیں جن سے حدیث مروی ہے۔ ابن کلبی نے بحوالہ عمران ان کا ذکر کیا ہے۔ ان کا مغیرہ بن شعبہ کے ساتھ قصہ ذکر کیا ہے، جب وہ خلافت عمر میں بصرہ کے امیر تھے، اس سے پتہ چلتا ہے کہ انہوں نے نبوت کا زمانہ پایا، ابن کلبی کا قول ہے: نہ حج کے لوگوں میں سے تھے، ان کے والد قادسیہ کے دن شہید ہوئے۔\nمرزبان نے نجم اشعراء میں نقل کیا ہے، ابو عمران ان لوگوں میں سے تھے جنہوں نے حجر بن عدی کے خلاف گواہی دی تھی، وہ طویل عمر تک زندہ رہے، ابو احمد حاکم نے کتابوں میں ان کا ذکر کیا ہے اور بطریق عبد الملک بن عمیر روایت نقل کی ہے، فرماتے ہیں: عمرو بن خریث نے ابو العریان کی عیادت کی اور کہا: کیا حال ہے؟ انہوں نے کہا: وہ چیزیں سفید ہو گئی ہیں جو مجھے پسند تھیں کہ سیاہ ہو جائیں اور وہ چیزیں سیاہ ہو گئیں جو مجھے پسند تھیں کہ سفید ہو جائیں اور یہ اشعار پڑھے۔ ”سنو! میں تمہیں بڑھاپے کی نشانیوں سے خبر دار کرتا ہوں، قدموں کا چھوٹا ہو جانا، نظر کی کمزوری، اور جب کھانا حاضر ہو تو بھوک کم لگے، جب یاد دلایا جائے تو بات بات پر بھول جائے“۔\nرہا: ابو عمر کا یہ جواز پیش کرنا یہ وہی ہیں جن سے محمد بن سیرین نے حدیث سہو کی نقل کی ہے، کتابوں میں اس کا بیان آئے گا۔"],[7686,"§۹۰۶۴ ۔ ھیشم حنفی\nوثیمہ نے کتاب الردہ میں ان کا ذکر کیا ہے اور ان کا ایک شعر ذکر کیا ہے جس سے پتہ چلتا ہے کہ اسلام پر قائم رہے۔\nسیف نے فتوح میں ذکر کیا ہے کہ سیدنا ابو بکر رضی اللہ عنہ نے سیدنا خالد رضی اللہ عنہ کی طرف خط لکھا کہ میں نے تمہارے اور لوگوں کے درمیان اذان کو علامت بنایا ہے۔ جہاں اذان ہو اس علامت کو چھوڑ دو اور جہاں اذان نہ ہو وہاں جھاد کرو، اس کے بارے میں بنو حنیفہ کا ھیشم نامی ایک شخص کہتا ہے۔ سیدنا خالد بن ولید رضی اللہ عنہ کے لشکر نے اسے گرفتار کر لیا تھا۔ ”کیا تم دیکھتے ہو کہ خالد ہمیں چھوڑنے سے گناہ کی وجہ سے بے دریغ قتل کر رہا ہے۔ خواہ خواہ ہمیں چھوٹا قرار دے رہا ہے، ہم نے تو نبی کریم صلی اللہ علیہ وسلم کے دین کو چھوڑا ہے اور نہ ہی ہم اس سے پھرے ہیں۔“ سیدنا خالد رضی اللہ عنہ کو یہ بات معلوم ہوئی تو اسے چھوڑ دیا۔ جب وہ خشیر سے واپس ہوا تو اس کی سواری نے اسے اچھال دیا، جس سے وہ فوت ہو گیا۔"],[7687,"§۹۰۶۵ ۔ ھیشم بن مالک تنوخی\nبنو ساعدہ سے ہیں، انہوں نے نبوت کا زمانہ پایا، ابو سعید بن یونس کا قول ہے: فتح مصر میں شریک ہوئے، انہوں نے اپنی کتابوں میں ان کا ذکر کیا ہے۔"],[7688,"§۹۰۶۶ ۔ الھاد\nزہبی نے تجرید میں ذکر کیا ہے کہ مسند قی بن مخلد میں ان کی ایک حدیث ہے۔ خطا ہے، حدیث ان کے بیٹے شداد بن الھاد لیثی سے مروی ہے۔"],[7689,"§۹۰۶۷ ۔ ھجنع بن عبد اللہ\nابن جعفر بن بکاء بن عامر بن صحصحہ عامری، ابن قانع نے صحابہ میں ان کا ذکر کیا ہے، اس کے بارے میں انہوں نے واضح غلطی کی ہے اور بطریق عقبہ بن وہب بن عقبہ، عن ابیہ نقل کیا ہے کہ حجنع نے عرض کیا: یا رسول اللہ صلی اللہ علیہ وسلم! ہمارے لیے مروارید میں سے کیا حلال ہے؟ (الحدیث)۔(1) ان کا قول صحیح لفظی غلطی ہے، وہ فجیع ہیں، حرف فاء میں صحیح گزر چکا ہے۔ حدیث ابو داؤد کے ہاں ہے، اسے خطیب نے مؤتلف میں اس طریق سے نقل کیا ہے، جسے ابن قانع نے بیان کیا ہے، فرماتے ہیں: بحوالہ حجنع بن عبد اللہ پھر اس کا ذکر کیا ہے، فرماتے ہیں: اسی طرح لکھا ہے صحیح فجیع بن عبد اللہ ہے۔","",{"fn":"(1) ابو داود (۳۸۱۷)"}],[7690,"§۹۰۶۸ ۔ ھجنع بن قیس حارثی\nالبوہری نے ذیل میں ان کا ذکر کیا ہے، فرماتے ہیں: ابو بکر بن علی نے صحابہ میں ان کا ذکر کیا ہے اور بطریق ہشیم، بحوالہ حجنع حدیث نقل کی ہے، فرماتے ہیں رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جسے یہ پسند ہو کہ حضرت عیسیٰ بن مریم کو دیکھے، اسے چاہیے کہ ابو ذر کو دیکھ لے۔“ اسے ابن عساکر نے ابو ذر کے سوانح میں بطریق ہشیم نقل کیا ہے، فرماتے ہیں: یہ روایت مرسل ہے۔\nمیں کہتا ہوں: طبرانی نے مذکورہ حدیث بروایت ابراہیم جرجی، بحوالہ عبد اللہ بن مسعود نقل کی ہے۔\nابو حاتم رازی کا قول ہے: حجنع نے بحوالہ سیدنا علی رضی اللہ عنہ مرسل حدیث نقل کی ہے، ابن حبان نے اتباع التابعین میں ان کا ذکر کیا ہے، فرماتے ہیں: انہوں نے حضرت ابراہیم نخعی کے حوالے سے روایت کی ہے، ابن یونس نے اسے تاریخ مصر میں ذکر کیا ہے، فرماتے ہیں: انہوں نے بحوالہ حذیفہ روایت کیا ہے کہ اشعثمین کے ہاں وہ ظہر کرتے تھے۔ فرماتے ہیں: میرا خیال ہے وہ کون سے آگئے تھے، پھر بطریق ابن وہب، بحوالہ عبد الرحمن بن رزین نقل کیا ہے کہ حجنع بن قیس نے ان سے بیان کیا کہ ایک شخص نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم! مجھے دنیا میں سے کیا چیز کافی ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”جو تیرا پیٹ بھر دے اور تیرا ستر ڈھانک دے“۔"],[7691,"§۹۰۶۹ ۔ ھدیل\nالبوہری نے ذیل میں ان کا ذکر کیا ہے، اور بطریق ابن ابی ذینال ان کی سند سے جو ابو داؤد تک پہنچتی ہے، بحوالہ ابی ساقط نقل کیا ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اگر کسی شے نے کوئی شے کی وجہ سے چھوڑ دیا جاتا تو حدیل کو اس کے مال باپ کی وجہ سے چھوڑ دیا جاتا۔“\nمیں کہتا ہوں: البوہری کو وہم ہوا ہے کہ یہ حدیل کسی آدمی کا نام ہے، جبکہ ایسا نہیں، وہ اسم جنس ہے یہ فاختہ کا نر بچہ ہے، یہاں مراد ضرب المثل ہے، ذوالرمت شاعر کا قول ہے: ”میں کہتا ہوں کیا طوق والا پرندہ حدیل کو یاد کر کے روتا ہے، حدیل کی یہ رسم پرانی ہے۔“"],[7692,"§۹۰۷۰ ۔ ھرماس بن حبیب عنبری\nابن حبان کا قول ہے: انہیں شرف صحابیت حاصل ہے، اسی طرح حرماس بن زیاد کے بعد ان کا ذکر کیا ہے، وہ خطا ہے۔ کیونکہ بخاری(1) نے حرماس بن زیاد کے بعد حرماس بن حبیب کا ذکر کیا ہے، لیکن فرماتے ہیں: انہوں نے اپنے والد کے حوالے سے، انہوں نے اپنے دادا سے روایت کیا ہے، ان سے نضر بن شمیل نے روایت کیا ہے، یہی صحیح ہے، ہرماس بن حبیب تابعین میں سے ہیں۔ ان کے دادا کے نام میں اختلاف ہے۔","",{"fn":"(1) تاریخ کبیر (۲۴۷/۴)"}],[7693,"§۹۰۷۱ ۔ ھرم بن مسعدہ\nبنو عدی بن سجاد سے ہیں، ابن شاہین نے بحوالہ ابن کلبی ان کا ذکر کیا ہے۔ ان کے اور ان کے والد کے نام میں لفظی غلطی ہے، وہ ہم ابن مسعدہ ہیں، بنو عبس کے وفد کے نو(۹) افراد میں سے ایک ہیں، اسی طرح ابن کلبی رضی اللہ عنہ نے درست ان کا ذکر کیا ہے، رشاطی وغیرہ نے ان کی پیروی کی ہے، قسم اوّل میں ان کا ذکر گزر چکا ہے۔"],[7694,"§۹۰۷۲ ۔ ھزال بن مُرّہ اشجعی\n(1) آزرقی نے صحابہ میں ان کا ذکر کیا ہے، یہ ابو عمر کا قول ہے۔\nمیں کہتا ہوں: وہ خطا ہے جو لفظی غلطی سے پیدا ہوئی وہ ہلال بن مُرّہ ہیں۔ جیسا کہ قسم اوّل میں گزر چکا ہے۔","",{"fn":"(1) اسد الغابة (۵۳۶۱)"}],[7695,"§۹۰۷۳ ۔ ھشام بن عتبہ\nابن ابی وقاص، پہلے گزر چکا ہے کہ صحیح ھاشم ہے، جیسا کہ پہلی قسم میں گزر چکا ہے۔"],[7696,"§۹۰۷۴ ۔ ھشام بن قتادہ رُھاوی\n(1) بغوی نے اور یحییٰ بن یونس، ابو یحیٰ نے اس غلطی کی پیروی کرتے ہوئے ان کا ذکر کیا ہے جو سند سے ان کے والد کا ذکر بعض راویوں سے رہ جانے کی وجہ سے پیدا ہوئی۔\nبغوی کا قول ہے: ہم سے ابو بکر بن زنجویہ نے بحوالہ ھشام بن قتادہ نقل کیا ہے، فرماتے ہیں: جب نبی کریم صلی اللہ علیہ وسلم نے مجھے میری قوم کا جھنڈا باندھ کر دیا تو میں نے آپ صلی اللہ علیہ وسلم کا ہاتھ پکڑا اور آپ صلی اللہ علیہ وسلم کو الوداع کہا، ابو موسیٰ نے ذیل میں فرمایا: دوسرے راویوں نے بحوالہ علی بن بحر یعنی اس سند سے ھشام بن قتادہ تک نقل کیا ہے، فرماتے ہیں: عمن ابیہ، فرمایا: جب رسول اللہ صلی اللہ علیہ وسلم نے مجھے جھنڈا باندھ کر دیا۔(2)\nمیں کہتا ہوں: یہی صحیح ہے، اسے احمد بن ابی خیثمہ نے بحوالہ علی بن بحر اسی طرح نقل کیا ہے، اسی طرح بخاری رضی اللہ عنہ نے اسے بحوالہ احمد بن ابی طالب، انہوں نے قتادہ بن فضل سے نقل کیا ہے، اسی طرح طبرانی میں وہ دوسرے طریق سے بحوالہ علی بن بحر ہے، بخاری، ابن ابی حاتم(3) اور ابن حبان وغیرہ نے ھشام بن قتادہ کا تابعین میں ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۵۳۷۵) تجريد (۱۲۱/۲)\n(2) المعجم الکبیر (۲۲/۱۹) مجمع الزوائد (۱۳۱/۱۰) الدر المنثور (۳۲۱/۱) کنز العمال (۷۴۷۸) جامع المسانید والسنن (۲۹/۱۲)\n(3) الجرح والتعدیل (۶۸/۹)"}],[7697,"§۹۰۷۵ ۔ ھشام بن مغیرہ\n(1) ابن العاص، یحییٰ بن یونس اور مستغفری نے صحابہ میں ان کا ذکر کیا ہے، ابو موسیٰ نے ذیل میں ان کی پیروی کی ہے، انہوں نے بطریق ابی عثمان بحوالہ عمرو بن ھشام، انہوں نے اپنے دادا عمرو اور ھشام سے نقل کیا ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”قرآن اس لیے نازل ہوا تا کہ اس کے بعض حصے دوسرے حصوں کی تصدیق کریں۔۔۔۔“ (الحدیث)۔(2) سند میں یہ الفاظ عن عمرو بن ھشام، اس میں غلطی ہے، وہ عمرو بن شعیب ہیں ان کے دونوں دادا عمرو اور ھشام، عاص بن وائل کے بیٹے ہیں، مخیرہ بن ھشام اور عاص کا تذکرہ سوانح میں اضافہ ہے، جس کی ضرورت نہیں ہے۔ ھشام بن عاص کے سوانح میں بروایت سعید بن سعید، بحوالہ ابن ابی حازم، عن ابیہ، عن عمرو بن شعیب، عن ابیہ، عن جدہ ان کی حدیث گزر چکی ہے۔ فرماتے ہیں: میں اور میر ابھائی ھشام نبی کریم صلی اللہ علیہ وسلم کے دروازے پر تھے۔۔۔۔ پھر قصہ ذکر کیا۔","",{"fn":"(1) اسد الغابة (۵۳۷۷) استیعاب (۲۷۱۶) تجريد (۱۲۱/۲)\n(2) تاریخ کبیر (۱۹۹/۴) شرح السنہ (۶/۸)"}],[7698,"§۹۰۷۶ ۔ ھلال بن حارث\n(1) ابو الحکل، اپنی کنیت سے مشہور ہیں، اسی طرح ابن عبد البر(2) نے اسے نقل کیا ہے، پھر کتابوں میں دوبارہ اسے ذکر کیا ہے۔\nعباس بن محمد نے بحوالہ ابن معین ان کا نسب بیان کیا ہے، وہ وھب پر انہوں نے بہت بری لفظی غلطی کی ہے، وہ ابو الحرم ہیں، ان کے ساتھیوں اور تبعین نے ان کا تعاقب کیا ہے، یہ بات اس سے زیادہ مشہور ہے، اللہ ہی کی توفیق سے ہے۔","",{"fn":"(1) اسد الغابة (۵۳۸۲) استیعاب (۲۷۱۹) تجريد (۱۲۱/۲)\n(2) استیعاب (۱۰۳/۴)"}],[7699,"§۹۰۷۷ ۔ ھلال بن حکم\n(1) مستغفری نے ان کا ذکر کیا ہے اور بطریق علی بن سلمہ، بحوالہ ھلال بن حکم نقل کیا ہے۔ فرماتے ہیں: جب میں نبی کریم صلی اللہ علیہ وسلم کے پاس آیا تو میں نے اسلام کی بہت سی باتیں سیکھیں، ان میں سے ایک یہ بھی تھی کہ جب کوئی شخص چھینک لے، پھر اللہ کی حمد بیان کرے تو میں اس کا جواب دوں۔۔۔۔ (الحدیث)۔ اس میں چھینکنے والے کا جواب دینا جبکہ وہ نماز پڑھ رہا ہو، مذکور ہے، ابو موسیٰ نے ذیل میں فرمایا: یہ حدیث معاویہ بن حکم کے بارے میں مشہور ہے، اس راوی کے بارے میں وہم ہے۔\nمیں کہتا ہوں: اس کا تعین نہیں، وہ علی بن سلمہ ہیں، اسے ابو داؤد(2) نے بحوالہ عبد الملک بن عمرو اس سند سے نقل کیا ہے، فرماتے ہیں: بحوالہ معاویہ بن حکم، وہ، اور مسلم اور نسائی کے ہاں بطریق یحییٰ بن ابی کثیر، بحوالہ ھلال بن علی اسی طرح مروی ہے۔","",{"fn":"(1) اسد الغابة (۵۳۸۲) تجريد (۱۲۱/۲)\n(2) ابو داود (۵۰۳۱)"}],[7700,"§۹۰۷۸ ۔ ھلال بن ربیعہ\n(1) ابن مندہ نے ان کا ذکر کیا ہے اور بطریق عبد الرحمن بن بشیر، بحوالہ ابن اسحاق،(2) انہوں نے ھلال بن ربیعہ سے نقل کیا ہے، فرماتے ہیں: میں نے سیف بن عائذ مخزومی کو گرفتار کر لیا، پھر اسے مال غنیمت میں شامل کر دیا، اسے ارقم بن ابی ارقم مخزومی نے دیکھا تو رسول اللہ صلی اللہ علیہ وسلم سے اس کا سوال کیا، آپ صلی اللہ علیہ وسلم نے اسے ان کو عطا فرما دیا۔(3) ابو ابراہیم کا قول ہے: صحیح نام مالک بن ربیعہ ہے، وہ ابو اسید ساعدی ہیں، پھر بطریق ابراہیم بن سعد، بحوالہ ابن اسحاق اسی طرح نقل کیا۔\nمیں کہتا ہوں: کاش ابن مندہ اپنے وسعت علم کے باوجود خاموش رہتے۔","",{"fn":"(1) اسد الغابة (۵۳۸۶) تجريد (۱۲۱/۲)\n(2) السیرة النبویة (۲۱۴/۲)\n(3) تفسیر طبری (۳۷۴/۱۳) تفسیر ابن کثیر سورہ انفال الآیۃ (۵۴/۳)"}],[7701,"§۹۰۷۹ ۔ ھلال بن عامر\nابن مندہ نے صحابہ میں ان کا ذکر کیا ہے، انہیں صریح وہم ہوا ہے۔ انہوں نے انہیں صحابی خیال کیا، جبکہ وہ معروف قبیلے کا نام ہے جو اپنے دادا ھلال بن عامر کی طرف منسوب ہیں۔\nحرف نون میں نمیر بن عامر کے سوانح میں اس کا بیان گزر چکا ہے۔"],[7702,"§۹۰۸۰ ۔ ھلال بن عامر مُزنی\n(1) دوسرے ہیں، جعفر مستغفری نے ان کا ذکر کیا ہے، انہیں اس میں وہم ہوا ہے۔ وہ تابعی ہیں، پھر بطریق عبدہ، بحوالہ محمد بن عبد اللہ طفسی نقل کیا ہے کہ میں نے بنو فزارہ کے ایک شیخ سے بحوالہ ھلال بن عامر مزنی وغیرہ حدیث بیان کرتے ہوئے سنا، فرماتے ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو سورت فجر کی تلاوت پر دیکھا۔۔۔۔ (الحدیث)۔\nمیں کہتا ہوں: ابو موسیٰ نے ذیل میں ان کی پیروی کی ہے، اسے ھلال بن عامر نے اپنے والد سے، انہوں نے رافع بن عمر سے نقل کیا ہے، اسے امام احمد رضی اللہ عنہ نے بحوالہ محمد بن عبید اسی طرح بحوالہ ھلال بن عامر، عن ابیہ نقل کیا ہے، ابو داؤد اور نسائی نے بطریق مروان بن معاویہ، بحوالہ رافع نقل کیا ہے، ابو معاویہ نے لعلی بن عید، یکین بن قطان وغیرہ کی پیروی کی ہے، یہ راجح ہے۔","",{"fn":"(1) تجريد (۱۲۲/۲)"}],[7703,"§۹۰۸۱ ۔ ھَمّام\n(1) مولیٰ رسول اللہ صلی اللہ علیہ وسلم، ابو موسیٰ نے بطریق جعفر مستغفری، بحوالہ بردع نقل کیا ہے کہ ابو الزبیر نے بحوالہ ھمام مولیٰ رسول اللہ صلی اللہ علیہ وسلم نقل کیا کہ ایک شخص نے کہا: یا رسول اللہ! میری بیوی بڑھنے والے ہاتھ کو روک نہیں کرتی۔۔۔۔ (الحدیث)۔(2) اس میں لفظی غلطی ہے، وہ ھشام ہیں، جیسا کہ قسم اوّل میں گزر چکا ہے۔","",{"fn":"(1) اسد الغابة (۵۳۹۹)\n(2) ابو داود (۲۰۴۹) نسائی (۳۴۶۴) نصب الرایۃ (۳۵۳/۳) تذکرۃ الموضوعات (۱۱۹)"}],[7704,"§۹۰۸۲ ۔ ھَنّاد\nمیں نے جزو ابو اسحاق بن ابو ثابت میں ان کی سند سے جو عزمی تک پہنچتی ہے، وہ محمد بن عبید عزری ہیں، بحوالہ عبد اللہ بن عبد اللہ بن ھناد، عن ابیہ، فرماتے ہیں: ھناد نے اپنی بیٹی کی شادی کی، اس میں دف بجائے۔ وہ لفظی غلطی ہے، وہ ہبار ہیں: جیسا کہ پہلی قسم میں صحیح گزر چکا ہے۔"],[7705,"§۹۰۸۳ ۔ ھنیدہ بن مُغفل غفاری\nابن اسحاق نے صحابہ میں ان کا ذکر کیا ہے، فرماتے ہیں: انہیں شرف صحابیت حاصل ہے، مصر میں رہائش تھی، میرا خیال ہے کہ وہ حبیب بن مُغفل ہیں۔\nمیں کہتا ہوں: ایسا ہی ہے جیسا کہ ان کا خیال ہے۔ لگتا ہے انہیں کہیں سے درست نام مل گیا ہے۔ لہذا اسے ذکر دیا پھر انہیں کسی جگہ سے غلط نام ملا، انہوں نے اسے احتیاط سے ذکر کر دیا، اس میں کوئی شک نہیں کہ وہ ایک ہی شخص ہیں۔ ان کے والد مُغفل ہیں۔"],[7706,"§۹۰۸۴ ۔ ھودہ بن قیس\n(1) ابن عمارہ بن وثیم انصاری، ابن شاہین اور ابن مندہ نے ان کا ذکر کیا ہے، ان دونوں کو اس میں وہم ہوا ہے۔ شرف صحابیت ان کے بیٹے معبد کو حاصل ہے۔ ابن شاہین نے بطریق صالح بن زریق، بحوالہ عبد الرحمن بن معبد بن ھودہ، عن ابیہ، عن جدہ نقل کیا ہے۔\nابن مندہ نے بطریق نفیلی، بحوالہ عبد الرحمن بن نعمان بن ھودہ، عن ابیہ، عن جدہ نقل کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے خوشبودار انشمرے کا حکم دیا اور فرمایا: ”روزہ دار کو اس سے بچنا چاہیے۔“(2)\nصحیح یہ ہے جو امام احمد، ابو داؤد، ابن قانع نے بطریق عبد الرحمن بن نعمان بن معبد بن ھودہ، عن ابیہ، عن جدہ نقل کیا ہے۔ پہلی روایت میں، راوی کے نسب میں نعمان اور دوسری روایت میں معبد کا نام رہ گیا ہے۔ علائی نے اس پر تنبیہ کی ہے، شرف صحابیت معبد بن ھودہ کو حاصل ہے۔\nابن مندہ نے جو کچھ ذکر کیا ہے اس سے ابن اثیر(3) کو دھوکا ہوا ہے۔ چنانچہ انہوں نے وہ حدیث ان کے سوانح میں مند احمد سے نقل کی ہے، اور اسے ابن مندہ کے سیاق پر نقل کیا ہے، جو ان کا وہم ہے، جبکہ مند میں جو سند ہے اس میں نعمان کا نام لکھا ہوا ہے۔","",{"fn":"(1) اسد الغابة (۵۴۱۳) تجريد (۱۲۴/۲)\n(2) ابو داود (۳۲۷۷) مسند احمد (۵۰/۳)\n(3) اسد الغابة (۲۹۷/۴)"}],[7707,"§۹۰۸۵ ۔ ھودہ عُصری\nابن قانع نے ان کا ذکر کیا ہے، انہیں اس میں وہم ہوا ہے جو ظاہر ہے۔ انہوں نے ان کے سوانح میں حدیث بطریق ھودہ عصری، عن جدہ نقل کیا ہے۔ مجھے معلوم نہیں کہ کیسے وہ خبر ہے، یہاں تک کہ ھودہ کو صحابی کہا جبکہ شرف صحابیت ان کے نانا کو حاصل ہے، وہ ان کے نانا ہیں ان کا نام مرشد بن جابر ہے، جیسا کہ حرف میم میں گزر چکا ہے۔"],[7708,"§۹۰۸۶ ۔ ھیشم بن ربیع\nابو نعیم بحری، کتابوں میں ان کا ذکر آئے گا۔"],[7709,"§۹۰۸۷ ۔ ھیشم بن مالک طائی\nتابعی ہیں، اہل شام میں سے ہیں۔ انہوں نے مرسل حدیث نقل کی تو بعض نے انہیں صحابی گمان کیا۔ ابراہیم حربی نے بطریق صفوان بن عمرو، بحوالہ ھیشم بن مالک نقل کیا ہے، فرماتے ہیں: ایک خاتون نبی کریم صلی اللہ علیہ وسلم کے پاس اپنے شوہر کی شکایت لے کر آئی، آپ صلی اللہ علیہ وسلم نے فرمایا: ”کیا تم چاہتی ہو کہ زلفوں والے سے شادی کرو، اور اس کی ہرٹ سے شیطان پیدا ہو۔“ یہ حدیث صحیح السند مرسل ہے۔\nبیہقی نے بطریق ھیشم بن مالک اسی طرح نقل کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم نے خطبہ دیا، ایک شخص رونے لگا تو نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”اگر آج تم میں ہر ایمان والے شخص پر مضبوط پہاڑ جیسے گناہ ہوتے تو اس آدمی کے رونے کی وجہ سے اس کی بخشش کر دی جاتی۔“ یہ اس لیے کہ جب کوئی شخص روتا اور دعا کرتا ہے تو فرشتے کہتے ہیں: اے اللہ! رونے والوں کی نہ رونے والوں کے بارے میں سفارش قبول فرما۔\nاسے بخاری، ابن ابی حاتم وغیرہ نے تابعین سے نقل کیا ہے۔ واللہ اعلم"],[7710,"§۹۰۸۸ ۔ وابصہ بن معبد\n(1) ابن عقبہ بن حارث بن مالک بن حارث بن قیس بن کعب بن سعید بن حارث بن ثعلبہ بن دودان بن اسد بن خزیمہ اسدی، ابو حاتم کا قول ہے: وہ وابصہ بن عبید ہیں، معبد کا لقب ابو اسلم تھا، بعض کا قول ہے: ابو عثمان، بعض نے کہا: ابو سعید ہے۔\nوہ میں نبی کریم صلی اللہ علیہ وسلم کے پاس وفد میں آئے، انہوں نے نبی کریم صلی اللہ علیہ وسلم ابن مسعود، ام قیس بنت محصن وغیرہ سے روایت کی، ان سے ان کے دونوں بیٹوں سالم اور عمر نے اور زر بن حبیش، شداد مولیٰ عیاش، راشد بن سعد، زیاد بن ابی جعدہ وغیرہ نے روایت کی۔\nجزیرہ میں فروکش ہوئے، ابو علی حرافی نے تاریخ رقہ میں بطریق عبد اللہ بن عمرو ورقی نقل کیا ہے کہ مجھ سے ابو عبد اللہ ورقی نے بیان کیا وہ حضرت عمر بن عبد العزیز کے مددگار تھے، فرماتے ہیں: سیدنا عمر رضی اللہ عنہ نے مجھے مال دے کر بھیجا اور وابصہ کی طرف لکھا کہ میرے ساتھ سپاہیوں کو بھیجیں جو لوگوں کو جمعے سے روکے رکھیں، انہوں نے کہا: یہ مال جاری نہر پر تقسیم کرنا مجھے خدشہ ہے کہ لوگ پیاسے ہو جائیں گے۔\nابو علی کا قول ہے: میرا خیال ہے کہ یہ وہم ہے کیونکہ وابصہ خلافت عمر بن عبد العزیز تک زندہ نہ رہے۔\nایسا ہی ہے جیسا کہ ان کا گمان ہے۔ فرماتے ہیں: ہو سکتا ہے کہ اصل میں یہ وابصہ کا بیٹا ہو۔","",{"fn":"(1) اسد الغابة (۵۴۲۱)"}],[7711,"§۹۰۸۹ ۔ وابصہ بن خالد\nابن عبد اللہ بن عمر بن مخزوم قرشی مخزومی، ہشام بن کلبی نے ان لوگوں میں ان کا ذکر کیا ہے جنہیں تالیف قلب کے لیے مال دیا گیا۔ ان کی کتاب کے آخر میں جنگوں میں ان کا ذکر ہے۔"],[7712,"§۹۰۹۰ ۔ واثلہ بن اسقع\n(1) ابن کعب بن عامر، بجولیت بن عبد مناۃ سے ہیں۔ بقول بعض: ابن اسقع بن عبد اللہ بن عبد یالیل بن ناشب بن غنیم بن ابن سعد بن لیث، ابن ابی خیثمہ نے صحیح کی ہے کہ وہ واثلہ بن عبد اللہ بن اسقع ہیں۔ وہ اپنے دادا کی طرف منسوب تھے، بعض کا قول ہے: اسقع لقب ہے، ان کا نام عبد اللہ ہے۔\nواقدی کا قول ہے: ان کی کنیت ابو قرصافہ ہے، اور وں کا کہنا ہے: ان کی کنیت ابو اسقع ہے، بعض نے کہا: ابو محمد، بقول بعض: ابو خطاب، بعض کا قول ہے: ابو ھذہ اد ہے۔ بخاری رضی اللہ عنہ(2) کو اس کے بارے میں وہم ہوا ہے۔ تبوک سے پہلے اسلام لائے اور اس میں شریک ہوئے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سیدنا ابو بکر، عمر، ابو ہریرہ، ام سلمہ رضی اللہ عنہ سے روایت کیا، ان سے ان کی بیٹی فلیم، بعض کا قول ہے: حفصہ، ابو ادریس خولانی، شداد ابو عمار، بشر بن عبد اللہ، مکحول، معروف ابو الخطاب اور دوسرے لوگوں نے روایت کیا۔\nابن سعد کا قول ہے: اہل صفہ میں سے ہیں، پھر شام فروکش ہوئے۔\nابو حاتم کا قول ہے: فتح دمشق اور حمص(3) وغیرہ میں شریک ہوئے، ابن سمیع کا قول ہے: خلافت عبد الملک میں وفات پائی، اسماعیل بن عیاش نے بحوالہ سعید بن خالد نقل کیا ہے ۸۳ھ میں وفات پائی اور یہ اضافہ کیا ہے کہ اس وقت ایک سو پینٹھ(۱۲۵) سال کے تھے۔ ابو ہریرہ وغیرہ کا قول ہے: ۸۵ھ میں وفات پائی، واقدی نے ان کی تاریخ وفات بتائی ہے۔ آٹھتر(۸۸) سال کے تھے، وہ دمشق میں وفات پانے والے آخری صحابی تھے۔","",{"fn":"(1) اسد الغابة (۵۴۲۲) استیعاب (۲۷۶۷) تجريد (۱۲۵/۲)\n(2) تاریخ کبیر (۱۸۷/۴)\n(3) المعجم الکبیر (۵۳/۲۲) مختصر تاریخ دمشق (۲۳۲/۲۶)"}],[7713,"§۹۰۹۱ ۔ واثلہ بن خطاب قرشی\n(1) فرماتے ہیں: ابو حسین رازی، تمام کے والد ہیں، صحابی ہیں۔ سیدنا عمر رضی اللہ عنہ کے قبیلے سے ہیں۔ یہ ابن عمار کرنے ان کے حوالے سے بحوالہ اپنے مشیخ شیخوں، ان کی اسانید سے نقل کیا ہے کہ واثلہ کے نام سے مشہور گھر حمام خالد کے صحن میں واثلہ بن خطاب عدوی عدی قریش کا گھر تھا، پھر ان کا ذکر کیا، ابو قاسم بغوی نے ان کا عنوان قائم کیا ہے اور ان کی کوئی حدیث روایت نہیں کی۔\nیحییٰ بن یونس شیرازی اور جعفر مستغفری نے ان کا ذکر کیا ہے، دونوں نے بطریق اسماعیل بن عیاش، بحوالہ واثلہ بن خطاب قرشی ذکر کیا ہے، فرماتے ہیں: ایک شخص مسجد میں داخل ہوا، جب آپ صلی اللہ علیہ وسلم نے اسے دیکھا تو اس کے لیے تھوڑا سا اپنی جگہ سے ہٹ گئے، اس نے کہا: یا رسول اللہ! جگہ کشادہ ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”مسلمان کا مسلمان پر حق ہے کہ جب وہ اسے دیکھے تو اپنی جگہ سے تھوڑا سا ہٹ جائے۔“(2) ابو موسیٰ کا قول ہے: اس کا یہ نام لیا ہے: زفر بن ہبیرہ، عن اسماعیل، عن مجاہد بن روی بن فرقد، اسی طرح ابن قانع نے نقل کیا ہے۔ اسے ابو بکر بن ابو علی نے صحابہ رضی اللہ عنہ میں ذکر کیا ہے اور بطریق قبیح بن مہران، بحوالہ واثلہ بن خطاب ذکر کیا ہے، ابو موسیٰ کا قول ہے: میرے خیال میں انہوں نے لفظی غلطی کی۔\nمیں کہتا ہوں: مشہور صحابی کے والد میں لفظی غلطی ہوئی ہے۔ رہے مجاہد کے والد تو ان کے بارے میں ٹھیک کہا ہے۔ فرماتے ہیں: ھناد بن سری، عن اسماعیل، عن مجاہد بن فرقد، اسے بیہقی نے ادب میں بطریق فریابی نقل کیا ہے کہ ہم سے مجاہد ابو اسود نے بحوالہ واثلہ بن خطاب نقل کیا ہے۔","",{"fn":"(1) اسد الغابة (۵۴۲۷) تجريد (۱۲۵/۲)\n(2) مجمع الزوائد (۳۸/۸) کنز (۲۵۴۰۵) مختصر تاریخ دمشق (۲۴۳/۲۶) جامع المسانید والسنن (۲۴۴/۱۲)"}],[7714,"§۹۰۹۲ ۔ واثلہ بن عبد اللہ\n(1) ابن عمر و لشی، ابو طفیل عامر کے والد ہیں۔ حرف عین میں ان کے بیٹے عامر کے حالات میں ان کا نسب گزر چکا ہے۔ بغوی نے ان کا ذکر کیا ہے اور بطریق عمر بن یوسف ثقفی، بحوالہ ابو ظبیل، عن ابیہ یا جدہ نقل کیا ہے، فرماتے ہیں: میں نے حجر اسود کو سفید دیکھا ہے، اہل جاہلیت جب اپنے اونٹوں کی قربانی کرتے تو اسے گوبر اور خون سے لت پت کر دیتے۔(2)\nابو موسیٰ نے اس حدیث کو نقل کرنے کے بعد فرمایا: یہ عجیب حدیث ہے۔","",{"fn":"(1) اسد الغابة (۵۴۲۴)\n(2) مجمع الزوائد (۳۸/۸) کنز العمال (۲۵۴۰۵) مختصر تاریخ دمشق (۲۴۳/۲۶) جامع المسانید والسنن (۲۴۴/۱۲)"}],[7715,"§۹۰۹۳ ۔ وازع\n(1) ابو نصر بن ماکولا(2) کا قول ہے۔ بعض کا قول ہے: انہیں شرف صحابیت حاصل ہے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کیا، ان سے ان کے بیٹے ذرّح نے روایت کیا، اسی طرح ابن اثیر نے اپنے استدراک میں مختصر ان کا ذکر کیا ہے، خطیب نے مؤتلف میں بطریق ابی نجیح سکونی ان کا ذکر کیا ہے، بحوالہ عمر بن عبد العزیز، انہوں نے ابو وازع درّح بن وازع سے، عن ابیہ نقل کیا ہے، انہیں شرف صحابیت حاصل ہے۔ فرماتے ہیں، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”قرآن پاک کو دیکھنا عبادت ہے۔“(3)\nمیں کہتا ہوں: اس متن کا دوسرا طریق ہے، اسے ابو نعیم نے حدیث عائشہ رضی اللہ عنہ سے نہایت ضعیف سند سے نقل کیا ہے، اس میں مصحف کے بجائے کتاب اللہ کے الفاظ ہیں۔","",{"fn":"(1) اسد الغابة (۵۴۲۵)\n(2) الاکمال (۲۹۷/۷)\n(3) اللآلی المصنوعۃ (۱۷۹/۱)"}],[7716,"§۹۰۹۴ ۔ وازع عبدی\nام ابان کے والد ہیں، ان کے والد وازع کی سوانح میں ان کی حدیث کے بارے میں اختلاف کا بیان گزر چکا ہے۔ احمد، ابن قانع، ابو بکر بن ابو علی اور دوسرے راویوں نے صحابہ میں ان کا ذکر کیا ہے۔"],[7717,"§۹۰۹۵ ۔ وازم بن زرّ کلبی\n(1) یحییٰ بن یونس اور یونس اور مستغفری نے ان کا ذکر کیا ہے، دونوں نے بطریق محمد بن یزید بن زبّان بن وازح بن علی بن وازم بن زرّ کلبی نقل کیا ہے، وازم نبی کریم صلی اللہ علیہ وسلم کے پاس آئے تھے، ابن مندہ نے ان کا نام وودان لیا ہے، جیسا کہ آگے آئے گا۔ ابن ماکولا(2) نے ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابة (۵۴۲۷)\n(2) الاکمال (۷۱/۲)"}],[7718,"§۹۰۹۶ ۔ واسع بن حبّان\n(1) ابن منقذ انصاری۔ عدوی کا قول ہے: بیعت رضوان اور بعد کے واقعات میں شریک ہوئے، حمرہ(2) کے دن قتل ہوئے۔ میں کہتا ہوں: یہ راوی کے علاوہ ہیں جیسا کہ میں گمان کرتا ہوں، کیونکہ وہ تابعین میں مشہور ہیں۔ ان کی حدیث صحیح مسلم میں ہے، ابن فحون نے استیعاب کے ذیل میں ان دونوں کے درمیان فرق کیا ہے۔","",{"fn":"(1) اسد الغابة (۵۴۲۸) تجرید (۱۲۵/۲)\n(2) اسد الغابة (۳۰۲/۴)"}],[7719,"§۹۰۹۷ ۔ واسع سلمی\n(1) بنو سلیم کے وفد میں سے ہیں، عباس بن مرداس نے شعروں میں ان کا ذکر کیا ہے، جو مقنع کی سوانح میں گزر چکے ہیں۔","",{"fn":"(1) تجرید (۱۲۵/۲)"}],[7720,"§۹۰۹۸ ۔ واقد بن حارث\n(1) ابو الحارث، بغوی کا قول ہے، محمد بن اسماعیل نے کہا: انہیں شرف صحابیت حاصل ہے، ابن مندہ کا قول ہے: انصاری ہیں۔ اہل مصر میں ان کا شمار ہوتا ہے۔ ابن مبارک نے زہد میں فرمایا: ہم سے رشید بن سعد نے بحوالہ قیس بن رافع بیان کیا، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم کے اصحاب سیدنا ابن عباس رضی اللہ عنہما کے پاس جمع ہوئے اور خیر و بھلائی کی باتیں کرنے لگے، اس سے ان کے دل نرم پڑ گئے، سیدنا واقد بن حارث خاموش تھے، انہوں نے ان سے کہا: تم بات چیت کیوں نہیں کرتے؟ میری عمر کی قسم! تم ہم سے چھوٹے نہیں ہو؟ انہوں نے کہا: میں باتیں سنتا ہوں، کیونکہ خوفزدہ کے قول کا اعتبار کیا جاتا ہے، میں فعل دیکھتا ہوں کیونکہ مطمئن شخص کے فعل کا اعتبار ہوتا ہے۔(2)","",{"fn":"(1) اسد الغابہ (۲۴۳۰) استیعاب (۲۷۴۲) تجرید (۱۲۵/۲)\n(2) اسد الغابہ (۳۰۳/۴)"}],[7721,"§۹۰۹۹ ۔ واقد بن سہل انصاری اشہلی\nاموی نے مغازي میں، بحوالہ ابو اسحاق یمامہ میں شہید ہونے والوں میں ان کا ذکر کیا ہے۔"],[7722,"§۹۱۰۰ ۔ واقد بن عبد اللہ\n(1) ابن عبد مناف بن عرین بن ثعلبہ بن یربوع بن حنظلہ بن مالک بن زید مناۃ بن تمیم حنظلی، یربوعی، بنو عدی بن کعب کے حلیف ہیں، موسی بن عقبہ نے مغازي میں فرمایا: واقد ہیں، بعض کا قول ہے: وقدان، بدر میں شریک ہوئے، ابن اسحاق(2) نے بدر میں شریک ہونے والوں میں ان کا ذکر کیا ہے، ابن اسحاق نے مغازي میں فرمایا: مجھ سے یزید بن رومان نے بحوالہ عروہ بن زبیر نقل کیا ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے سیدنا عبد اللہ بن جحش کو نخلستان کی طرف بھیجا۔۔۔ پھر قصہ ذکر کیا، اس میں ہے: جب انہیں لوگوں نے دیکھا تو واقد بن عبد اللہ انہیں جھانک کر دیکھنے لگے، ان کا سر منڈا ہوا تھا۔ جب ان لوگوں نے انہیں دیکھا تو کہنے لگا: عمار ہیں، تمہیں ان سے کوئی خطرہ نہیں، رسول اللہ صلی اللہ علیہ وسلم کے اصحاب۔\nلوگ انہیں قتل کرنے کے لیے جمع ہو گئے، واقد بن عبد اللہ بن عمرو بن حضرمی کو نیزہ لگا جس سے وہ شہید ہو گئے، اس پر یہ آیت اتری(3) ﴿تم سے حرمت والے مہینے کے بارے میں پوچھتے ہیں۔۔۔۔﴾ - (الآیۃ)\nابونعیم نے یہ قصہ بطریق ابوسعد بقال، بحوالہ ابن عباس رضی اللہ عنہما طویل نقل کیا ہے۔ اسی طرح طبری نے اسے بطریق اسباط ابن نضر، بحوالہ السدی نقل کیا ہے۔ ابو عبیدہ کا قول ہے: بنو یربوع اس بات پر فخر کرتے تھے ان میں سے حالت اسلام میں پہلے شخص نے مشرکین میں سے ایک آدمی کو مارا۔\nاس کے بارے میں سیدنا عمر بن خطاب رضی اللہ عنہ فرماتے ہیں: شعر\n\"ہم نے ابن حضرمی سے اپنے نیزوں کو سیراب کیا، اس نخلستان میں جس میں واقد نے جنگ چھیڑی تھی۔\"\nعبدالعزیز بن مختار نے بحوالہ سعید بن مسیب فرمایا، فرماتے ہیں: مجھ سے ابن عمیر نے اپنے بیٹے سالم کا نام سالم مولی ابو حذیفہ پر اور اپنے بیٹے واقد کا نام واقد بن عبد اللہ یربوعی پر رکھا۔\nابن ابی حاتم نے بحوالہ اپنے والد فرمایا ہے: یہ خلافت عمر کے آغاز میں وفات پا گئے۔","",{"fn":"(1) اسد الغابہ (۵۴۳۲)\n(2) السیرۃ النبویۃ (۱۸۵/۲) (۲۴۷/۲)\n(3) سورۃ البقرۃ الآیۃ (۲۱۷)"}],[7723,"§۹۱۰۱ ۔ واقد (مولی رسول اللہ صلی اللہ علیہ وسلم)\n(1) حسن بن سفیان نے اپنی مسند میں اور طبرانی(2) نے اپنے معجم میں ان کا ذکر کیا ہے، دونوں نے بطریق زاذان، بحوالہ واقد مولی رسول اللہ صلی اللہ علیہ وسلم نقل کیا: \"جس نے اللہ کی اطاعت کی، اس نے اللہ کا ذکر کیا، اگر چہ اس کی نمازیں اور روزے کم ہوں\"۔ (الحدیث)","",{"fn":"(1) اسد الغابہ (۵۴۳۱) استیعاب (۲۷۴۴)\n(2) المعجم الکبیر (۱۵۴/۲۲)"}],[7724,"§۹۱۰۲ ۔ واقد لیثی\nان کی کنیت ابو مرواح ہے۔ ابن مندہ نے بحوالہ ابو داؤد ان کا ذکر کیا ہے کہ انہیں شرف صحابیت حاصل ہے، بطریق ربیعہ ابن عثمان، بحوالہ واقد ابی مرواح لیثی نقل کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ عز و جل فرماتے ہیں: ہم نے نماز قائم کرنے اور زکوۃ دینے کے لیے مال دیا ہے۔\""],[7725,"§۹۱۰۳ ۔ وائل بن حجر\n(1) ابن ربیعہ بن وائل بن یعمر، بعض نے کہا: ابن حجر بن سعد بن مسروق بن وائل بن نعمان بن ربیعہ بن حارث بن سعد بن عوف بن عدی بن مالک بن شرحبیل بن مالک بن مرہ بن حمیر بن زید حضرمی، ان کے والدین کے بہادر تھے۔ وہ نبی کریم صلی اللہ علیہ وسلم کے پاس وفد میں آئے اور زمین کا ٹکڑا مانگا۔ آپ صلی اللہ علیہ وسلم نے وہ انہیں عطا فرما دیا، اور ان کے ساتھ معاویہ کو بھیجا تا کہ وہ اسے ان کے سپرد کر دیں، ان کا ان کے ساتھ قصہ معروف ہے۔\nابن سعد و یتیمیہ کا قول ہے: کوفہ میں فروکش ہوئے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کیا، ان سے ان کے دونوں بیٹوں علقمہ اور عبدالجبار نے اور ان کی زوجہ ام یحیی نے، ان کے مولی نے اور کلیب بن شہاب، حجر بن عنبس اور دوسرے لوگوں نے روایت کیا، وائل خلافت معاویہ رضی اللہ عنہ میں فوت ہوئے۔\nابو نعیم کا قول ہے: نبی کریم صلی اللہ علیہ وسلم نے انہیں منبر پر کھڑا کیا، انہیں زمین کا ٹکڑا دیا اور انہیں تحریر لکھ کر دی، فرماتے ہیں: یہ وائل بہادروں کے سردار تھے، پھر وائل کوفہ فروکش ہوئے، وہاں ان کی اولاد ہے۔\nابن حبان کا قول ہے: بادشاہوں کی باقی ماندہ اولاد میں سے تھے، جو حضرت موت میں تھی۔ نبی کریم صلی اللہ علیہ وسلم نے وفات سے پہلے انہیں خوشخبری دی، انہیں زمین کا ایک ٹکڑا دیا اور سیدنا معاویہ رضی اللہ عنہ کو ان کے ساتھ بھیجا، انہوں نے ان سے کہا: مجھے اپنے پیچھے بٹھالو، انہوں نے کہا: تم بادشاہوں کے پیچھے بیٹھنے کے قابل نہیں ہو، جب سیدنا معاویہ رضی اللہ عنہ خلیفہ بنے تو وہ ان کے پاس گئے۔ جب ان کی ملاقات ہوئی تو آپ نے ان کا اکرام کیا، وائل کہنے لگے: میں نے چاہا کہ کاش! میں انہیں اپنے آگے سوار کر لیتا۔(2)","",{"fn":"(1) اسد الغابہ (۵۴۳۶) استیعاب (۲۷۶۵)\n(2) المعجم الکبیر (۹/۲۲) مختصر تاریخ دمشق (۲۵۳/۲۶) جامع المسانید والسنن (۳۵۰/۱۲)"}],[7726,"§۹۱۰۴ ۔ وائل بن افلح\nبعض کا قول ہے: وہ ابو القعیس کا لقب ہے۔ ابن خزیمہ نے اپنی صحیح میں اور ابن مندہ نے اپنے طریق سے پھر بروایت یحیی ابن ابی کثیر، بحوالہ عکرمہ نقل کیا ہے کہ ابو القعیس وائل بن افلح نے سیدہ عائشہ رضی اللہ عنہا کے پاس آنے کی اجازت مانگی۔۔۔۔ (الحدیث) ابن مندہ نے اسی طرح بروایت ابی حریز، بحوالہ الحکم بن عیینہ نقل کیا ہے کہ عراک بن مالک نے ان سے بیان کیا ہے کہ افلح سیدہ عائشہ رضی اللہ عنہا کے پاس آئے، انہوں نے ان سے پردہ کیا، وائل بن ابو القعیس کی زوجہ نے سیدہ عائشہ رضی اللہ عنہا کو دودھ پلایا تھا، ابن مندہ کا قول ہے: اسے شعبہ وغیرہ نے بحوالہ عائشہ رضی اللہ عنہا نقل کیا ہے کہ افلح ابو القعیس نے سیدہ عائشہ رضی اللہ عنہا کے پاس آنے کی اجازت طلب کی۔۔۔۔ (الحدیث) فرماتے ہیں: یہی صحیح ہے۔\nمیں کہتا ہوں: شعبہ وغیرہ کی روایت سے جو صحیح ثابت ہے کہ افلح ابو القعیس کے بھائی ہیں، لہذا ابو القعیس کا نام اگر وائل ہے تو یہ عنوان سوانح میں ہے۔"],[7727,"§۹۱۰۵ ۔ وائل بن رناب\nابن حذیفہ بن ہشم بن سعید بن سہم قرشی سہمی۔ انہیں اور ان کے دونوں بھائیوں معمر اور حبیب کو شرف صحابیت حاصل ہے۔ جن لوگوں نے صحابہ رضی اللہ عنہم کے بارے میں کتابیں لکھی ہیں انہوں نے ان کا ذکر نہیں کیا۔ ایک قوی روایت سے ان کا ذکر ثابت ہے جسے فاکہی، یعقوب بن شیبہ، دارقطنی وغیرہ نے بطریق حسین معلم، بحوالہ عمرو بن شعیب، عن ابیہ، عن جدہ نقل کیا ہے۔ فرماتے ہیں: رکاب بن حذیفہ سہمی نے اُم وائل بنت معمر بن حبیب بن وہب بن حذیفہ بن حج سے نکاح کیا، جس سے تین بیٹے ہوئے: وائل، معمر اور حبیب۔ ان کی والدہ وفات پا گئیں۔ ان کے بیٹے ان کے مکانات، اور ان کے موالی کے وارث ہوئے۔ سیدنا عمرو بن العاص رضی اللہ عنہ تینوں کو شام لے گئے، وہاں وہ تینوں طاعون عمواس میں فوت ہو گئے، پھر سیدنا عمرو بن العاص ان کے وارث ہوئے، وہ ان کے عصبہ رشتہ دار تھے۔ فرماتے ہیں: جب وہ واپس آئے تو بنو معمر اور بنو حبیب آ کر ان سے جھگڑا کرنے لگے کہ انہیں ان کے موالی کی ولاء واپس کی جائے۔ سیدنا عمر رضی اللہ عنہ نے فرمایا: جو کچھ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا اس کے مطابق میں تمہارے درمیان فیصلہ کر کے رہوں گا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"بچے کا جو کچھ مال ہے وہ اس کے عصبہ کے لیے ہے جو بھی ہو\"۔(1) فرماتے ہیں: اس کے مطابق سیدنا عمر رضی اللہ عنہ نے ہمارے درمیان فیصلہ کیا اور ہمارے لیے اس کے بارے میں تحریر لکھ دی جس میں سیدنا عبدالرحمن بن عوف، زید ابن ثابت رضی اللہ عنہما اور دوسرے صحابہ کی گواہی تھی۔ فرماتے ہیں: ہم اس پر عمل کرتے تھے یہاں تک کہ عبدالملک بن مروان خلیفہ بنے اور ہمارا ایک مولی فوت ہو گیا اور ایک ہزار دینار چھوڑ گیا۔ انہوں نے ہمارا جھگڑا ہشام بن اسماعیل کے سامنے پیش کیا، ہم عبدالملک کے پاس یہ معاملہ لے کر گئے، میں ان کے پاس سیدنا عمر رضی اللہ عنہ کی تحریر لے کر آیا، میں نہیں سمجھتا کہ اہل مدینہ یہ جرات کر سکتے ہیں کہ اس فیصلے میں شک ہے۔\nیعقوب بن ابی شیبہ کی روایت میں ان کا نام موجود نہیں۔ اسی طرح ابوداؤد نے بطریق حسین معلم اسے نقل کیا ہے اور ان کا نام نہیں لیا۔ ان کے ہاں اس کے آخر میں ہے، عبدالملک کا قول ہے: میں بھی یہی فیصلہ درست سمجھتا تھا اور بعد والی بات ذکر نہیں کی، درست اس کا اثبات ہے، اس کی تقدیر یوں ہے: میں نہیں سمجھتا کہ یہ فیصلہ بھلایا جائے۔","",{"fn":"(1) ابوداؤد (۲۹۱۷) ابن ماجہ (۲۷۳۲)"}],[7728,"§۹۱۰۶ ۔ وبر بن مشہر حنفی\n(1) بخاری،(2) ابن سکن اور ابن حبان کا قول ہے: انہیں شرف صحابیت حاصل ہے، انہوں نے اور ابن ابی عاصم،(3) ابن سکن اور طبرانی(4) نے بطریق حاجب بن قدامہ، بحوالہ وبر بن مشہر حنفی نقل کیا ہے کہ انہوں نے انہیں بتایا کہ مسیلمہ نے انہیں ابن نواحہ اور ابن اثال حنفی کو بھیجا، یہاں تک کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے، وبر کا قول ہے: وہ دونوں مجھ سے عمر میں بڑے تھے، ان دونوں نے گواہی دی پھر رسول اللہ صلی اللہ علیہ وسلم کے لیے گواہی دی کہ وہ اللہ کے رسول ہیں۔ اور مسیلمہ ان کے بعد رسول ہے، فرماتے ہیں: پھر میری طرف متوجہ ہو کر پوچھا: اے لڑکے! تم کس چیز کی گواہی دیتے ہو؟ انہوں نے کہا: میں اس چیز کی گواہی دیتا ہوں جس کی آپ گواہی دیتے ہیں، اور اس چیز کو جھٹلاتا ہوں جس کو آپ جھوٹا قرار دیتے ہیں۔ فرمایا: میں مٹی کے ذروں کے برابر گواہی دیتا ہوں کہ مسیلمہ جھوٹا ہے، وبر نے کہا: جس کی آپ نے گواہی دی، میں اس کی گواہی دیتا ہوں۔ آپ صلی اللہ علیہ وسلم نے ان دونوں کے بارے میں حکم دیا تو انہیں نکال دیا گیا۔ وبر بن مشہر رسول اللہ صلی اللہ علیہ وسلم کے پاس رہ کر قرآن سیکھتے تھے یہاں تک کہ آپ صلی اللہ علیہ وسلم کی وفات ہو گئی ان کے دونوں ساتھی واپس چلے گئے۔","",{"fn":"(1) اسد الغابہ (۵۴۳۹) استیعاب (۲۷۴۶) تجرید (۱۲۶/۲)\n(2) التاریخ الکبیر (۱۸۳/۴)\n(3) الاحاد والمثانی (۱۶۸۵)\n(4) المعجم الکبیر (۱۵۳/۲۲)"}],[7729,"§۹۱۰۷ ۔ وبر بن یحنس کلبی\n(1) ابن حبان کا قول ہے، بعض نے کہا: انہیں شرف صحابیت حاصل ہے، واقدی کا قول ہے: ۱۰ھ میں وبر بن یحنس نبی کریم صلی اللہ علیہ وسلم کے پاس سے عجم میں مقیم عربوں کے پاس آئے، وہ نعمان بن بزرج کی بیٹیوں کے پاس فروکش ہوئے وہ اسلام لے آئیں اور فیروز دیلمی کی طرف پیغام بھیجا، وہ اسلام لے آئے اور مرکبوط کے پاس پیغام بھیجا وہ بھی اسلام لے آئے، ان کے بیٹے عطاء پہلے شخص تھے جنہوں نے یمن میں قرآن جمع کیا تھا۔ ابن فتحون کا قول ہے: واقدی رحمہ اللہ نے اہل سباء میں سے اسلام لانے والوں میں ان کا ذکر کیا ہے، ابن سکن اور ابن مندہ نے بطریق عبدالملک بن عبدالرحمن ذماری، بحوالہ نعمان بن بزرج نقل کیا ہے کہ وبر بن یحنس فرماتے ہیں: مجھ سے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم صنعاء آؤ تو اس کی اس مسجد میں آؤ جو صنعاء کے پہاڑ جیال انقبیل میں ہے اور اس میں نماز پڑھو\"۔ ابن سکن نے اپنی روایت میں اضافہ کیا ہے، جب اسود کذاب کو قتل کیا گیا، وبر فرماتے ہیں: یہ وہی جگہ ہے جس کے بارے میں رسول اللہ صلی اللہ علیہ وسلم نے مجھے حکم دیا کہ اس میں مسجد بناؤں۔ ابن مندہ کا قول ہے: ذماری اس حدیث کی روایت میں تنہا ہیں۔","",{"fn":"(1) اسد الغابہ (۵۴۴۰) استیعاب (۲۷۴۵) تجرید (۱۲۶/۲)"}],[7730,"§۹۱۰۸ ۔ وبرہ بن سنان جہنی\nابوالعباس ضریر نے مقامات التنزیل میں ان کا ذکر کیا ہے، بعض کا قول ہے: یہ وہی ہیں جنہوں نے سیدنا عمر بن خطاب رضی اللہ عنہ کے مزدور جعال غفاری سے حوض کے بارے میں جھگڑا کیا، ان دونوں کے بارے میں یہ آیت نازل ہوئی: ﴿اے لوگو! ہم نے تمہیں مرد اور عورت سے پیدا کیا ہے۔﴾(1) - (الآیۃ)","",{"fn":"(1) سورۃ الحجرات الآیۃ (۴۳)"}],[7731,"§۹۱۰۹ ۔ وبرہ بن قیس خزرجی\nرشاطی نے انساب میں اشعثی کی سوانح میں ذکر کیا ہے کہ جب اشعث بن قیس، سیدنا ابوبکر رضی اللہ عنہ کے پاس سے باہر تشریف لائے، جبکہ سیدنا ابوبکر رضی اللہ عنہ نے اپنی بہن کا نکاح ان سے کر دیا تھا، تو انہوں نے اپنی تلوار سونت لی اور بازار میں جو اونٹ، گھوڑا، خچر، بکری، اور بیل نظر آیا اس کے گھر کاٹ ڈالے۔ سیدنا ابوبکر رضی اللہ عنہ سے کہا گیا: وہ مرتد ہو گئے ہیں، انہوں نے کہا: دیکھو! وہ کہاں ہیں؟ تو وہ انصار کے ایک بالا خانے میں تھے، لوگ ان کے پاس جمع تھے۔ اور وہ کہہ رہے تھے، یہ میرا ولیمہ ہے، اگر میں اپنے ملک میں ہوتا تو ایسا ولیمہ کرتا کہ میری طرح کسی نے نہ کیا ہوتا، جس کو جو چیز ملے، اسے لے لو، کل تمہیں اس کی قیمت مل جائے گی۔ مدینہ کے گھروں میں سے کوئی گھر ایسا نہ رہا جس میں گوشت نہ گیا ہو، ایسا لگ رہا تھا کہ وہ عید الاضحی کا دن ہے۔\nاس کے بارے میں وبرہ بن قیس خزرجی فرماتے ہیں: شعر\n\"کندی نے اپنی طاقت کے دن وزن اٹھانے والے کے بوجھ کی وجہ سے ولیمہ کر دیا، جو تلوار نیام میں تھی۔ اس نے اسے سونت لیا، جو جنگوں میں کھوپڑیوں کے وقت نکالی جاتی تھی، پھر اس نے وہ تلوار ہر اونٹ، بیل، گدھے، خچر میں، اس کی انتڑیوں اور پاؤں میں گھسیڑ دی، تو بکری نوجوان سے کہہ دینا جب تو اس سے ملے کہ اولاد آدم کی بلند بزرگی کو تو لے اڑا\"۔\nمیں کہتا ہوں: ان اشعار کے علاوہ یہ قصہ مشہور ہے، اس کے ظاہر سے پتہ چلتا ہے کہ اس کے کہنے والا وہ شخص ہے جس کے سامنے قصہ پیش آیا، لہذا وہ صحابی ہیں، کیونکہ وہ انصار میں سے خزرجی ہیں۔ انصار میں سے جس نے بھی حالت اسلام میں نبی کریم صلی اللہ علیہ وسلم کا زمانہ پایا وہ صحابی ہے۔"],[7732,"§۹۱۱۰ ۔ وبرہ بن یحنس خزاعی\n(1) ابو عمر(2) نے ان کا ذکر کیا ہے۔ فرماتے ہیں: وہ رسول اللہ صلی اللہ علیہ وسلم کے ان لوگوں کی طرف قاصد تھے جنہوں نے اسود عنسی کو قتل کیا تھا، وہ یحنس بن وبرہ سبائی کے علاوہ ہیں۔ قسم اول میں جن کا ذکر گزر چکا ہے، سیف نے فتوح میں فرمایا: ہم سے ضحاک بن یربوع نے بحوالہ ابن عباس رضی اللہ عنہما نقل کیا ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے اسود، مسیلمہ، طلیحہ اور اس طرح کے لوگوں کے ساتھ جہاد کے لیے قاصدوں کو بھیجا۔ وبرہ بن یحنس کو فیروز کی طرف اور یحنس کو دیلمیوں کی طرف بھیجا۔","",{"fn":"(1) استیعاب (۲۷۴۴)\n(2) استیعاب (۱۱۲/۴)"}],[7733,"§۹۱۱۱ ۔ وحذ بن غالب\n(1) ابن عمرو، ابو قبیلہ، نبی کریم صلی اللہ علیہ وسلم کے پاس وفد میں آئے، یہ ابن کلبی(2) کا قول ہے، ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۴۴۱)\n(2) اسد الغابہ (۳۰۷/۴)"}],[7734,"§۹۱۱۲ ۔ وحشی بن حرب حبشی\n(1) مولی بنو نوفل، بعض کا قول ہے: مولی طعیمہ بن عدی ہیں، بقول بعض: ان کا بھائی مطعم کا مولی ہے، وہ سیدنا حمزہ رضی اللہ عنہ(2) کے قاتل ہیں، انہیں غزوہ احد میں شہید کیا۔ بخاری(3) نے اپنی صحیح میں ان کی شہادت کا طویل قصہ نقل کیا ہے۔ اس میں ان کے اسلام لانے کا واقعہ ہے۔ نبی کریم صلی اللہ علیہ وسلم نے انہیں حکم دیا کہ آپ صلی اللہ علیہ وسلم کے سامنے نہ آئیں۔ وہ آپ صلی اللہ علیہ وسلم کے پاس اہل طائف کے وفد کے ساتھ آئے تھے، اس کے آخر میں ذکر کیا کہ وہ مسیلمہ کے قتل میں شریک تھے، ان کی کنیت ابو سلمہ ہے، بعض کا قول ہے: ابو حرب ہے۔ سیدنا وحشی یرموک میں شریک ہوئے، پھر حمص میں رہے، وہیں وفات پا گئے۔ ان سے ان کے بیٹے حرب، عبداللہ بن عدی بن خیار، جعفر بن عمرو ضمری نے روایت کیا، سیدنا وحشی، سیدنا عثمان رضی اللہ عنہ کی خلافت تک زندہ رہے۔","",{"fn":"(1) اسد الغابہ (۵۴۴۲) تجرید (۱۲۷/۲)\n(2) المعجم الکبیر (۱۳۹/۲۲) مجمع الزوائد (۱۲۲/۶)\n(3) بخاری (۴۰۷۲)"}],[7735,"§۹۱۱۳ ۔ وحوح بن اسلت\n(1) وہ عامر بن بشم بن وائل بن زید بن قیس بن عامر بن مرہ بن مالک انصاری ہیں، ابو قیس کے بھائی ہیں، عبداللہ بن محمد بن محمد بن عمارہ کا قول ہے: انہیں شرف صحابیت حاصل ہے۔ غزوہ خندق اور بعد کے غزوات میں شریک ہوئے۔","",{"fn":"(1) اسد الغابہ (۵۴۴۳) تجرید (۱۲۷/۲)"}],[7736,"§۹۱۱۴ ۔ وحوح بن ثابت انصاری\nخزیمہ ذی الشہادتین کے بھائی ہیں، طبری نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔"],[7737,"§۹۱۱۵ ۔ وداعہ بن حرام انصاری\nمستغفری نے ان کا ذکر کیا ہے اور بطریق ابن کلبی، بحوالہ ابن عباس رضی اللہ عنہما ان لوگوں میں ان کا ذکر کیا ہے جو تبوک سے رہ گئے تھے۔ انہوں نے اور ابو لبابہ نے اپنے آپ کو مسجد کے ستون سے باندھ دیا تھا۔"],[7738,"§۹۱۱۶ ۔ وداعہ بن ابی زید انصاری\n(1) ابن کلبی نے انصار میں سے سیدنا علی رضی اللہ عنہ کے ساتھ صفین میں شریک ہونے والوں میں ان کا ذکر کیا ہے، فرماتے ہیں: ان کے والد احد کے دن قتل ہوئے۔","",{"fn":"(1) استیعاب (۲۷۷۰)"}],[7739,"§۹۱۱۷ ۔ وداعہ بن ابی وداعہ سہمی\nابن کلبی نے بھی ان کا ذکر کیا ہے، ابن مندہ نے بطریق ابن کلبی، بحوالہ وداعہ سہمی نقل کیا ہے، فرماتے ہیں: گرمیوں میں ایک دن رسول اللہ صلی اللہ علیہ وسلم مکہ آئے، بیت اللہ کا طواف کیا، پھر فرمایا: \"کیا پینے کی کوئی شے ہے۔۔۔\"۔ (الحدیث)"],[7740,"§۹۱۱۸ ۔ ودان بن زر کلبی\nوازم میں ان کا ذکر گزر چکا ہے۔"],[7741,"§۹۱۱۹ ۔ ودقعہ بن ایاس\n(1) ابن عمرو انصاری، بنو لوذان بن غنم سے ہیں، ابن اسحاق(2) نے بدر میں شریک ہونے والوں میں ان کا ذکر کیا ہے، اس کے لکھنے میں اختلاف ہے، بعض نے کہا: فاء کے ساتھ ہے، ایک قول ہے: قاف کے ساتھ ہے، اکثر کا قول ہے کہ وہ دال کے ساتھ ہے، ابن ہشام نے راہ کے ساتھ نقل کیا ہے۔ اسی طرح موسی بن عقبہ کی کتاب کے بعض نسخوں میں ہے۔","",{"fn":"(1) استیعاب (۲۷۷۱) تجرید (۱۲۷/۲)\n(2) السیرۃ النبویۃ (۲۵۵/۲)"}],[7742,"§۹۱۲۰ ۔ ودیعہ بن خذام\n(1) خذام بن ودیعہ میں گزر چکے ہیں، بخاری رحمہ اللہ نے اپنی تاریخ میں لکھا ہے کہ ہم سے عبید بن یعیش نے، بحوالہ عبداللہ بن ودیعہ بن خذام نقل کیا ہے، وہ سیدنا عمر بن خطاب رضی اللہ عنہ کے پاس سالم مولی ابو حذیفہ کی میراث لے کر آئے۔ آپ نے ودیعہ کو بلایا، آپ نے فرمایا: تم سالم کی ولاء کے زیادہ حق دار ہو۔ انہوں نے کہا: ہماری رشتہ دار نے اسے اللہ کی رضا کے لیے آزاد کیا تھا، ہمیں نہیں چاہیے۔ سیدنا عمر رضی اللہ عنہ نے اسے بیت المال میں شامل کر لیا۔","",{"fn":"(1) اسد الغابہ (۵۴۴۴) تجرید (۱۲۷/۲)"}],[7743,"§۹۱۲۱ ۔ ودیعہ بن عمرو\n(1) ابن یاسر ابن عوفی بن جراد بن یربوع بن طفیل بن عدی بن ربعہ بن رشدان بن قیس بن جمیہ جمحی، بنو سواد بن مالک بن غنم کے حلیف ہیں، موسی بن عقبہ اور ابن اسحاق(2) نے بدر میں شریک ہونے والوں میں ان کا ذکر کیا ہے۔ ابن کلبی رحمہ اللہ نے فرمایا: بدر میں شریک ہوئے، بنو نجار کے حلیف ہیں۔","",{"fn":"(1) اسد الغابہ (۵۴۵۰)\n(2) السیرۃ النبویۃ (۱۵۲/۳)"}],[7744,"§۹۱۲۲ ۔ ودیعہ بن عمرو\n(1) ابن حبان نے کہا: بعض نے کہا: انہیں شرف صحابیت حاصل ہے، احتمال ہے کہ وہ پہلے والے ہوں، بظاہر وہ کوئی اور ہیں۔","",{"fn":"(1) تجرید (۱۲۷/۲)"}],[7745,"§۹۱۲۳ ۔ ورد بن خالد\nابن حذیفہ بن عمرو بن خلف بن مازن بن مالک بن ثعلبہ بن محمد بن سلیم سلمی بجلی۔ فتح مکہ کے دن نبی کریم صلی اللہ علیہ وسلم کے لشکر میں بائیں دستے پر امیر مقرر تھے، ابو عمر نے ان کا ذکر کیا ہے۔"],[7746,"§۹۱۲۴ ۔ ورد بن عمرو\nابن مرداس، بنو سعد بن حدیم میں سے ہیں، طبری نے ذکر کیا ہے کہ وہ سیدنا زید بن حارثہ کے ساتھ وادی قری کی طرف کسی سریہ میں شہید ہوئے۔"],[7747,"§۹۱۲۵ ۔ ورد بن قتادہ\nبنو اداس بن عبداللہ بن ذبیان بن حارث بن سعد حدیم سے ہیں، ابن کلبی کا قول ہے: یہ وہی ہیں جنہوں نے ام قرفہ فزاریہ کو دو گھوڑوں کے درمیان باندھ کر دو ٹکڑے کر دیا تھا، یہ زید بن حارثہ کے حکم پر تھا، جب انہوں نے بنو فزارہ سے جہاد کیا اور ام قرفہ کو قیدی بنا لیا، ابن کلبی کا قول ہے: رسول اللہ صلی اللہ علیہ وسلم نے بنو فزارہ کی طرف وادی قری کے کسی حصے میں شاخ پر خط لکھا، انہوں نے ٹہنی کا پھول لے لیا، رسول اللہ صلی اللہ علیہ وسلم کو یہ بات معلوم ہوئی تو فرمایا: \"بے آب و گیاہ وادی اور شیروں کو چھوڑ دو\"۔ اور فزاری کو اس کے عوض عطاء کیا، یہ قصہ حرف سین میں سمعان کی سوانح میں گزر چکا ہے، اس کے بعد وہ اسلام لے آئے اور سیدنا زید بن حارثہ کے ساتھ جہاد کیا اور شہید ہوئے۔\nمیں کہتا ہوں: احتمال ہے کہ وہ بعد والے ہوں۔"],[7748,"§۹۱۲۶ ۔ ورد بن مداس عذری\nمدائنی نے ان کا ذکر کیا ہے، جیسا کہ سمعان کی سوانح میں گزر چکا ہے، پھر مجھے معلوم ہوا کہ وہ پہلے والے ہیں، اپنے دادا کی طرف منسوب ہیں۔ اموی نے مغازی میں، بحوالہ ابن اسحاق(1) ذکر کیا ہے کہ وہ سیدنا زید بن حارثہ کے ساتھ شہید ہوئے۔","",{"fn":"(1) السیرۃ النبویۃ (۲۶۱/۴)"}],[7749,"§۹۱۲۷ ۔ وردان بن محرم عنبری\n(1) ان کے بھائی حیدہ اور ربیعہ بن رفیع میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) تجرید (۱۲۸/۲)"}],[7750,"§۹۱۲۸ ۔ وردان بن محرم تمیمی عنبری\n(1) ابن شاہین نے ان کا ذکر کیا ہے اور بطریق ابو حسن مدائنی، کئی راویوں سے متعدد اسناد سے نقل کیا ہے، فرماتے ہیں: جب عیینہ بن حصن نے بنو عنبر پر حملہ کیا تو ان کا وفد آیا وہ چلا رہے تھے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یہ چیخ و پکار کیا ہے؟\" کہا گیا: بنو عنبر کا وفد ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"انہیں چاہیے کہ آرام سے بیٹھیں\"۔ یہ بات ان سے کہی گئی تو انہوں نے کہا: ہم اپنے سردار وردان بن محرم کا انتظار کر رہے ہیں، وہ لوگ جلدی میں تھے اور اپنی سواریوں کے پاس جمع تھے، رسول اللہ صلی اللہ علیہ وسلم سے کہا گیا: وردان نے کبھی جھوٹ نہیں بولا، یہ وہی شخص ہے جس کا وہ انتظار کر رہے ہیں، جب وہ آیا تو آپ صلی اللہ علیہ وسلم نے اس سے فرمایا: \"تم اپنی قوم کے سردار ہو، مجھے ان کے بارے میں بتاؤ،\" اس نے کہا: یہ مسلمان ہو کر آنے والے نہیں ہیں نہ ہی پیٹھ پھیرنے والے مشرک ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"انہیں میرے لیے علیحدہ کر دو\"۔ فرماتے ہیں: وہ جوانوں کو ایک طرف کرنے لگے، رسول اللہ صلی اللہ علیہ وسلم مسکرائے پھر فرمایا: اے بنو تمیم! ہر ایک کا حق اور رشتہ داری ہے۔ میں ایک تہائی تمہیں دے دوں گا، ایک تہائی آزاد کر دوں گا اور ایک تہائی لے لوں گا\"۔ اس پر عیینہ اور اقرع میں جھگڑا ہو گیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو چار سو(۴۰۰) ادا کرے وہ چلا جائے\"۔","",{"fn":"(1) اسد الغابہ (۵۴۵۶) استیعاب (۲۷۷۴) تجرید (۱۲۸/۲)"}],[7751,"§۹۱۲۹ ۔ وردان (مولی رسول اللہ صلی اللہ علیہ وسلم)\n(1) ابو نعیم نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور بطریق حسن بن عمارہ، بحوالہ ابن ابن، ان کا ذکر کیا ہے۔ فرمایا: مولی رسول اللہ صلی اللہ علیہ وسلم وردان تنے سے گر پڑا اور مر گیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اس کی سرزمین کا کوئی آدمی ڈھونڈو اور اسے اس کی میراث دو۔ لوگوں کو ایک آدمی مل گیا، انہوں نے وہ اسے دے دی۔ ابو موسی نے ذیل میں ان کا ذکر کیا ہے، فرماتے ہیں: وہ ابو عیسی ترمذی کی کتاب میں، بحوالہ مجاہد بن وردان مروی ہے۔\nمیں کہتا ہوں: یہ روایت ان کے پاس ہے، اور باقی اصحاب سنن کے پاس۔ حدیث سفیان ثوری، بحوالہ عائشہ رضی اللہ عنہا مروی ہے۔ لیکن انہوں نے مذکورہ مولی کا نام نہیں لیا۔","",{"fn":"(1) اسد الغابہ (۵۴۵۴)"}],[7752,"§۹۱۳۰ ۔ وردان\n(1) فرات بن یزید بن وردان کے دادا ہیں، ابن اسحاق نے طائف سے نبی کریم صلی اللہ علیہ وسلم کے پاس آنے والوں میں ان کا ذکر کیا ہے۔ اسی طرح واقدی نے ان کا ذکر کیا ہے۔ نبی کریم صلی اللہ علیہ وسلم نے انہیں ابان بن سعید کے سپرد کر دیا تاکہ وہ ان کی دیکھ بھال کریں، اور انہیں قرآن سکھائیں۔ ابو سعید نیشاپوری کا قول ہے: نبی کریم صلی اللہ علیہ وسلم نے انہیں طائف سے قیدی بنایا پھر انہیں آزاد کر دیا۔","",{"fn":"(1) اسد الغابہ (۵۴۵۵)"}],[7753,"§۹۱۳۱ ۔ وردان جنی\n(1) ابن مردویہ نے تفسیر سورہ جن میں بطریق مستمر بن ریان، بحوالہ ابن مسعود ان کا ذکر کیا ہے، فرماتے ہیں: میں نبی کریم صلی اللہ علیہ وسلم کے پاس لیلۃ الجن میں گیا، یہاں تک کہ جنوں میں آئے، نبی کریم صلی اللہ علیہ وسلم نے میرے گرد ایک لکیر کھینچی، پھر ان کی طرف تشریف لے گئے۔ انہوں نے آپ صلی اللہ علیہ وسلم کے پاس ہجوم کیا۔ ان کے سردار جسے وردان کہا جاتا تھا اس نے نبی کریم صلی اللہ علیہ وسلم سے کہا: یا رسول اللہ! کیا میں ان کو آپ کے پاس سے لے نہ جاؤں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ کے سوا مجھے کوئی ہرگز پناہ نہیں دے سکتا\"۔(2)","",{"fn":"(1) اسد الغابہ (۵۴۵۳)\n(2) اسد الغابہ (۳۱۱/۴)"}],[7754,"§۹۱۳۲ ۔ ورقہ بن ایاس\nودقہ میں ان کا ذکر گزر چکا ہے۔"],[7755,"§۹۱۳۳ ۔ ورقہ بن حابس تمیمی\nاقرع کے بھائی ہیں، حاکم نے نیشاپور سے آنے والے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ فرماتے ہیں: ان میں اقرع بن حابس، ورقہ بن حابس دونوں تمیمی ہیں، پھر بطریق عباس بن مصعب نقل کیا ہے، فرماتے ہیں: مرو سے آنے والے صحابہ رضی اللہ عنہم میں سے اقرع اور ورقہ ہیں، اور وردان احنف کے ساتھ آئے۔ احمد بن سنان نے، بحوالہ مدائنی فرمایا: اقرع اور ان کے بھائی ان لوگوں میں سے ہیں جن کی تالیف قلب کی گئی۔"],[7756,"§۹۱۳۴ ۔ ورقہ بن نوفل\n(1) ابن اسد بن عبدالعزی بن قصی قرشی اسدی، نبی کریم صلی اللہ علیہ وسلم کی زوجہ سیدہ خدیجہ رضی اللہ عنہا کے چچازاد ہیں۔ طبری، بغوی، ابن قانع اور ابن سکن وغیرہ نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ سب نے بطریق روح بن مسافر جو ایک ضعیف راوی ہے، بحوالہ ورقہ ابن نوفل نقل کیا ہے، فرماتے ہیں: میں نے کہا: اے محمد! جو تمہارے پاس آتا ہے وہ کیسے آتا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"میرے پاس آسمان سے جو آتا ہے، اس کے دونوں پر لولو کے ہیں، اس کے قدموں کا اندرونی حصہ سبز ہے۔\"(2) ابن عساکر(3) کا قول ہے: ابن عباس رضی اللہ عنہما نے ورقہ سے نہیں سنا، اور مجھے معلوم نہیں کہ کسی نے یہ کہا ہو کہ وہ اسلام لے آئے۔\nطبری نے اس حدیث کے راوی اور ورقہ بن نوفل اسدی میں فرق کیا ہے۔ لیکن یہ قصہ اس قصے سے مختلف ہے، جو صحیحین میں بطریق عائشہ رضی اللہ عنہا مروی ہے، رسول اللہ صلی اللہ علیہ وسلم پر وحی کی ابتداء سے پہلے۔۔۔۔ یہ حدیث حضرت جبرائیل علیہ السلام کے غار حرا میں آنے کے بارے میں ہے۔ اس میں ہے: سیدہ خدیجہ رضی اللہ عنہا آپ صلی اللہ علیہ وسلم کو لے کر ورقہ بن نوفل بن اسد بن عبدالعزی کے پاس لے گئیں جو سیدہ خدیجہ رضی اللہ عنہا کے چچازاد تھے اور جاہلیت میں عیسائی ہو گئے تھے۔۔۔۔ (الحدیث)\nاس میں ہے، ورقہ نے کہا: یہ وہی ناموس ہے جو حضرت موسی علیہ السلام پر اترا، اے کاش! میرے اندر طاقت ہوتی، اے کاش! میں اس وقت زندہ ہوتا جب آپ کی قوم آپ کو نکال دے گی، اس کے آخر میں ہے: ورقہ تھوڑے ہی عرصے میں وفات پا گئے۔ اس سے ظاہر ہوتا ہے کہ انہوں نے نبوت کا اقرار کیا تھا، لیکن وہ رسول اللہ صلی اللہ علیہ وسلم کے لوگوں کو اسلام کی طرف بلانے سے پہلے وفات پا گئے، ان کی مثال بحیرا کی ہوگی۔ ان کے صحابی ہونے میں تردد ہے، لیکن زیادات مغازی میں بروایت یونس بن بکیر، بحوالہ میسرہ مروی ہے، ان کا نام عمرو بن شرحبیل ہے، وہ اکابر تابعین میں سے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سیدہ خدیجہ رضی اللہ عنہا سے فرمایا: \"جب میں تنہا ہوتا ہوں تو پکارنے کی آواز سنتا ہوں، اللہ کی قسم! مجھے اپنی جان کا خوف ہے۔ انہوں نے کہا: اللہ کی پناہ! اللہ تعالی آپ کے ساتھ ایسا نہیں کرے گا، اللہ کی قسم! آپ امانتیں ادا کرتے ہیں۔۔۔۔ (الحدیث) ان سے ورقہ نے کہا: خوشخبری ہو، پھر خوشخبری ہو، میں گواہی دیتا ہوں کہ آپ وہی ہیں جس کی حضرت ابن مریم علیہ السلام نے خوشخبری دی، آپ کے پاس حضرت موسی علیہ السلام کی طرح ناموس آتا ہے، آپ نبی مرسل ہیں۔ اس دن کے بعد عنقریب آپ کو جہاد کا حکم دیا جائے گا، اگر میں نے وہ وقت پایا تو آپ کے ساتھ ضرور جہاد کروں گا، جب وہ وفات پا گئے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میں نے جنت میں قس کو دیکھا ان پر ریشم کے کپڑے تھے، کیونکہ وہ مجھ پر ایمان لائے اور میری تصدیق کی\"۔\nبیہقی نے اسے دلائل(4) میں اس طریق سے نقل کیا ہے، فرماتے ہیں: یہ روایت منقطع ہے۔\nمیں کہتا ہوں: جو کچھ زبیر بن بکار نے ذکر کیا اس سے اس کی تائید ہوتی ہے کہ ہم سے عثمان نے، بحوالہ عروہ بن زبیر نقل کیا ہے، فرماتے ہیں: سیدنا بلال رضی اللہ عنہ بنو جمح کی عورت کے غلام تھے، وہ انہیں مکہ میں تپتی ریت پر تکلیفیں دیتے تھے۔ ان کی پیٹھ کو تپتی ریت پر لگا دیتے تاکہ وہ شرک کریں وہ احد، احد کہتے تھے۔ ان کے پاس ورقہ گزرے وہ اسی حالت میں تھے، انہوں نے کہا: اے بلال! احد، احد کہو۔ اللہ کی قسم! اگر تم لوگ اسے قتل کر دو گے تو میں اسے یاد کرتا رہوں گا۔ یہ مرسل جید ہے، اس سے پتہ چلتا ہے کہ ورقہ اس وقت تک زندہ رہے جب رسول اللہ صلی اللہ علیہ وسلم نے لوگوں کو اسلام کی طرف بلایا یہاں تک کہ بلال اسلام لے آئے، اس حدیث اور حدیث عائشہ رضی اللہ عنہا کو اس طرح جمع کیا جا سکتا ہے کہ ان کے قول کو ورقہ جلد ہی وفات پا گئے، اس میں یہ احتمال ہے کہ وہ اسلام کے پھیل جانے سے اور نبی کریم صلی اللہ علیہ وسلم کے جہاد کا حکم دینے سے پہلے وفات پا گئے، لیکن اس پر یہ اعتراض ہوتا ہے جو محمد بن عائذ نے مغازی میں بطریق عثمان بن عطاء خراسانی، بحوالہ ابن عباس رضی اللہ عنہما، وحی کی ابتداء کے بارے میں نقل کیا، اس میں سیدہ خدیجہ رضی اللہ عنہا کا ورقہ کے ساتھ اسی طرح واقعہ منقول ہے جیسے حدیث عائشہ رضی اللہ عنہا میں ہے، اس کے آخر میں ہے: اگر یہ وہی ہوا، پھر اپنی دعوت ظاہر کی، اور میں زندہ رہا تو میں ضرور اللہ سے دعا کروں گا کہ وہ میری ذات کو اپنے رسول کی فرمانبرداری اور اس کی بہترین مدد کے لیے آزمائے پھر ورقہ نصرانیت پر فوت ہوئے، لیکن عثمان ضعیف راوی ہے۔\nزبیر کا قول ہے: ورقہ کو بتوں کی عبادت ناپسند تھی، وہ اطراف میں صحیح دین کی تلاش میں نکل گئے، کتابیں پڑھی تھی، سیدہ خدیجہ رضی اللہ عنہا ان سے نبی کریم صلی اللہ علیہ وسلم کے بارے میں پوچھتی تھیں، وہ کہتے: میرے خیال میں وہ اس امت کے نبی ہیں جس کی حضرت موسی اور حضرت عیسی علیہما السلام نے خوشخبری دی تھی۔ ابن اسحاق کے مغازی الکبیر میں ہے، اسے حاکم نے اپنے طریق سے نقل کیا ہے۔\nفرماتے ہیں: مجھ سے عبدالملک بن عبداللہ بن ابی سفیان بن علاء بن حارثہ ثقفی نے بیان کیا، ان کے چرواہے تھے، فرماتے ہیں: ورقہ بن نوفل نے، جو کچھ سیدہ خدیجہ رضی اللہ عنہا نے ان سے رسول اللہ صلی اللہ علیہ وسلم کے بارے میں ذکر کیا تھا، اس کے بارے میں کہا:\n\"مردوں، زمانے کی گردش اور تقدیر کے ہیر پھیر پر افسوس!\"\nچند اشعار جن میں سے یہ ہیں:\n\"یہ خدیجہ میرے پاس آتی ہے کہ میں اسے خبر دوں جبکہ غیب کی پوشیدگی کی ہمیں کچھ خبر نہیں کہ احمد کے پاس جبرائیل آکے یہ خبر دے رہے ہیں کہ آپ تمام انسانیت کی طرف مبعوث ہیں، تو میں نے کہا: وہ جس کی تم امید کرتی ہو کہ وہ جواب دے گا وہ بیمار ہو گیا اس کا اللہ ہے لہذا خیر کی امید رکھو اور انتظار کرو\"۔(5)\nابن عدی نے کامل میں بطریق اسماعیل بن مجالد، بحوالہ جابر، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے نقل کیا ہے: \"میں نے ورقہ کو جنت کے درمیان دیکھا، ان پر سندس کا کپڑا تھا\"۔(6) ابن عدی کا قول ہے: اسماعیل، بحوالہ اپنے والد سے روایت کرنے میں تنہا ہیں۔\nمیں کہتا ہوں: اسے ابن سکن نے بطریق یحیی بن سعید اموی، بحوالہ مجالد نقل کیا ہے، لیکن اس کے الفاظ یہ ہیں: میں نے ورقہ کو جنت کی ایک نہر پر دیکھا، کیونکہ وہ کہتے تھے: زید کا دین ہی میرا دین ہے اور زید کا الہ میرا اللہ ہے۔ اسے محمد بن عثمان بن ابی شیبہ نے اپنی تاریخ میں اسی طریق سے نقل کیا ہے، بزار نے بطریق ابی معاویہ، بحوالہ عائشہ رضی اللہ عنہا نقل کیا ہے، فرماتی ہیں: نبی کریم صلی اللہ علیہ وسلم نے ورقہ کو گالی دینے سے منع فرمایا ہے۔ یہ روایت یونس بن بکیر کی زیادات مغازی میں ہے، اسے، بحوالہ ہشام بن عروہ، انہوں نے اپنے والد سے نقل کیا ہے، فرماتے ہیں: ورقہ کے بھائی نے کسی شخص کو گالی دی، اس شخص نے ورقہ کو گالی دی، نبی کریم صلی اللہ علیہ وسلم کو یہ بات معلوم ہوئی تو فرمایا: \"کیا تم جانتے ہو کہ میں نے ورقہ کے لیے جنت میں ایک یا دو باغ دیکھے ہیں\"۔ پس آپ صلی اللہ علیہ وسلم نے انہیں گالی دینے سے روکا۔\nاسے بزار نے بطریق ابو اسامہ، بحوالہ ہشام مرسل نقل کیا ہے۔ احمد نے بطریق ابن لہیعہ، بحوالہ عائشہ نقل کیا ہے: سیدہ خدیجہ رضی اللہ عنہا نے نبی کریم صلی اللہ علیہ وسلم سے ورقہ بن نوفل کے بارے میں پوچھا: آپ صلی اللہ علیہ وسلم نے فرمایا: \"میں نے اسے دیکھا ہے کہ اس پر سفید کپڑے ہیں، میرا خیال ہے کہ اگر وہ اہل دوزخ میں سے ہوتے تو اس پر سفید کپڑے نہ ہوتے۔\"","",{"fn":"(1) اسد الغابہ (۵۴۵۸) تجرید (۱۲۸/۲)\n(2) طبرانی (۱۵۳/۲۲) مجمع الزوائد (۲۵۶/۸) جامع المسانید والسنن (۳۸۹/۱۲) السیرۃ النبویۃ (۱۸۹/۲) (۱۸۰/۲)\n(3) مختصر تاریخ دمشق (۲۷۱/۲)\n(4) دلائل النبوۃ (۱۵۸/۲)\n(5) مختصر تاریخ دمشق (۲۷۶/۲۶)\n(6) مختصر تاریخ دمشق (۲۸۳/۲۶)"}],[7757,"§۹۱۳۵ ۔ ورقہ بن نوفل دیلمی\nیا انصاری، ان سے پہلے والی سوانح میں ان کا ذکر گزر چکا ہے۔"],[7758,"§۹۱۳۶ ۔ وزر بن سدوس طائی\n(1) ابن قانع نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، اور بطریق ہشام بن کلبی، بحوالہ عبید اللہ بن عبداللہ نبھانی، عن ابیہ، عن جدہ نقل کیا ہے، فرماتے ہیں: زید خیل الطائی نبی کریم صلی اللہ علیہ وسلم کے پاس آئے، ان کے ساتھ وزر بن سدوس اور قبیصہ بن اسود وغیرہ تھے، انہوں نے اپنی سواریاں بٹھائیں۔(2) پھر قصہ ذکر کیا، قبیصہ کی سوانح میں گزر چکا ہے، رشاطی کا قول ہے: وہ وزر بن جابر بن سدوس ہیں، اپنے دادا کی طرف منسوب ہیں، سدوس وہ ابن اصمع بن ابی بن عبداللہ بن ربیعہ بن سعد بن ثروان بن نبھان ہیں، ابن کلبی کا قول ہے: ان کا لقب اسد رمحس ہے، یہ وہی ہیں جنہوں نے عنزہ عبسی کو قتل کیا تھا، فرماتے ہیں: وہ نبی کریم صلی اللہ علیہ وسلم کے پاس زید الخیل کے ساتھ آئے۔\nمیں کہتا ہوں: ابو الفرج اصبہانی(3) کی کتاب میں زید خیل کی سوانح میں ہے کہ وزر بن سدوس شام چلا گیا، اپنا سر منڈا دیا اور عیسائی ہو گیا، اس حال میں مر گیا۔ واللہ اعلم","",{"fn":"(1) اسد الغابہ (۵۴۵۹) تجرید (۱۲۸/۲)\n(2) اسد الغابہ (۳۱۴/۴)\n(3) اغانی (۴۸/۱۶)"}],[7759,"§۹۱۳۷ ۔ وعلہ بن یزید\n(1) بصرہ کے دیہاتیوں میں ان کا شمار ہے، ابن سکن، ابن شاہین اور ابن مندہ نے بطریق عبدالرحمن بن عمرو بن جبلہ روایت کیا ہے کہ ہم سے فاطمہ بنت محمد بن جلاس عقیلیہ نے روایت کیا، فرماتی ہیں: میں قبیلے کی ایک خاتون ام یزید بنت وعلہ بن یزید کے پاس گئی، انہوں نے اپنے والد کے حوالے سے نقل کیا کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فجر کی نماز میں سورہ ق(2) اور ﴿قُلْ هُوَ اللَّهُ أَحَدٌ﴾ پڑھتے ہوئے سنا۔ ابن مندہ نے یہ اضافہ کیا ہے کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم کو عاشوراء کے روزے کا حکم دیتے ہوئے سنا۔","",{"fn":"(1) اسد الغابہ (۵۴۶۰) تجرید (۱۲۸/۲)\n(2) السیرۃ النبویۃ (۳۶۱/۴)"}],[7760,"§۹۱۳۸ ۔ وفاء بن عدی\nابن ربیع بن ربیعہ ابن عبدالعزی بن عبد شمس بن عبد مناف عبشمی، ان کی اور ان کے بھائی ابو العاص کی والدہ سیدہ ہالہ بنت خویلد، سیدہ خدیجہ رضی اللہ عنہا کی بہن ہیں۔ بلاذری نے ان کا ذکر کیا ہے۔"],[7761,"§۹۱۳۹ ۔ وفرہ بن نافر بعاثی\nایک حدیث میں ان کا ذکر ہے، جسے روایت کرنے میں روح بن زنباح متفرد ہیں۔ یہ جعفر مستغفری کا قول ہے۔"],[7762,"§۹۱۴۰ ۔ وقاص بن حاجب\nابن غفار، ابو بصرہ کے دادا ہیں، جمیل بن بصرہ بن وقاص۔ وقاصی قضاعی نے خطط میں فرمایا: دار کلاب، دار ابی بصرہ ہے، وہ، ان کے والد، ان کے دادا صحابی ہیں۔"],[7763,"§۹۱۴۱ ۔ وقاص بن قمامہ\nبنو حارثہ سے ہیں، حدیث عمرو بن حزم میں ان کا ذکر ہے، یہ ابو موسی کا قول ہے۔"],[7764,"§۹۱۴۲ ۔ وقاص بن مجزز مدلجی\n(1) ابن ہشام کا قول ہے: کئی اہل علم نے ذکر کیا ہے کہ وہ غزوہ ذی قرد میں شہید ہوئے۔ رہے ابن اسحاق(2) تو فرماتے ہیں: اس دن محرز بن نضلہ کے علاوہ کوئی شہید نہیں ہوا۔","",{"fn":"(1) اسد الغابہ (۵۴۶۲) استیعاب (۲۷۷۵) تجرید (۱۲۹/۲) السیرۃ النبویۃ (۲۲۳/۲) (۲۱۶/۴)\n(2) السیرۃ النبویۃ (۲۲۳/۳) و (۲۱۶/۴)"}],[7765,"§۹۱۴۳ ۔ وکیع بن عدس\nابن زرارہ تمیمی، اکثم بن صیفی کی سوانح میں ان کا ذکر گزر چکا ہے، ابو حاتم سجستانی نے معمرین میں ذکر کیا ہے کہ وہ اور حاجب جب انہیں اکثم کا نبی کریم صلی اللہ علیہ وسلم کی طرف نکلنا معلوم ہوا تو وہ اس کے پیچھے نکلے، جب ان کی قبر کے پاس پہنچے تو وہاں ٹھہر گئے اور اونٹ ذبح کیے، پھر اپنے ساتھیوں کے پاس آئے انہوں نے ان سے کہا: تمہیں اکثم نے کیا کہا تھا؟ انہوں نے کہا: انہوں نے ہمیں اسلام لانے کا کہا: ہم ان کے ساتھ اسلام لے آئے۔\nصفوان بن اسید کی سوانح میں گزر چکا ہے کہ وہ قتل ہوئے تو حاجب اور وکیع جو زرارہ کے بیٹے ہیں، نبی کریم صلی اللہ علیہ وسلم کے پاس ان کے قاتل کو لے کر آئے۔ گویا وکیع اپنے دادا کی طرف منسوب ہیں، یا وہ کوئی اور ہیں، تابعین میں وکیع بن عدس ہیں: وہ عقیل بن اخی لقیط بن عامر ہیں۔ ان کا ان کے ساتھ ذکر گزر چکا ہے، تمیمی جو صحابی ہیں اور عقیلی جو تابعی ہیں، ان کا نام اور ان کے والد کا نام ایک جیسا ہے۔"],[7766,"§۹۱۴۴ ۔ وکیع بن مالک\n(1) سیف نے ذکر کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم نے انہیں، مالک بن نویرہ کو بنو حنظلہ، بنو یربوع کے صدقات پر عامل بنایا، رسول اللہ صلی اللہ علیہ وسلم کی وفات ہوئی اور وہ اسی حالت میں تھے۔ پھر سجاح کی موافقت کرنے لگے جس نے نبوت کا دعوی کیا تھا، جب اللہ نے اس کی جمعیت کو ختم کیا تو سیدنا خالد بن ولید کے پاس اپنی قوم کے صدقات لے کر آئے۔ ان سے معذرت کی اور اسلام لائے، ان کا اسلام سنور گیا، اسی طرح طبری نے ذکر کیا ہے۔ سیف نے بھی ذکر کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم نے وکیع دارمی کو صلصل بن شرحبیل کے ساتھ عمرو بن محجوب کی طرف بھیجا، تاکہ وہ مرتدین کے مقابلے میں تعاون کریں۔ ہو سکتا ہے کہ وہ کوئی اور ہوں، صلصل کی سوانح میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) تجرید (۱۲۹/۲)"}],[7767,"§۹۱۴۵ ۔ ولید بن ابی امیہ مخزومی\nام سلمہ رضی اللہ عنہا بنت ابو امیہ ام المومنین کے بھائی ہیں۔ مہاجر کی سوانح میں ان کا ذکر گزر چکا ہے۔ ان کا نام ولید بن ابی امیہ تھا، نبی کریم صلی اللہ علیہ وسلم نے ان کا نام بدل دیا جب وہ اسلام لائے۔ یہ ابن عبد البر کا قول ہے، یہ زبیر بن بکار نے ذکر کیا ہے۔ فرماتے ہیں: ہم سے محمد بن سلام جمعی نے ذکر کیا، وہ فرماتے ہیں کہ ہم سے حماد بن سلمہ اور ابن جعد بہ، ان کے سیاق میں اختلاف ہے، دونوں فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم سیدہ ام سلمہ رضی اللہ عنہا کے پاس تشریف لائے تو ان کے پاس ایک شخص تھا، آپ صلی اللہ علیہ وسلم نے پوچھا: \"یہ کون ہے؟\" انہوں نے کہا: میرا بھائی ولید ہے، ہجرت کر کے آیا ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ مہاجر ہے،\" انہوں نے کہا: یا رسول اللہ! وہ ولید ہیں، آپ صلی اللہ علیہ وسلم نے دوبارہ یہی کہا۔ انہوں نے پھر وہی کہا: آپ صلی اللہ علیہ وسلم نے فرمایا: \"تم چاہتے ہو کہ ولید کو نعم بنالو، میری امت میں ایک فرعون ہو گا جسے ولید کہا جائے گا\"۔"],[7768,"§۹۱۴۶ ۔ ولید بن جابر\n(1) ابن ظالم بن حارثہ بن عباس بن ابی حارثہ بن عتود بن بکتر طائی بحتری۔ نبی کریم صلی اللہ علیہ وسلم کے پاس وفد میں آئے، آپ صلی اللہ علیہ وسلم نے انہیں تحریر لکھ کر دی، وہ ان کے پاس ہے، یہ ابو عمر(2) کا قول ہے۔","",{"fn":"(1) اسد الغابہ (۵۴۶۴) استیعاب (۲۷۴۷) تجرید (۱۲۹/۲)\n(2) استیعاب (۱۱۳/۳)"}],[7769,"§۹۱۴۷ ۔ ولید بن حارث\nابن عامر بن نوفل نوفلی، مشہور صحابی عقبہ بن حارث کے بھائی ہیں۔ بعض کا قول ہے: منذر اور میمونہ بنت ولید کے بھائی ہیں، یہ عبید اللہ بن عبد اللہ بن ابی ملیکہ کی زوجہ ہیں، ان کے والد عبد اللہ بن ابی ملیکہ مشہور تابعی ہیں۔ ہم نے ان کے والد عبد اللہ کا صحابہ رضی اللہ عنہم میں ذکر کیا ہے۔ اگر ولید ان کے نانا ہیں، فتح مکہ تک زندہ رہے تو وہ اس قسم میں سے ہوں گے، اگر وہ اس سے پہلے وفات پا گئے تو ان کی بیٹی میمونہ کو رؤیت حاصل ہے۔ میں نساء کے حرف میم میں ان کا ذکر کروں گا۔ ان شاء اللہ تعالی"],[7770,"§۹۱۴۸ ۔ ولید بن زفر مزنی\n(1) ابن شاہین نے ان کا ذکر کیا ہے، اور بطریق ہشام بن کلبی، بحوالہ بنو مرہ بن عوف کے ایک شخص سے نقل کیا ہے، فرماتے ہیں: ولید بن زفر، نبی کریم صلی اللہ علیہ وسلم کے پاس وفد میں آئے۔ رسول اللہ صلی اللہ علیہ وسلم نے انہیں جھنڈا باندھ کر دیا، ان کی زوجہ آئی اور رونے لگی۔ ان کے چچا زاد ساریہ بن اونی اٹھے، نبی علیہ السلام کی طرف چلنے لگے۔ نبی کریم صلی اللہ علیہ وسلم نے صعدہ کو بلایا اور انہیں جھنڈا باندھ دیا۔ پھر وہ بنو مرہ کی طرف چلے، ان پر اسلام پیش کیا، انہوں نے قبول کرنے میں تاخیر کی، انہوں نے ان پر تلوار چلا دی۔ جب بہت زیادہ قتل کیا تو وہ لوگ اسلام لائے، اور ان کے گرد قیس میں سے لوگ اسلام لائے، پھر وہ نبی کریم صلی اللہ علیہ وسلم کی طرف ایک ہزار شہسواروں کے ساتھ چلے۔(2)","",{"fn":"(1) اسد الغابہ (۵۴۶۵) تجرید (۱۲۹/۲)\n(2) اسد الغابہ (۳۱۴/۴)"}],[7771,"§۹۱۴۹ ۔ ولید بن عبد شمس\n(1) ابن مغیرہ بن عبداللہ بن عمر بن مخزوم مخزومی، ان کی کنیت ابو عبدالرحمن ہے۔ قریش کے معزز لوگوں میں سے تھے، زبیر بن بکار کا قول ہے: ان کی والدہ قیلہ بنت جحش بن ربیعہ ہیں جو بنو عامر بن لوی سے ہیں۔ ابن اسحاق نے مغازی میں فرمایا: یمامہ میں شہید ہوئے۔ سیدنا عثمان رضی اللہ عنہ نے اپنی بیٹی فاطمہ کا نکاح ان سے کر دیا، جس سے سعید پیدا ہوئے۔","",{"fn":"(1) اسد الغابہ (۵۴۶۷) استیعاب (۲۷۴۹)"}],[7772,"§۹۱۵۰ ۔ ولید بن عقبہ\n(1) ابن ابی معیط، ابان بن ابی عمرو، ذکوان بن امیہ بن عبد شمس بن عبد مناف اموی، عثمان بن عفان کے ماں شریک بھائی ہیں۔ ان دونوں کی والدہ اروی بنت کریز بن ربیعہ بن حبیب بن عبد شمس ہیں۔ ان کی والدہ بیضاء بنت عبدالمطلب ہیں، ان کی کنیت ابو وہب ہے، ان کا باپ غزوہ بدر سے فراغت کے بعد باندھ کر قتل کیا گیا۔ وہ مسلمانوں پر بہت سخت اور رسول اللہ صلی اللہ علیہ وسلم کو بہت زیادہ ایذاء دیتا تھا۔ بدر کے قیدیوں میں تھا۔ نبی کریم صلی اللہ علیہ وسلم نے اس کے قتل کا حکم دیا۔ اس نے کہا: اے محمد! بچوں کا کون نگران ہو گا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"آگ\"۔ ولید اور ان کے بھائی عمارہ فتح مکہ کے دن اسلام لائے۔ بعض کا قول ہے: یہ آیت اس کے بارے میں نازل ہوئی: ﴿اے ایمان والو! اگر تمہارے پاس فاسق کوئی خبر لے کر آئے تو اس کی تحقیق کر لیا کرو﴾۔(2) (الآیۃ)\nابن عبد البر(3) کا قول ہے: اہل علم کو قرآن کی آیت کی اس تفسیر میں اختلاف نہیں ہے کہ یہ آیت ان کے بارے میں نازل ہوئی، اس لیے کہ رسول اللہ صلی اللہ علیہ وسلم نے انہیں بنو مصطلق(4) کی طرف تصدیق کے لیے بھیجا، وہ واپس آئے اور ان کے بارے میں خبر دی کہ وہ مرتد ہو گئے ہیں، زکوۃ نہیں دیتے، وہ ان سے ملاقات کے لیے نکلے تھے اور ان پر ہتھیار تھے، انہوں نے گمان کیا کہ وہ ان سے لڑائی کے لیے نکلے ہیں، لہذا وہ واپس آ گئے۔ رسول اللہ صلی اللہ علیہ وسلم نے ان کی طرف سیدنا خالد بن ولید رضی اللہ عنہ کو بھیجا، انہوں نے آپ صلی اللہ علیہ وسلم کو بتایا کہ وہ اسلام پر ہیں، پھر یہ آیت نازل ہوئی۔\nمیں کہتا ہوں: اس قصے کو عبد الرزاق نے اپنی تفسیر میں، بحوالہ قتادہ نقل کیا ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے ولید بن عقبہ کو بنو مصطلق کی طرف بھیجا، ان لوگوں نے اس سے ملاقات کی، انہوں نے ان لوگوں کو پہچان لیا، پھر واپس لوٹ آئے اور کہا: وہ مرتد ہو گئے ہیں، رسول اللہ صلی اللہ علیہ وسلم نے ان کی طرف سیدنا خالد بن ولید رضی اللہ عنہ کو بھیجا، جب وہ ان لوگوں کے قریب پہنچے تو رات کے وقت جاسوس کو بھیجا تو وہ لوگ اذان دے رہے تھے اور نماز پڑھ رہے تھے، سیدنا خالد بن ولید ان کے پاس گئے تو انہیں مطیع اور بھلائی پر پایا، وہ نبی کریم صلی اللہ علیہ وسلم کی طرف واپس آئے اور آپ صلی اللہ علیہ وسلم کو بتایا، اس پر یہ آیت نازل ہوئی۔ اسے عبد بن حمید نے، بحوالہ قتادہ اسی مفہوم میں نقل کیا ہے۔ بطریق حکم بن ابان، بحوالہ عکرمہ اسی مفہوم میں نقل ہے، بطریق ابن ابی نجیح، بحوالہ مجاہد اسی طرح مروی ہے۔ اسے طبرانی نے، موصولاً، بحوالہ حارث بن ضرار مصطلقی طویل نقل کیا ہے۔\nسند میں ایسا راوی ہے جو معروف نہیں، ابو داؤد(5) کی سنن میں بطریق ثابت بن حجاج، بحوالہ ولید بن عقبہ اس روایت سے تعارض ہے۔ فرماتے ہیں: جب رسول اللہ صلی اللہ علیہ وسلم نے مکہ فتح کیا تو اہل مکہ اپنے بچوں کو لانے لگے، آپ صلی اللہ علیہ وسلم ان کے سروں پر ہاتھ پھیرتے تھے، مجھے بھی آپ صلی اللہ علیہ وسلم کے پاس لایا گیا، مجھے رنگ دار خوشبو لگی ہوئی تھی، آپ صلی اللہ علیہ وسلم نے اس رنگ دار خوشبو کی وجہ سے میرے سر پر ہاتھ نہ پھیرا۔ ابن عبد البر(6) کا قول ہے: ابو موسی مجہول ہیں، فتح مکہ کے موقع پر جو بچہ ہو، فتح مکہ کے تھوڑے عرصے بعد نبی کریم صلی اللہ علیہ وسلم اسے تصدیق کے لیے نہیں بھیج سکتے۔ زبیر وغیرہ نے سیرت کا علم رکھنے والے راویوں سے نقل کیا ہے کہ ام کلثوم بنت عقبہ جب ۷ ھ صلح کے زمانے میں نبی کریم صلی اللہ علیہ وسلم کے پاس ہجرت کر کے آئیں تو ان کے بھائی ولید اور عمارہ انہیں واپس لوٹانے کے لیے آئے، فرماتے ہیں: فتح مکہ کے موقع پر جو بچہ ہو تو وہ فتح سے پہلے اپنی بہن کو لوٹانے کے لیے کیسے جا سکتا ہے۔\nمیں کہتا ہوں: وہ فتح مکہ کے موقع پر آدمی تھے، اس کی تائید اس سے ہوتی ہے کہ وہ اپنے والد کے چچا زاد حارث بن ابی وجزہ بن ابی عمرو بن امیہ کا فدیہ لے کر آئے، بدر کے دن وہ قید ہو گئے ہیں، اس کا فدیہ چار ہزار(۴۰۰۰) دیا، اسے اصحاب مغازی نے بیان کیا ہے کہ اس کے بعد ولید سیدنا عثمان رضی اللہ عنہ کی تربیت میں بڑھنے لگے یہاں تک کہ جب سیدنا عثمان رضی اللہ عنہ خلیفہ بنے تو انہیں سیدنا سعد بن ابی وقاص کی معزولی کے بعد کوفہ کا گورنر بنا دیا۔ جو لوگوں پر بہت شاق گزرا۔ ولید بہادر، شاعر اور سخی تھے۔ مصعب زبیری کا قول ہے: قریش کے رجال اور سردار تھے، صبح کی نماز میں انہوں نے لوگوں کو چار رکعت پڑھائیں یہ قصہ مشہور اور منقول ہے۔ شراب پینے کا جرم ثابت ہونے کے بعد ان کے معزول ہونے کا قصہ مشہور ہے جو صحیحین میں ہے، سیدنا عثمان رضی اللہ عنہ نے انہیں کوڑے لگانے کے بعد کوفہ سے معزول کر دیا اور سیدنا سعید بن العاص کو اس کا والی بنا دیا۔ بعض نے کہا: کوفہ کے کچھ لوگوں نے تعصب کی بنا پر ناحق ان کے خلاف گواہی دی، اسے طبری نے روایت کیا ہے، ابن عبد البر نے اس کا انکار کیا ہے۔\nجب سیدنا عثمان رضی اللہ عنہ شہید ہوئے تو سیدنا ولید فتنے سے الگ رہے، نہ وہ سیدنا علی رضی اللہ عنہ کے ساتھ شریک تھے نہ کسی اور کے ساتھ، لیکن وہ سیدنا معاویہ رضی اللہ عنہ کو اپنی تحریروں اور اشعار سے سیدنا علی رضی اللہ عنہ سے قتال کی ترغیب دلاتے۔ اس میں سے یہ بھی ہے کہ سیدنا علی رضی اللہ عنہ نے جب جریر کو سیدنا معاویہ رضی اللہ عنہ کے پاس خط دے کر بھیجا، اس میں انہیں مطیع ہونے کا اور اہل شام سے بیعت لینے کا حکم دیا، ولید کو یہ بات معلوم ہوئی تو انہوں نے ان کی طرف شعر لکھ کر بھیجے:\n\"تمہارے پاس علی کے قلم سے لکھا ہوا خط آیا ہے، جو فیصلہ کن ہے، یا تو اس کی صلح کو قبول کر لو یا اس سے جنگ کرو، اگر تمہاری نیت اسے جواب دینے کی ہے تو اس خط کے املاء کرنے والے اور اس کے کتاب کا برا ہو۔\"\nنیز ان کی طرف یہ اشعار لکھ کر بھیجے:\n\"تم اور علی کی طرف خط کی مثال ایسے ہے جیسے کوئی دباغت کرنے والا اس وقت دباغت کرے جب چمڑا سوکھ جائے۔\"\nسیدنا عثمان رضی اللہ عنہ کی شہادت کے موقع پر انہوں نے یہ اشعار کہے تھے:\n\"خبردار! تین افراد کے بعد سب سے بہترین شخص تحیمی کا مقتول ہے جو مضر سے آیا تھا، میں کیسے نہ روؤں جبکہ میرے رشتہ دار رو رہے ہیں، ابو عمر کے احسانات ہم سے رک گئے۔\"\nانہوں نے وفات تک مقام رقہ میں قیام کیا۔ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے احادیث روایت کیں، جن کا ذکر گزر چکا ہے۔ انہوں نے سیدنا عثمان رضی اللہ عنہ وغیرہ سے روایت کیا، ان سے حارثہ بن مضرب، شعمی، ابو موسیٰ ہمدانی وغیرہ نے روایت کیا۔ خلیفہ کا قول ہے: سیدنا ولید ۲۵ھ میں کوفہ کے امیر تھے، ۲۸ھ میں انہوں نے آذربائیجان کا جہاد کیا، وہ قوم کے امیر تھے۔ ۲۹ھ میں معزول ہوئے، ابو عروبہ حرابی کا قول ہے: خلافت معاویہ میں وفات پائی۔","",{"fn":"(1) اسد الغابہ (۵۴۶۸) استیعاب (۲۷۵۰)\n(2) سورۃ الحجرات الآیۃ (۶)\n(3) استیعاب (۱۱۴/۳)\n(4) مختصر تاریخ دمشق (۳۳۸/۲۸، ۳۳۹)\n(5) استیعاب (۱۱۴/۳)\n(6) السیرۃ النبویۃ (۲۵۳/۳)"}],[7773,"§۹۱۵۱ ۔ ولید بن عمارہ\n(1) ابن ولید ابن مغیرہ بن عبداللہ بن عمر بن مخزوم مخزومی، ہجرت سے پہلے پیدا ہوئے، ابن عبد البر(2) کا قول ہے: سیدنا خالد ابن ولید کے ساتھ بطاح میں ۱۱ھ میں شہید ہوئے۔ دوسرے راویوں کا قول ہے: ان کی والدہ بنت بلعاء بن قیس کنانی ہیں، ان کے والد عمرو نے سیدنا عمرو بن العاص رضی اللہ عنہ کے ساتھ قریش کی طرف سے نجاشی کے پاس سفر کیا تاکہ وہ مسلمان مہاجرین کو واپس لوٹا لائیں، عمارہ نے اپنے اہل اور اولاد کو مکہ میں چھوڑا، ان میں سے ولید، ابو عبیدہ، عبد الرحمن اور ہشام ہیں۔ اپنی اپنی جگہ پر ان کا ذکر گزر چکا ہے۔ عمارہ کا قصہ زبیر نے بیان کیا ہے جس کا خلاصہ یہ ہے کہ وہ عمرو بن عاص کی باندی پر گر گئے، سیدنا عمرو بن عاص کو پتہ چلا تو ناراض ہوئے اور سخت انہیں ڈانٹا، جب نجاشی کے پاس ٹھہر گئے تو عمارہ نے نجاشی کی بیوی کے ساتھ بھی ایسا ہی کیا۔ عمارہ حسین و جمیل تھے تو وہ اس کی طرف مائل ہو گئی اور ان سے میل ملاپ کرنے لگی۔ عمرو کو اس کا پتہ چلا، اس نے نجاشی کو بتا دیا، جب اسے حقیقت معلوم ہوئی تو ساحروں کو حکم دیا، انہوں نے ان کے ذکر کے اگلے حصے میں پھونک ماری تو وحشی ہو گئے اور جانوروں کے ساتھ رہے، یہاں تک کہ خلاف عمر میں عبداللہ بن ابی ربیعہ ان کی طرف گئے، گھات لگا کر بیٹھے اور انہیں پانی پر پکڑ لیا، وہ چلانے لگے: مجھے چھوڑ دو، اگر تم نے مجھے چھوا تو میں مر جاؤں گا، وہ آپ کے ہاتھوں میں مر گئے۔\nزبیر کا قول ہے: مجھ سے عبداللہ بن یزید بن ہذلی نے بیان کیا کہ مجھے عبداللہ بن محمد بن عمران طلحی نے بتایا، فرماتے ہیں: جب عمارہ نے عبداللہ اور ان کے ساتھ دوسرے لوگوں کو دیکھا تو چلا کر کہنے لگے: اے مغیرہ! اے مغیرہ!","",{"fn":"(1) اسد الغابہ (۵۴۶۹) استیعاب (۲۷۵۱) تجرید (۱۲۹/۲)\n(2) استیعاب (۱۱۸/۳)"}],[7774,"§۹۱۵۲ ۔ ولید بن قاسم\n(1) ولید بن دباغ نے استیعاب پر اپنے استدراک میں ان کا ذکر کیا ہے، اور بطریق ابو احمد عسکری، پھر بطریق معلی بن زیاد، بحوالہ ولید بن قاسم نقل کیا ہے، انہیں شرف صحابیت حاصل ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"وہ برے لوگ ہیں جو شبہات اور شہوات سے حرام چیزوں کو حرام کر لیتے ہیں۔۔۔۔ (الحدیث)(2)","",{"fn":"(1) اسد الغابہ (۵۴۷۰) تجرید (۱۲۹/۲)\n(2) کنز العمال (۵۵۸۴) جامع المسانید والسنن (۳۹۲/۱۲)"}],[7775,"§۹۱۵۳ ۔ ولید بن قیس\n(1) ابن سکن نے ان کا ذکر کیا ہے، فرماتے ہیں: ان کی حدیث ثابت نہیں، اسے حسن بن سفیان نے اپنی مسند میں اور طبرانی(2) نے کبیر میں بطریق عبدالملک بن حسن بن خثیمی، بحوالہ ولید بن قیس نقل کیا ہے، فرماتے ہیں: انہیں برص کی بیماری تھی، رسول اللہ صلی اللہ علیہ وسلم نے ان کے لیے دعا کی، جس سے وہ ٹھیک ہو گئے۔ عبدالملک وہ ابو مالک ہے۔ بہت ضعیف راوی ہے۔","",{"fn":"(1) اسد الغابہ (۵۴۷۱) استیعاب (۲۷۵۲)\n(2) المعجم الکبیر (۱۵۱/۲۲)"}],[7776,"§۹۱۵۴ ۔ ولید بن ولید\n(1) ابن مغیرہ بن عبداللہ بن عمر بن مخزوم قرشی مخزومی، خالد بن ولید کے بھائی ہیں۔ بدر میں مشرکین کے ساتھ شریک تھے، قیدی بنے، ان کے بھائیوں ہشام اور خالد نے ان کا فدیہ دیا، ہشام ان کا سگا بھائی تھا، ان دونوں کی والدہ آمنہ یا عاتکہ بنت حرملہ ہیں، جب ان کا فدیہ دیا گیا تو اسلام لے آئے۔ ان لوگوں نے اس پر عتاب کیا تو انہوں نے کہا: میں نے قبول کیا، مجھے یہ بات ناپسند تھی کہ لوگ میرے بارے میں گمان کریں کہ میں قید میں گھبرا گیا تھا۔ واقدی نے اپنی اسانید سے ان کا ذکر کیا ہے، جب اسلام لائے تو ان کے ماموؤں نے انہیں قید کر لیا۔ نبی کریم صلی اللہ علیہ وسلم قنوت نازلہ میں ان کے لیے دعا کرتے تھے، جیسا کہ صحیح میں حدیث ابو ہریرہ رضی اللہ عنہ سے ثابت ہے کہ آپ صلی اللہ علیہ وسلم فرمایا کرتے: \"اے اللہ! ولید بن ولید اور ان مومنوں کو نجات دے جو کمزور سمجھے جاتے ہیں\"۔(2) جب قید سے واپس آئے تو نبی کریم صلی اللہ علیہ وسلم سے عمرہ قضیہ میں ملے، بعض کا قول ہے: وہ پیدل ہی قید سے نکل بھاگے، ان لوگوں نے انہیں تلاش کیا، لیکن انہیں پا نہ سکے، بعض نے کہا: وہ بئر ابی عقبہ میں مدینہ آنے سے پہلے فوت ہو گئے۔ بعض نے کہا: جب نبی کریم صلی اللہ علیہ وسلم عمرہ کے لیے تشریف لے گئے تو خالد مکہ سے نکل گئے یہاں تک کہ انہوں نے مسلمانوں کو مکہ میں داخل ہوتے نہیں دیکھا، نبی کریم صلی اللہ علیہ وسلم نے ولید\nابن ولید سے فرمایا: \"اگر خالد ہمارے پاس آتے تو ہم اس کا اکرام کرتے، یہ ایسا شخص نہیں ہے کہ کسی عقد میں اسلام سے نا آشنا رہا ہو\"۔ ولید نے یہ سیدنا خالد رضی اللہ عنہ کو لکھا، یہ ان کی ہجرت کا سبب بنا، اسے واقدی نے بھی اسی طرح بیان کیا ہے، زبیر بن بکار نے بحوالہ محمد بن ضحاک، عمن ابیہ نقل کیا ہے، جب ولید بن ولید نے ہجرت کی تو ان کی والدہ کہنے لگیں:\n\"مسافت کا چوتھائی حصہ ولید نے ہجرت کی، تو اس عورت سے ایک اونٹ اور اونٹنی خریدے اور ان کی جانب آرزوؤں کے ساتھ بلند ہو۔\"\nفرماتے ہیں: میرے چچا مصعب کی روایت میں ہے:\n\"ان کے درمیان سے تنگ دل یا تنگ جان پھینک دے۔\"\nان کے اشعار میں ایسا شعر ہے جس سے پتہ چلتا ہے کہ وہ اسلام لے آئی تھیں۔ جب ولید کا انتقال ہوا تو سیدہ ام سلمہ رضی اللہ عنہا حضور صلی اللہ علیہ وسلم کی زوجہ جو ان کی چچازاد بہن تھیں کہنے لگیں:\n\"اے آنکھ! ولید بن ولید بن مغیرہ پہ آنسو بہا، بے شک وہ قحط سالیوں میں بارش، ہم لوگوں میں روشن رحمت تھا۔ وہ بہت زیادہ بخشش والا، عزت مند ہے۔ سخاوت کے طریق کی تلاش میں بلند ہوتا ہے، ابو الولید ولید بن ولید جیسا شخص خاندان کے لیے کافی ہے۔\"(3)\nاسی طرح زبیر بن بکار نے بحوالہ محمد بن ضحاک حزامی، عمن ابیہ، انہی الفاظ میں نقل کیا ہے، انہوں نے اس قول \"وہ ہم لوگوں میں روشن رحمت تھا\" اس کے بجائے اور الفاظ نقل کیے ہیں \"بہت زیادہ پانی والی ندی، اور ذخیرہ شدہ خوراک تھا\"۔ ایک روایت میں ہے: \"پانی سے بھری ہوئی ندی ہے\"۔ ابن عدی کی کامل میں بطریق کامل بن علاء، بحوالہ حبیب بن ابی ثابت مروی ہے کہ سیدہ ام سلمہ رضی اللہ عنہا نے نبی کریم صلی اللہ علیہ وسلم سے فرمایا: ولید بن ولید فوت ہو گیا ہے، میں اس پر کیسے روؤں؟ فرماتے ہیں: میرا قول۔۔۔۔ پھر شعر ذکر کیا، یہ باطل ہے۔ گویا وہ راوی سے الٹ گیا ہے۔ طبرانی(4) نے بطریق عبد العزیز بن عمران، بحوالہ اسماعیل بن ایوب مخزومی نقل کیا ہے کہ ولید بن ولید بن مغیرہ مکہ میں قید تھے، جب انہوں نے ہجرت کرنے کا ارادہ کیا تو طائف میں اپنا مال بیچا، جب لوگ بے خبر تھے، وہ اور عیاش بن ابی سلمہ اور سلمہ بن ہشام پیدل نکل بھاگے، انہیں تعاقب کا خوف تھا، وہ بھاگے یہاں تک کہ تھک گئے۔ ولید پیچھے رہ گئے۔ اس پر انہوں نے کہا:\n\"اے میرے قدمو! مجھے ان لوگوں تک پہنچا دو اور آج کے بعد مجھے کبھی نہ تھکانا۔\"\nجب احراس کے مقام پر پہنچے تو انہیں ٹھوکر لگی تو کہا:\n\"تو ایک خون آلود انگلی ہی تو ہے، اللہ کے راستے میں تجھے یہ تکلیف پہنچی ہے۔\"\nپھر رسول اللہ صلی اللہ علیہ وسلم کے پاس پہنچے اور کہا: یا رسول اللہ! میں تھک گیا ہوں، اور میں مرنے والا ہوں، آپ اپنے زائد کپڑے سے جو آپ کے بدن مبارک پر ہو مجھے کفن دیجئے، پھر وہ وفات پا گئے، نبی کریم صلی اللہ علیہ وسلم نے اپنی قمیص میں انہیں کفن دیا، اور سیدہ\nام سلمہ رضی اللہ عنہا کے ہاں گئے، ان کے سامنے بچہ تھا، اور وہ کہہ رہی تھیں: \"ولید بن ولید بن مغیرہ پر رو\"۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"تم لوگوں سے اگر ہو سکتا تو تم ولید کو دل کی نرمی بنا لیتے\"۔ پھر ان کا نام عبداللہ رکھا۔ ان کا یہ قصہ مصعب زبیری نے بغیر اسناد ذکر کیا ہے۔ ولید ابن مغیرہ کی سوانح میں اس میں سے کچھ آئے گا۔\nاحمد نے اپنی مسند میں ان کی ایک حدیث بروایت محمد بن یحیی بن حبان ان کے حوالے سے نقل کی ہے کہ انہوں نے فرمایا: یا رسول اللہ! مجھے خواب میں ڈر لگتا ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم سونے کے لیے لیٹو تو کہو: اللہ کے نام سے میں اللہ کے کلمات کے ساتھ اس کے غصے سے، اس کی سزا سے، اس کے بندوں کے شر سے اور شیاطین کے لشکروں سے پناہ مانگتا ہوں اور میں آپ کی پناہ مانگتا ہوں کہ وہ میرے پاس آئیں\"۔ وہ تمہیں کچھ نقصان نہیں پہنچائے گا۔۔۔۔ (الحدیث)(5)\nیہ روایت منقطع ہے کیونکہ محمد بن یحیی نے انہیں نہیں پایا، اسے ابو داؤد نے بروایت ابن اسحاق، بحوالہ عمرو بن شعیب، عمن ابیہ عمن جدہ نقل کیا ہے، فرماتے ہیں: ولید بن ولید نیند میں گھبرا جاتے تھے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے اس کا ذکر کیا۔۔۔۔ پھر حدیث ذکر کی۔","",{"fn":"(1) اسد الغابہ (۵۴۷۲) استیعاب (۲۷۵۳) تجرید (۱۳۰/۲)\n(2) مجمع الزوائد (۱۷۶/۶) جامع المسانید والسنن (۳۹۷/۱۲) تاریخ کبیر (۱۵۳/۴)\n(3) طبقات الکبری (۹۳/۴) اسد الغابہ (۳۱۸/۴) استیعاب (۱۱۸/۳)\n(4) المعجم الکبیر (۱۵۲/۲۲، ۱۵۳)\n(5) کنز العمال (۴۱۲۷۶)"}],[7777,"§۹۱۵۵ ۔ ولید بن یزید\nابن ربیعہ بن شمس قرشی عبشمی، بلاذری نے ان کا ذکر کیا ہے ان کا بیٹا عبداللہ بن ولید جنگ جمل میں سیدہ عائشہ رضی اللہ عنہا کے ساتھ شریک تھا۔"],[7778,"§۹۱۵۶ ۔ وہبان بن صیفی غفاری\nرہبان میں ان کا ذکر گزر چکا ہے۔"],[7779,"§۹۱۵۷ ۔ وہب بن اسود\nاسود بن وہب میں گزر چکے ہیں۔"],[7780,"§۹۱۵۸ ۔ وہب بن امیہ\n(1) ابن ابی الصلت ثقفی، ابن کلبی نے روایت نقل کی ہے، جس سے عہد نبوی میں ان کے اسلام لانے کا پتہ چلتا ہے کہ نبی کریم صلی اللہ علیہ وسلم کے زمانے میں ثقیف میں سے ایک شخص فوت ہو گیا، اس کی اولاد نہیں تھی، اس کی میراث میں جھگڑا ہو گیا، نبی کریم صلی اللہ علیہ وسلم نے اس کی میراث وہب بن امیہ بن ابی الصلت بن ربیعہ بن عوف ثقفی کو دی، عبداللہ بن صفوان بن امیہ بن خلف طلحی نے مجھے بتایا کہ وہب ابن امیہ بن ابی الصلت سے نکاح کیا، جس سے صفوان بن عبداللہ بن صفوان کی ولادت ہوئی۔","",{"fn":"(1) اسد الغابہ (۵۴۷۴)"}],[7781,"§۹۱۵۹ ۔ وہب بن حذیفہ\n(1) ابن عباد بن خلاد غفاری، بعض کا قول ہے: مزنی ہیں، ایک قول ہے: ثقفی ہیں، حجازی ہیں، ان کی ایک حدیث ہے جسے ترمذی(2) وغیرہ نے بطریق واسع بن حبان ان کے حوالے سے مرفوع نقل کیا ہے: \"جب کوئی شخص کسی مجلس سے اٹھ کر جائے پھر واپس آئے تو وہ اس جگہ کا زیادہ حق دار ہے\"۔ ترمذی نے اسے صحیح قرار دیا ہے، ابن سعد نے اہل خندق کے طبقہ میں ان کا ذکر کیا ہے، اور بحوالہ واقدی نقل کیا ہے کہ وہ اہل الصفہ میں سے تھے، سیدنا معاویہ رضی اللہ عنہ کی خلافت تک زندہ رہے۔","",{"fn":"(1) اسد الغابہ (۵۴۷۶) استیعاب (۲۷۵۵)\n(2) ترمذی (۲۷۰۶)"}],[7782,"§۹۱۶۰ ۔ وہب بن حمزہ\n(1) ابن مسکن کا قول ہے، بعض نے کہا: انہیں شرف صحابیت حاصل ہے۔ ان کی حدیث کی اسناد میں تردد ہے، پھر بطریق یوسف بن صہیب، بحوالہ وہب بن حمزہ نقل کیا ہے، فرماتے ہیں: میں نے سیدنا علی رضی اللہ عنہ کے ساتھ سفر کیا، میں نے ان میں سختی دیکھی تو میں نے کہا: میں واپس جا کر ان کی شکایت کروں گا، پھر میں واپس آیا، میں نے رسول اللہ صلی اللہ علیہ وسلم سے سیدنا علی رضی اللہ عنہ کا ذکر کیا اور اس کی شان میں کچھ نازیبا باتیں کیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"ایسا ہرگز نہ کہو، یہ علی ہیں اور میرے بعد تمہارے ولی ہیں\"۔(2)","",{"fn":"(1) اسد الغابہ (۵۴۷۷) تجرید (۱۳۰/۲)\n(2) المعجم الکبیر (۱۳۵/۲۲) مجمع الزوائد"}],[7783,"§۹۱۶۱ ۔ وہب بن خنبش\n(1) جعفر کے وزن پر ہے، شعبی رضی اللہ عنہ کے ہاں ان کی حدیث ہے، بیان، فراس اور جابر وغیرہ نے، بحوالہ شعبی، ان کے حوالے سے اسی طرح نقل کیا ہے، داؤد اودی نے، بحوالہ شعبی فرمایا: وہب کے بدلے ہرم ہے، پہلا قول مشہور ہے۔","",{"fn":"(1) اسد الغابہ (۵۴۷۸) استیعاب (۲۷۵۶)"}],[7784,"§۹۱۶۲ ۔ وہب بن خویلد\nابن خویلم بن عوف بن عبدہ ثقفی، ان کا ذکر کیا ہے۔۔۔۔(1)","",{"fn":"(1) بیاض فی الاصل"}],[7785,"§۹۱۶۳ ۔ وہب بن زمعہ\n(1) ابن اسود بن مطلب، بن اسد بن عبد العزی بن قصی اسدی، مسلمانان فتح مکہ میں سے ہیں، قریش کے نہایت سخی تھے، سنن ابی داؤد میں ان کی ایک حدیث ہے، جسے بطریق محمد بن اسحاق(2) نقل کیا ہے کہ مجھ سے ابو عبیدہ بن عبداللہ بن زمعہ نے، بحوالہ اپنے والد اور اپنی والدہ زینب بنت ابی لیلی، دونوں نے، بحوالہ ام سلمہ رضی اللہ عنہا روایت کیا ہے، فرماتی ہیں: وہ رات جس میں نحر کے دن شام کو رسول اللہ صلی اللہ علیہ وسلم میرے پاس آئے، آپ صلی اللہ علیہ وسلم میرے ہاں تھے کہ میرے ہاں وہب بن زمعہ اور آل ابی امیہ میں سے ایک شخص آیا دونوں نے قمیص پہنی ہوئی تھی، ان سے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کیا تم عرفات سے واپس لوٹے ہو؟\"۔۔۔۔ (الحدیث)(3)\nزبیر بن بکار نے بطریق یحیی بن مقداد بن یعقوب زمعی، بحوالہ اپنے چچا موسی بن یعقوب نقل کیا ہے، فرماتے ہیں: جب لوگ سیدنا معاویہ رضی اللہ عنہ کے پاس جمع ہوئے تو عبداللہ اصغر بن وہب بن زمعہ اپنے بھائی عبداللہ اکبر کے خون کا بدلہ لینے کے لیے گئے، وہ یوم الدار کو قتل ہوئے، سیدنا معاویہ رضی اللہ عنہ نے انہیں دیت دی اور فرمایا: وہ فتنہ اور اختلاط میں قتل ہوئے۔","",{"fn":"(1) اسد الغابہ (۵۴۸۰) تجرید (۱۳۰/۲)\n(2) السیرۃ النبویۃ (۶۵۳/۱) و (۶۵۷/۱)\n(3) مسند احمد (۲۹۵/۶) صحیح ابن خزیمہ (۲۹۵۸) بیہقی (۱۳/۵)"}],[7786,"§۹۱۶۴ ۔ وہب بن ابی سرح\n(1) ابن حارث بن حبیب بن جذیمہ بن مالک بن حسل بن عامر قرشی عامری، عمرو کے بھائی ہیں، یہ ابو عمر کا قول ہے۔ موسی بن عقبہ نے ذکر کیا ہے کہ وہ اور ان کے بھائی عمرو بدر میں شریک ہوئے۔ ابن فتحون نے ان کا تعاقب کیا ہے کیونکہ موسی بن عقبہ میں ان کا ذکر نہیں، انہوں نے وہب بن سعد بن ابی سرح کا ذکر کیا ہے۔\nمیں کہتا ہوں: وہ اس کے علاوہ ہیں۔ ہیشم بن عدی نے مہاجرین حبشہ میں ان کا ذکر کیا ہے، بلاذری کا قول ہے: یہ ثابت نہیں لیکن وہ بدر میں شریک ہوئے۔ ابو معشر کہتے تھے: ان کے بھائی معمر نے حبشہ کی طرف ہجرت کی، واقدی کا قول ہے: انہوں نے حبشہ کی طرف ہجرت نہیں کی، وہ بدر میں شریک ہوئے تھے، جن کا موسی بن عقبہ، ابن اسحاق اور کلبی نے ذکر کیا ہے وہ عمرو بن ابی سرح ہیں۔","",{"fn":"(1) اسد الغابہ (۵۴۸۱) تجرید (۱۳۰/۲)"}],[7787,"§۹۱۶۵ ۔ وہب بن سعد\n(1) ابن ابی سرح بن ربیعہ بن ہلال بن مالک بن ضبہ بن حارث بن فہر فہری۔ عبداللہ بن سعد کے بھائی ہیں۔ ابن مندہ اور ابن حبان نے ان کا ذکر کیا ہے، وہ دونوں فرماتے ہیں: ہمیں ان کی روایت معلوم نہیں، محمد بن سعد(2) نے طبقات میں ان کا ذکر کیا ہے، فرماتے ہیں: بدر میں شریک ہوئے، موسی بن عقبہ، ابو معشر اور واقدی کا قول ہے: رسول اللہ صلی اللہ علیہ وسلم نے ان کے اور سوید بن عمرو کے درمیان بھائی چارہ قائم کر دیا تھا، دونوں موتہ کے دن شریک تھے، فرماتے ہیں: وہب بن سعد احد، خندق، حدیبیہ اور خیبر میں شریک ہوئے جس وقت شہید ہوئے چالیس(۴۰) سال کے تھے۔(3) پھر ابن مندہ نے، بحوالہ عاصم بن عمر روایت کیا ہے، فرماتے ہیں: وہب ابن سعد نے جب ہجرت کی تو کلثوم بن ہدم کے پاس فروکش ہوئے۔","",{"fn":"(1) اسد الغابہ (۵۴۸۲) استیعاب (۲۷۵۸) تجرید (۱۳۱/۲)\n(2) طبقات الکبری (۲۹۶/۳)\n(3) السیرۃ النبویۃ (۳۸۸/۲)"}],[7788,"§۹۱۶۶ ۔ وہب بن سماع عوفی\n(1) ابن عبد البر(2) نے ان کا ذکر کیا ہے، فرماتے ہیں: نبوت کی علامات کے بارے میں ان کی حدیث ہے جو حدیث ابن عباس رضی اللہ عنہما سے مروی ہے۔\nمیں کہتا ہوں: ابن سعد نے شرف مصطفی میں نہایت کمزور سند سے، بحوالہ ابن عباس رضی اللہ عنہما روایت کیا ہے، فرماتے ہیں: اسی اثناء میں کہ رسول اللہ صلی اللہ علیہ وسلم مسجد میں تشریف فرما تھے، آپ صلی اللہ علیہ وسلم کے اردگرد اصحاب تھے کہ ایک دراز قد اعراب لمبی گردن والی اونٹنی پر آیا، لوگوں کی گردنیں پھلانگیں، رسول اللہ صلی اللہ علیہ وسلم کے سامنے جا کر کھڑا ہو گیا اور گفتگو کرنے لگا، کئی بار اس کی طبیعت میں جوش آیا، یہاں تک کہ اسے سکون مل گیا تو اس نے چند اشعار سنائے جس پر نبی علیہ السلام نے فرمایا: \"تم وہب بن سماع ہو؟\" اس نے کہا: ہاں! میں وہب ابن سماع عوفی ہوں، سخت دفاع کرنے والا اور روکنے والا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"تم وہی ہو نا جس کی زیادہ تر قوم جنگوں میں ضائع ہو گئی\"۔ پھر اس کے حالات کی کئی چیزوں کا ذکر کیا تو اس نے کہا: چیز کے بعد اس کا اثر نہیں رہتا، میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی معبود نہیں اور میں گواہی دیتا ہوں کہ آپ اللہ کے رسول ہیں۔ پھر اپنے بت کے ساتھ اپنا قصہ ذکر کیا، اور آپ صلی اللہ علیہ وسلم کے سامنے یہ اشعار کہے:\n\"اے وہب! اے ابن مالک! جلدی نہ کر، ایسی چیز آچکی ہے جسے دور نہیں کیا جا سکتا۔\"\nپھر اشعار ذکر کر کے، فرماتے ہیں: وہ اسلام لائے اور ان کا اسلام سنور گیا۔","",{"fn":"(1) اسد الغابہ (۵۴۸۳) الاستيعاب (۲۷۶۰) تجرید (۱۳۱/۲)\n(2) الاستيعاب (۱۲۱/۳)"}],[7789,"§۹۱۶۷ ۔ وہب بن عبداللہ\nابن سعد بن ابی سرح، زبیر بن بکار کا قول ہے: موتہ کے دن قتل ہوئے، عبداللہ بن سعد بن ابی سرح اور ان کی اولاد کا ذکر کرنے کے بعد فرمایا، پھر فرمایا: ابو سرح وہب کی اولاد میں سے وہب بن عبداللہ ہیں، پھر ان کا ذکر کیا، ابن عساکر رضی اللہ عنہ نے ان کا تعاقب کیا ہے کہ موتہ میں وہب بن سعد شہید ہوئے۔\nمیں کہتا ہوں: احتمال ہے کہ وہ دونوں اکٹھے شہید ہوئے ہوں اور ان کا نام اپنے چچا وہب کے نام پر رکھا گیا ہو۔"],[7790,"§۹۱۶۸ ۔ وہب بن عبداللہ\n(1) ابن قارب، ابن حبان کا قول ہے: انہیں شرف صحابیت حاصل ہے، ابو نعیم کا قول ہے: شرف صحابیت اور رؤیت قارب اور ان کے بیٹے عبداللہ کو حاصل ہے، رہے وہب تو انہوں نے اپنے والد کے حوالے سے روایت کی، فرماتے ہیں: میں نے اپنے والد کے ساتھ حج کیا۔(2)","",{"fn":"(1) اسد الغابہ (۵۴۸۵) تجرید (۱۳۱/۲)\n(2) کنز العمال (۳۸۰۰۷) جامع المسانید والسنن (۴۰۳/۱۲)"}],[7791,"§۹۱۶۹ ۔ وہب بن عبداللہ\n(1) ابن مسلم بن جنادہ بن حبیب بن سواءہ سوائی، ابن عامر بن صعصعہ، ابو جحیفہ سوائی۔ نبی کریم صلی اللہ علیہ وسلم کے پاس آخری عمر میں آئے اور آپ صلی اللہ علیہ وسلم سے احادیث یاد کیں۔ پھر اس کے بعد سیدنا علی رضی اللہ عنہ کے ساتھی تھے، جب وہ خلیفہ بنے تو انہوں نے کوفہ کی پولیس کا نگران بنایا تھا۔\nصحیح میں ان سے مروی روایت ہے: میں نے نبی کریم صلی اللہ علیہ وسلم کو دیکھا، وہ حسن بن علی رضی اللہ عنہما کے مشابہ تھے، آپ نے ہمیں تیرہ(۱۳) اونٹنیاں دینے کا حکم فرمایا۔ ہمارے اونٹنیاں لینے سے پہلے آپ صلی اللہ علیہ وسلم وفات پا گئے۔ سیدنا علی رضی اللہ عنہ نے ان کا نام وہب الخیر رکھا۔\nانہوں نے نبی کریم صلی اللہ علیہ وسلم اور سیدنا علی اور سیدنا براء بن عازب رضی اللہ عنہم سے روایت کی، ان سے ان کے بیٹے: عون، شعبی، ابو اسحاق سبیعی، سلمہ بن کہیل، اسماعیل بن ابی خالد، علی بن ارقم اور حکم بن عیینہ وغیرہ نے روایت کیا۔\nواقدی کا قول ہے: عراق پر بشر کی گورنری میں وفات پائی، ابن حبان کا قول ہے: ۲۶ھ میں وفات پائی۔","",{"fn":"(1) اسد الغابہ (۵۴۸۶) تجرید (۱۳۱/۲)"}],[7792,"§۹۱۷۰ ۔ وہب بن عبداللہ\nابن محصن اسدی، ابو سنان ہیں۔ اپنی کنیت سے مشہور ہیں۔ ابن حبان کا قول ہے: انہیں شرف صحابیت حاصل ہے، کنیتوں میں ان کا ذکر آئے گا، بعض کا قول ہے: ان کا نام عبداللہ بن وہب ہے، بعض کا قول ہے: وہ وہب بن محصن ہیں، پہلے قول پر مسلم نے اعتماد کیا۔"],[7793,"§۹۱۷۱ ۔ وہب بن عثمان\n(1) ابن ابی طلحہ عبدری، ان کا والد احد کے دن حالت شرک میں قتل ہوا۔ انہوں نے بنت عبد بن زمعہ سے نکاح کیا اس سے عبدالرحمن کی ولادت ہوئی۔ شیبہ اور عبداللہ بھی ان کے بیٹے ہیں، زبیر بن بکار نے ان کا ذکر کیا ہے، فرماتے ہیں: انہوں نے ام جمیل بنت شیبہ بن ربیعہ سے شادی کی۔","",{"fn":"(1) تجرید (۱۳۱/۲)"}],[7794,"§۹۱۷۲ ۔ وہب بن عمرو اسدی\n(1) یونس بن بکیر نے مغازی میں آغاز ہجرت میں ہجرت کرنے والوں میں ان کا ذکر کیا ہے، ابو نعیم نے جائز کہا ہے کہ وہ ثقف ابن عمرو ہوں، احتمال ہے کہ وہ ان کے بھائی ہوں۔","",{"fn":"(1) اسد الغابہ (۵۴۸۱) تجرید (۱۳۱/۲)"}],[7795,"§۹۱۷۳ ۔ وہب بن عمیر\nابن وہب بن خلف بن وہب بن حذافہ بن جمح قرشی جمحی۔ موطا میں، بحوالہ ابن شہاب مروی ہے کہ انہیں یہ بات معلوم ہوئی کہ نبی کریم صلی اللہ علیہ وسلم کے زمانے میں خواتین ایسی بھی تھیں کہ اپنے علاقے میں اسلام لائیں اور انہوں نے ہجرت نہیں کی، ان کے شوہر کافر تھے، ان میں سے ولید بن مغیرہ کی بیٹی جو عفوان بن امیہ کی زوجہ تھیں، فتح مکہ کے موقع پر اسلام لائیں، ان کا شوہر صفوان ابن امیہ بھاگ گیا، رسول اللہ صلی اللہ علیہ وسلم نے اس کی طرف اس کے چچا زاد وہب بن عمیر کو بھیجا اور اسے اسلام کی دعوت دی۔۔۔۔ پھر حدیث ذکر کی۔ معروف یہ ہے کہ یہ قصہ ان کے والد عمیر بن وہب کا تھا، اسی طرح موسی بن عقبہ وغیرہ نے اہل مغازی میں ان کا ذکر کیا ہے۔\nابو سعید بن یونس نے ان کا ذکر کیا ہے، فرماتے ہیں: فتح مصر میں شریک ہوئے، بنی جمح کی حویلی میں ایک حوض تھا اس میں پانی جمع ہوتا تھا، سیدنا عمرو بن عاص کہنے لگے: میرے بھتیجے یعنی وہب بن عمیر کا میری جانب خط کھینچ دو، پھر اس حوض کا دہانہ بند کر دیا گیا اور اس کا نقشہ کھینچ دیا گیا، یوں یہ بنو جمح کی حویلی بن گئی، فرماتے ہیں: غزوہ عموریہ ۲۳ھ میں وہب بن عمیر کو مصر کے سمندر کا نگران مقرر کر دیا گیا۔\nبخاری رحمہ اللہ نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، ان سے کوئی حدیث مروی نہیں، ابو بکر بن درید نے اخبار منثورہ میں کہا: وہب بن عمیر لوگوں میں سب سے زیادہ حافظے والے تھے، قریش ان کے بہت زیادہ حافظے کی وجہ سے کہتے تھے، ان کے دو دل ہیں، اللہ تعالیٰ نے یہ آیت نازل کی: ﴿اللہ تعالیٰ نے کسی شخص کے سینے میں دو دل نہیں بنائے ﴾(1)\nجب بدر کا دن ہوا تو شکست کھا کر آ گئے، ایک جوتا ان کے ہاتھ میں تھا، اور دوسرا جوتا پاؤں میں تھا، لوگوں نے پوچھا: لوگوں کا کیا ہوا؟ انہوں نے کہا: شکست کھا گئے، انہوں نے کہا: تمہارا جوتا کہاں ہے؟ انہوں نے کہا: میرے پاؤں میں ہے۔ انہوں نے کہا: تمہارے ہاتھ میں کیا ہے؟ انہوں نے کہا: مجھے معلوم نہیں، تو انہیں معلوم ہو گیا کہ ان کے دو دل نہیں ہیں۔\nثعلبی رحمہ اللہ نے یہ قصہ جمیل بن معمر کے بارے میں ذکر کیا ہے، اور جو شخص ان سے ملا اور سوال کیا وہ ابو سفیان تھے، ابن کلبی نے اپنی تفسیر میں، بحوالہ ابن عباس رضی اللہ عنہما مسند روایت کیا ہے، لیکن فرماتے ہیں: جمیل بن اسد ہیں۔","",{"fn":"(1) سورۃ احزاب الآیۃ (۴)"}],[7796,"§۹۱۷۴ ۔ وہب بن قابس\n(1) یا قابوس مزنی، ابن سکن نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور بطریق محمد بن طلحہ، بحوالہ محمد بن حسین بن عمرو بن سعد بن معاذ، عن ابیہ، عن جدہ نقل کیا ہے، فرماتے ہیں: مزینہ کا وہب بن قابس نامی ایک آدمی عرج مقام پر ملا، اسلام لائے اور بیعت کی، پھر اپنے گھر والوں کے پاس ٹھہر گئے یہاں تک کہ جب احد کا دن ہوا تو اپنی بکریوں کی رسی پکڑ کر نکلے، یہاں تک کہ مدینہ پہنچے تو اسے خالی پایا، انہوں نے نبی کریم صلی اللہ علیہ وسلم کے بارے میں پوچھا، لوگوں نے کہا: وہ احد کے قریب جنگ کے لیے گئے ہیں، اس نے ان کی رسی پھینک دی اور احد کی طرف چلے، اتنے میں گھوڑے سامنے آئے، نبی کریم صلی اللہ علیہ وسلم نے فرمایا: \"ان گھوڑوں کو ہم سے کون دور کرے گا؟ اللہ اسے جنت میں میرا ساتھی بنائیں گے\"۔ وہب آگے بڑھے اور تلواروں کے وار سے انہیں واپس لوٹا دیا، یہاں تک کہ انہوں نے تین مرتبہ ایسا ہی کیا اور شہید ہو گئے۔ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: \"اسے چھوڑ دو یہاں تک کہ ہم فارغ ہوں، جب فارغ ہوئے تو انہیں تلاش کیا لیکن وہ نہ ملے\"۔ سیدنا عمر رضی اللہ عنہ نے فرمایا: وہب بن قیس سے بڑھ کر مجھے کوئی شخص محبوب نہیں کہ میں اللہ تعالیٰ کا سامنا اس کے عمل سے کروں۔\nواقدی رحمہ اللہ نے اسی مفہوم میں ان کا ذکر کیا ہے، حارث بن عقبہ بن قابس کی سوانح میں ان کا ذکر گزر چکا ہے۔\nمیں نے صاعد بغوی کی کتاب الفصوص میں پڑھا، فرماتے ہیں: سیدنا عمر رضی اللہ عنہ نے فرمایا کہ اس امت میں سب سے زیادہ مجھے یہ پسند ہے کہ میں اللہ تعالیٰ سے اس کے اعمال نامے سے ملوں، آپ نے یہ بات وہب بن قابس مزنی کے بارے میں فرمائی، پھر مختصر قصہ ذکر کیا۔","",{"fn":"(1) اسد الغابہ (۵۴۹۰) استیعاب (۲۷۶۴) تجرید (۱۳۱/۲)"}],[7797,"§۹۱۷۵ ۔ وہب بن قیس\nابن ابان ثقفی۔ ان کے بھائی سفیان بن قیس کی سوانح میں ان کا ذکر گزر چکا ہے۔"],[7798,"§۹۱۷۶ ۔ وہب بن کلدہ\nبنو عبداللہ بن غطفان سے ہیں، ابن اسحاق نے بدر میں شریک ہونے والوں میں ان کا ذکر کیا ہے۔"],[7799,"§۹۱۷۷ ۔ وہب بن مالک\nابن سواد بن جذیمہ بن دارع بن عدی بن تمیم دار داری، تمیم کے قبیلے سے ہیں، ابن اسحاق نے تمیم داری کے ساتھ آنے والوں میں ان کا ذکر کیا ہے، اسلام لائے۔"],[7800,"§۹۱۷۸ ۔ وہب بن محصن اسدی\nوہب بن عبداللہ بن محصن ہیں، ان کا ذکر گزر چکا ہے، بعض نے انہیں اپنے دادا کی طرف منسوب کیا ہے۔"],[7801,"§۹۱۷۹ ۔ وہب (بے نسبت)\nمستغفری نے ان کا ذکر کیا ہے، فرماتے ہیں: میرا خیال ہے انہیں شرف صحابیت حاصل ہے۔"],[7802,"§۹۱۸۰ ۔ وہب\nدوسرے ہیں، بے نسبت۔ بغوی نے ان کا ذکر کیا ہے اور بطریق مجالد، بحوالہ وہب ذکر کیا ہے، فرماتے ہیں: ایک اعرابی نبی کریم صلی اللہ علیہ وسلم کے پاس آیا آپ عرفہ میں مقیم تھے، اس نے آپ سے آپ کی چادر مانگی، آپ نے وہ اسے عطا کر دی، وہ اسے لے کر چلا گیا، پھر آپ صلی اللہ علیہ وسلم نے فرمایا: \"سوال کرنا جائز نہیں سوائے ایسے فقیر کی وجہ سے جو ہلاک کر دے یا ایسا قرض جو لاچار کر دے\"۔"],[7803,"§۹۱۸۱ ۔ وہیب\nابن اسود، وہب میں ان کا ذکر گزر چکا ہے۔"],[7804,"§۹۱۸۲ ۔ وہیب بن سماع\nوہب انصاری میں ان کا ذکر گزر چکا ہے۔"],[7805,"§۹۱۸۳ ۔ ولید بن عبادہ\n(1) ابن صامت انصاری، ابن سعد کا قول ہے: نبی کریم صلی اللہ علیہ وسلم کے زمانے میں ولادت ہوئی، انہوں نے اپنے والد، ابو الیسر انصاری وغیرہ سے روایت کی۔\nان سے ان کے بیٹے عبادہ، محمد بن یحییٰ بن حبان، عطاء، سلیمان بن حبیب، عمارہ بن عمیر وغیرہ نے روایت کی ہے۔\nابن سعد کا قول ہے: خلافت عبد الملک میں فوت ہوئے، وہ ثقہ اور کم احادیث روایت کرنے والے ہیں۔\nمیں کہتا ہوں: اس روایت میں وہم ہے کہ انہیں شرف صحابیت حاصل ہے، احمد کے ہاں بطریق سیار، بحوالہ عبادہ بن ولید، عن ابیہ مروی ہے، فرماتے ہیں: ہم نے رسول اللہ صلی اللہ علیہ وسلم سے حکم سننے اور تنگی فراخی، نشاط اور ناپسندیدگی میں اطاعت کرنے پر بیعت کی۔۔۔۔(2) (الحدیث)\nیہ حدیث عبادہ کی ہے جو ان کے والد ہیں، شاید ان کے قول عن ابیہ سے مراد عن جدہ ہے، اسے موطا، شیخین، احمد نے بھی اور نسائی نے کئی طرق سے، بحوالہ عبادہ روایت کیا ہے، ترمذی نے عبدالواحد بن سلیم کے طریق سے نقل کیا ہے کہ میں مکہ آیا اور عطاء بن ابو رباح سے ملا، عطاء نے فرمایا: میں ولید بن عبادہ بن صامت سے ملا جو رسول اللہ صلی اللہ علیہ وسلم کے صحابی ہیں، میں نے کہا: آپ کے والد نے وفات کے وقت کیا وصیت کی تھی؟ پھر حدیث ذکر کی، اگر اسے ولید کی صفت بناتے ہوئے نصب کے ساتھ پڑھا جائے تو اس کا تقاضا ہے کہ وہ صحابی ہوں، اگر عبادہ کی صفت بناتے ہوئے جر کے ساتھ پڑھا جائے تو کوئی اشکال نہیں۔","",{"fn":"(1) اسد الغابہ (۵۴۶۶)، استیعاب (۲۷۴۸)، تجرید (۱۲۹/۲)\n(2) بخاری (۷۱۹۹، ۷۲۰۰) مسلم (۶۱) نسائی (۴۱۶۰، ۴۱۶۱، ۴۱۶۲) ابن ماجہ (۲۸۶۶)"}],[7806,"§۹۱۸۴ ۔ ولید بن عدی اصغر\nابن خیار بن عدی بن نوفل قرشی نوفلی، ان کا والد حالت کفر میں مر گیا۔ ولید کا یہ بیٹا تھا، اس کا نام عمارہ تھا، اپنے گھرانے کے شاعر تھے۔ زبیر بن بکار نے کتاب النسب میں ان کا ذکر کیا ہے۔"],[7807,"§۹۱۸۵ ۔ ولید بن ولید\n(1) ابن ولید بن مغیرہ، عبداللہ نامی لوگوں میں ان کا نام گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۲۷۲) استیعاب (۲۷۵۳) تجرید (۱۳۰/۲)"}],[7808,"§۹۱۸۶ ۔ ولید بن یزید\n(1) ابن عدی بن ربیعہ بن عبدالعزی بن عبد شمس، ابن کلبی رحمہ اللہ نے ان کا ذکر کیا ہے، فرماتے ہیں: ان کے بیٹے عبداللہ جمل کے دن سیدہ عائشہ رضی اللہ عنہا کے لشکر میں شہید ہوئے، عبداللہ، ابن داریہ کے نام سے معروف تھے۔","",{"fn":"(1) اسد الغابہ (۵۴۶۷) استیعاب (۲۷۴۹)"}],[7809,"§۹۱۸۷ ۔ ابن یسار\nابن یسار بن ثعلبہ بن نبھان بن لام طائی، انہوں نے نبوت کا زمانہ پایا۔ ان کا بیٹا جہم ان لوگوں میں سے تھا جنہوں نے کوفہ میں اونٹوں کو چارہ ڈالنے میں بددیانتی کی تھی اور حجاج کے زمانے میں سمندروں کے لیے بوجھ لادتے تھے۔\nان پر سبیب بن عمرو بن کریب نے غارت گری کی جو ایک قصے میں ہے، جس کی طرف عمرو بن کریب میں اشارہ گزر چکا ہے، ابن کلبی رحمہ اللہ نے ان کا ذکر کیا ہے۔"],[7810,"§۹۱۸۸ ۔ وعوعہ بن سعید\nابن قرط بن عبد بن ابی بکر بن کلاب، انہوں نے نبوت کا زمانہ پایا، ان کے بیٹے مربع نے جریر کی مدد کی، فرزدق نے اسے ڈانٹا تو کہا:\n\"فرزدق کا گمان ہے کہ مربع عنقریب قتل ہو گا، اے مربع لمبی سلامتی کی خوشخبری ہو\"۔\nابن کلبی رحمہ اللہ نے ان کا ذکر کیا ہے۔"],[7811,"§۹۱۸۹ ۔ وفاء بن اشعر تمیمی\n(1) ابن لسان محمرہ کے نام سے مشہور ہیں، فصاحت کی وجہ سے مشہور تھے، ان کی کنیت ابو کلاب تھی۔ معمرین میں ان کا ذکر ہے۔ یہ وہی ہیں جنہوں نے معاویہ سے کہا: جب انہوں نے ان سے ان کے علم کے بارے میں پوچھا تھا، میں نے اسے سوال کرنے والی زبان اور عقلمند دل سے حاصل کیا ہے۔","",{"fn":"(1) تجرید (۱۳۰/۲)"}],[7812,"§۹۱۹۰ ۔ ولید بن محصن دریکی\nتصغیر کے ساتھ ہے، دھیمہ نے روہ میں ذکر کیا ہے کہ وہ صاحب رائے اور عقلمند تھے، انہوں نے بلیغ خطبہ دیا جس میں ملوک کندہ کو مرتد ہونے سے منع کیا، انہوں نے قبول نہ کیا، ان کی ہتک کی اور وہاں سے نکال دیا۔"],[7813,"§۹۱۹۱ ۔ وہب بن اسود\n(1) سیدنا عمر رضی اللہ عنہ سے ملے، ان سے ابن ابی ملیکہ نے روایت کیا ہے، بخاری نے ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۴۷۳) استیعاب (۲۷۵۴)"}],[7814,"§۹۱۹۲ ۔ وہب بن اکیدر دومہ\nابن عساکر رحمہ اللہ نے عمرو بن یحییٰ بن وہب بن اکیدر کی سوانح میں، بطریق عمرو بن محمد بن حسن، بحوالہ عمرو بن یحییٰ بن وہب، عن ابیہ، عن جدہ ذکر کیا ہے، فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم نے میرے والد کی طرف خط لکھا، اس کے ساتھ مہر نہ تھی۔ آپ صلی اللہ علیہ وسلم نے مٹی کی مہر لگائی۔"],[7815,"§۹۱۹۳ ۔ وہب بن خالد\nابن عامر بن غاضرہ سعدی، مولیٰ عبید، والد ابو جزہ، شاعر، مخضرم ہیں۔ محمد بن سلام جمحی نے، بحوالہ یونس بن عبید کہا، ابو جزہ کے والد عبید قیدی تھے، انہیں ذی المجاز کے بازار میں جاہلیت میں بیچا، اسے وہب بن خالد نے خرید لیا، وہ ان کے پاس بہت عرصہ رہے، ان کے اونٹوں کو چراتے تھے۔ پھر عبید نے اپنے مولیٰ کی اونٹنی کے تھن پر مارا اور اسے زخمی کر دیا وہب نے ان کے چہرے پر طمانچہ مارا، وہ ناراض ہو کر سیدنا عمر رضی اللہ عنہ کے پاس گئے۔\nانہوں نے کہا: اے امیر المومنین! میں بنو ظفر کا آدمی ہوں، جاہلیت میں مجھے قیدی بنا لیا گیا، میں معروف النسب ہوں، اسلام میں عربی کو غلام نہیں بنایا جاتا، ان کے مولیٰ آئے اور کہا: اے امیر المومنین! میرا یہ غلام میرے مال کا نگران ہے۔ اس نے برا کیا، اس لیے میں نے اسے مارا ہے۔ اللہ کی قسم! مجھے معلوم نہیں کہ اس کے علاوہ میں نے اسے کبھی مارا ہو، آدمی اپنے بیٹے کو اس سے زیادہ مارتا ہے تو کیا اس سے کم اپنے غلام کو نہیں مار سکتا؟ میں گواہ ہوں کہ وہ اللہ کی رضا کے لیے آزاد ہے۔ سیدنا عمر رضی اللہ عنہ نے فرمایا: اس نے تم پر احسان کیا ہے اور گالی کی مشقت کو دور کر دیا ہے، اگر تمہیں پسند ہو تو اس کے ساتھ رہو، اس کا تم پر احسان ہے، اگر تم پسند کرو تو اپنی قوم کے پاس چلے جاؤ، تو وہ ان کے ساتھ رہے، پھر زینب بنت عرفطہ مزنیہ سے نکاح کیا، اس سے ان کے ہاں ابو جزہ اور اس کا بھائی پیدا ہوئے، ابو جزہ نے اپنے والد کے حوالے سے، انہوں نے سیدنا عمر رضی اللہ عنہ سے ارتداد کے سال ان کے پانی طلب کرنے کا قصہ نقل کیا ہے۔"],[7816,"§۹۱۹۴ ۔ وادع\n(1) تجرید میں ان کا ذکر بحوالہ ابن قانع ہے۔ وہ وازع زاء کے ساتھ ہے۔ پہلے گزر چکا ہے۔","",{"fn":"(1) تجرید (۱۲۵/۲)"}],[7817,"§۹۱۹۵ ۔ واسع بن حبان\n(1) بغوی رحمہ اللہ نے ان کا ذکر کیا ہے، اور بطریق حبان بن واسع بن حبان، عن ابیہ نقل کیا ہے کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم کو اپنے\nسر کا مسح نئے پانی سے کرتے ہوئے دیکھا۔(2) یہ خطا ہے جو رہ جانے سے پیدا ہوئی، وہ یہ ہے کہ مسلم نے یہ روایت اسی سند سے نقل کی ہے، فرماتے ہیں: بحوالہ حبان بن واسع، عن ابیہ، عن عبداللہ بن زید، اسے طویل نقل کیا ہے، اسے ابو داؤد، ترمذی نے مختصر نقل کیا ہے۔\nپہلی قسم میں واسع بن حبان کی سوانح میں گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۴۲۸)\n(2) ابو داؤد (۱۲۰) ترمذی (۳۵) احمد (۳۹/۴، ۴۰/۴) جامع المسانید والسنن (۲۴۷/۱۲)"}],[7818,"§۹۱۹۶ ۔ واصلہ بن حبان\n(1) واثلہ میں گزر چکے ہیں، بعض نے لفظی غلطی کی ہے۔","",{"fn":"(1) تجرید (۱۲۵/۲)"}],[7819,"§۹۱۹۷ ۔ واقد بن عبداللہ یربوعی\n(1) ابن امین کا قول ہے: ابن مندہ نے ان کے اور واقد بن عبداللہ خطی کے درمیان فرق کیا ہے۔ وہ دونوں ایک ہیں۔","",{"fn":"(1) اسد الغابہ (۵۴۳۲) تجرید (۱۲۶/۲)"}],[7820,"§۹۱۹۸ ۔ واقد\n(1) بے نسبت۔ ابن مندہ کا قول ہے: ابو مسعود نے، بحوالہ عبداللہ بن واقد، عن ابیہ ان کا ذکر کیا ہے۔ فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اپنی عورت کو مساجد سے منع نہ کرو\"۔(2)\nابو مسعود کا قول ہے: وہ میرے نزدیک وہم ہے، وہ واقد بن عبداللہ بن عمر، عن ابیہ ہیں۔\nمیں کہتا ہوں: ایسا ہی ہے جیسا انہوں نے کہا:","",{"fn":"(1) اسد الغابہ (۵۴۲۵)\n(2) المعجم الکبیر (۳۹۹/۱۲) السنن الکبریٰ (۱۳۲/۲) تعلیق التعلیق (۲۵۳)"}],[7821,"§۹۱۹۹ ۔ وائل القیل\n(1) ابن شاہین ان کے ذکر کرنے میں تنہا ہیں، بطریق ابن اسحاق، بحوالہ وائل قیل نقل کیا ہے، فرماتے ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ اپنے دائیں ہاتھ کو بائیں ہاتھ پر نماز میں رکھے ہوئے تھے۔(2) ابو موسیٰ نے ذیل میں فرمایا: وہ وائل بن حجر ہیں، ان میں کوئی شک نہیں۔","",{"fn":"(1) اسد الغابہ (۵۴۳۸) تجرید (۱۲۶/۲)\n(2) مسند احمد (۳۱۶/۴) مجمع الزوائد (۱۰۴/۲) الکامل فی الضعفاء (۲۴۰۱/۶)"}],[7822,"§۹۲۱۱ ۔ یاسر العنسی\nآل مخزوم کے حلیف، یمن سے آئے تھے، ابو حذیفہ بن المغیرہ کے حلیف بنے تو انہوں نے اپنی باندی سے ان کی شادی کر دی جس کا نام سمیہ تھا۔ جس سے عمار نامی لڑکا پیدا ہوا۔ تو ابو حذیفہ نے اسے آزاد کر دیا، پھر عمار اور ان کے والد اسلام کی طرف سبقت کرنے والوں میں سے تھے۔ حاکم کی بطریق عقیل عن الزہری عن اسماعیل بن عبداللہ بن جعفر بحوالہ ان کے والد روایت ہے۔ رسول اللہ صلی اللہ علیہ وسلم کا یاسر، عمار اور سیدنا عمار کی والدہ کے ہاں سے گزرا ہوا جنہیں اللہ تعالیٰ کی خاطر اذیتیں دی جا رہی تھیں۔ آپ نے فرمایا: یاسر کے گھرانے والو! صبر کرو! یاسر کے گھرانے والو! صبر سے کام لو تمہارا مقام جنت ہے۔(1)\nامام احمد رحمہ اللہ نے کتاب الزہد میں بطریق یوسف بن مایل مرسل روایت کی ہے اور حارث نے اپنی مسند میں، حاکم اور ابن مندہ نے بطریق اعمش عن سالم بن ابی الجعد عن عثمان روایت کی ہے جو منقطع ہے۔ جبکہ حاکم نے اور طبرانی نے الاوسط میں بروایت ابی زبیر عن جابر مرفوع نقل کی ہے جسے ابن کلبی نے تفسیر میں ابو صالح سے، بحوالہ ابن عباس رضی اللہ عنہما مرفوعاً نقل کیا ہے اور اس میں یہ اضافہ نقل کیا۔ اور عبداللہ بن یاسر اور مزید یہ الفاظ ہیں: ابو جہل بدبخت نے سیدہ سمیہ کی ناف کے نیچے نیزہ مارا جس سے وہ فوت ہو گئیں اور یاسر تکلیفیں اٹھاتے رخصت ہو گئے، اور عبداللہ کے تیر لگا جس سے وہ گر گئے۔","",{"fn":"(1) البدایۃ والنہایۃ (۵۹/۳)"}],[7823,"§۹۲۱۲ ۔ یاسر بن سوید الجہنی\n(1) ابن حبان، ابن اسکن اور طبرانی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، ان کی حدیث ان کی اولاد سے مروی ہے۔ ابن ابی حاتم رحمہ اللہ لکھتے ہیں: عبداللہ بن داؤد بن دلہاث بن مبرع بن یاسر اپنے والد سے، بواسطہ اپنے دادا وہ بحوالہ اپنے والد نقل کرتے ہیں، ان کے متعلق جرح کا ذکر نہیں کیا۔ ابن اسکن اور طبرانی نے اسی سند سے جو مسرع بن یاسر تک پہنچتی ہے کہ ان کے والد نے ان سے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے انہیں کسی مہم پر روانہ فرمایا، انہیں ان کی والدہ رسول اللہ صلی اللہ علیہ وسلم کے پاس لائیں آپ نے ان پر اپنا دست\nرحمت پھیرا اور یہ دعا دی: \"اللہ ان کے مرد بڑھا، ان کے گناہ گھٹا، انہیں کسی گناہ میں نہ پھنسا، اور فرمایا: اس کا نام مسرع رکھنا اس لیے کہ اس نے اسلام میں جلدی کی ہے\"۔(2)","",{"fn":"(1) اسد الغابہ (۵۴۹۵) تجرید (۱۳۲/۲)\n(2) مجمع الزوائد (۴۱۲/۹) المعجم الکبیر (۲۲/۷۱) کنز العمال (۳۳۶۶۶) جمع الجوامع (۱۰۰۲۵)"}]])